        start = prev_t + prev_off if prev_t != -float('inf') else -10**18
        end = t + prev_off
        ranges.append((start, end, prev_off))

        if off > prev_off:
            # Gap
            gap_start = t + prev_off
            gap_end = t + off
            gaps.append((gap_start, gap_end, prev_off, off))
        elif off < prev_off:
            # Overlap
            overlap_start = t + off
            overlap_end = t + prev_off
            overlaps.append((overlap_start, overlap_end, prev_off, off))

        prev_t = t
        prev_off = off

    # Last range
    start = prev_t + prev_off if prev_t != -float('inf') else -10**18
    end = 10**18
    ranges.append((start, end, prev_off))

    # Sort lists
    ranges.sort()
    gaps.sort()
    overlaps.sort()

    # Extract starts for bisect
    range_starts = [r[0] for r in ranges]
    gap_starts = [g[0] for g in gaps]
    overlap_starts = [o[0] for o in overlaps]

    INF = 10**18

    def find_in_ranges(w):
        idx = bisect.bisect_right(range_starts, w)
        if idx > 0:
            r = ranges[idx-1]
            if w < r[1]:
