        idx = bisect.bisect_right(overlap_starts, w)
        if idx > 0:
            o = overlaps[idx-1]
            if w < o[1]:
                return o
        return None

    def resolve(w, fold):
        # Check overlaps
        o = find_in_overlaps(w)
        if o:
            off_before, off_after = o[2], o[3]
            x1 = w - off_before
            x2 = w - off_after
            # x1 is earlier, x2 is later
            if fold == 0:
                return x1
            else:
