import bisect

def table_zone_eval(zone, ops):
    # Validate zone structure
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone structure")
    initial, transitions = zone

    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("Initial offset must be an int")
    if abs(initial) > 50400:
        raise ValueError("Initial offset out of range")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Transitions must be a list or tuple")

    parsed_transitions = []
    prev_t = -float('inf')
    prev_off = initial

    for t, off in transitions:
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("Transition time must be an int")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("Transition offset must be an int")
        if abs(off) > 50400:
            raise ValueError("Transition offset out of range")
        if abs(t) > 10**13:
            raise ValueError("Transition time out of range")
        if t <= prev_t:
            raise ValueError("Transitions must be strictly increasing")
        if t - prev_t < 172800:
            raise ValueError("Transitions must be at least 2 days apart")
        if abs(off - prev_off) > 86400:
            raise ValueError("Offset change too large")
        parsed_transitions.append((t, off))
        prev_t = t
        prev_off = off

    times = [t for t, _ in parsed_transitions]
    offsets = [off for _, off in parsed_transitions]
    n = len(times)

    def get_offset(x):
        idx = bisect.bisect_right(times, x) - 1
        if idx < 0:
            return initial
        return offsets[idx]

    def resolve(w, fold):
        if fold not in (0, 1):
            raise ValueError("Fold must be 0 or 1")

        candidates = []
        idx = bisect.bisect_right(times, w) - 1

        # Check relevant intervals for x
        for i in [idx-1, idx, idx+1]:
            if i < 0:
                off = initial
                x = w - off
                if n == 0 or x < times[0]:
                    candidates.append(x)
            elif i >= n:
                off = offsets[-1]
                x = w - off
                candidates.append(x)
            else:
                off = offsets[i]
                x = w - off
                t_start = times[i]
                t_end = times[i+1] if i+1 < n else float('inf')
                if t_start <= x < t_end:
                    candidates.append(x)

        if len(candidates) == 1:
            return candidates[0]
        elif len(candidates) == 2:
            return min(candidates) if fold == 0 else max(candidates)
        else:
            # 0 matches -> Gap
            for i in [idx-1, idx, idx+1]:
                if i < 0 or i >= n:
                    continue
                T, new_off = parsed_transitions[i]
                prev_off = offsets[i-1] if i > 0 else initial
                if new_off > prev_off:
                    w_start = T + prev_off
                    w_end = T + new_off
                    if w_start <= w < w_end:
                        return w - prev_off if fold == 0 else w - new_off
            raise ValueError("No match found for wall time")

    def wall_and_fold(x):
        offset = get_offset(x)
        w = x + offset
        idx = bisect.bisect_right(times, x) - 1
        is_later = False
        if idx >= 0:
            prev_off = offsets[idx-1] if idx > 0 else initial
            new_off = offsets[idx]
            if new_off < prev_off:
                T = times[idx]
                if w < T + prev_off:
                    is_later = True
        return w, 1 if is_later else 0

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Operation must be a list or tuple")
        if not isinstance(op[0], str):
            raise ValueError("Operation command must be a string")

        cmd = op[0]

        if cmd == "instant":
            if len(op) != 3:
                raise ValueError("Invalid instant operation")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Wall time must be int")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("Fold must be int")
            if fold not in (0, 1):
                raise ValueError("Fold must be 0 or 1")
            if abs(w) > 10**13:
                raise ValueError("Wall time out of range")
            results.append(resolve(w, fold))

        elif cmd == "wall":
            if len(op) != 2:
                raise ValueError("Invalid wall operation")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("Instant must be int")
            if abs(x) > 10**13:
                raise ValueError("Instant out of range")
            results.append(wall_and_fold(x))

        elif cmd == "add":
            if len(op) != 5:
                raise ValueError("Invalid add operation")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Wall time must be int")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("Fold must be int")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("Days must be int")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("Seconds must be int")
            if fold not in (0, 1):
                raise ValueError("Fold must be 0 or 1")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("Values out of range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(wall_and_fold(x2))

        else:
            raise ValueError("Unknown operation")

    return results

