            raise ValueError("Transitions must be strictly increasing")
        if t - prev_t < 172800:
            raise ValueError("Transitions must be at least 2 days apart")
        if abs(off - prev_off) > 86400:
            raise ValueError("Offset change too large")
        parsed_transitions.append((t, off))
        prev_t = t
        prev_off = off

    times = [t for t, _ in parsed_transitions]
    offsets = [off for _, off in parsed_transitions]
    n = len(times)

    # Precompute W_Ends and W_Starts for O(log n) resolve
    # W_Ends[i] = wall time just before transition i (using previous offset)
    # W_Starts[i] = wall time at/after transition i (using new offset)
    W_Ends = []
    W_Starts = []

    for i in range(n):
        t = times[i]
        new_off = offsets[i]
        prev_off = offsets[i-1] if i > 0 else initial
        W_Ends.append(t + prev_off)
        W_Starts.append(t + new_off)

    def get_offset(x):
        idx = bisect.bisect_right(times, x) - 1
        if idx < 0:
            return initial
        return offsets[idx]

    def resolve(w, fold):
        if fold not in (0, 1):
            raise ValueError("Fold must be 0 or 1")

        idx = bisect.bisect_right(W_Ends, w) - 1

        # Determine which interval w falls into
        if idx < 0:
            # Interval 0: x < times[0]
            x = w - initial
            # By construction w < W_Ends[0] => w < t0 + init_off => x < t0
            return x
        elif idx >= n - 1:
            # Interval n: x >= times[-1]
            x = w - offsets[-1]
            return x
        else:
            # w is between W_Ends[idx] and W_Ends[idx+1]
            # It belongs to interval idx+1: times[idx] <= x < times[idx+1]
            # Check for gap or overlap at transition idx
            T = times[idx]
            prev_off = offsets[idx-1] if idx > 0 else initial
            curr_off = offsets[idx]

            w_end = W_Ends[idx]
            w_start = W_Starts[idx]

            if w_end < w < w_start:
                # Gap: 0 matches
                return w - prev_off if fold == 0 else w - curr_off
            elif w_start <= w < w_end:
                # Overlap: 2 matches
                # fold 0 -> earlier instant (before T) -> x = w - prev_off
                # fold 1 -> later instant (after T) -> x = w - curr_off
                return w - prev_off if fold == 0 else w - curr_off
            else:
                # Continuous: 1 match
                x = w - offsets[idx]
                return x

    def wall_and_fold(x):
        offset = get_offset(x)
        w = x + offset
        idx = bisect.bisect_right(times, x) - 1
        is_later = False
        if idx >= 0:
            prev_off = offsets[idx-1] if idx > 0 else initial
            new_off = offsets[idx]
            if new_off < prev_off:
                T = times[idx]
                if T + new_off <= w < T + prev_off:
                    is_later = (x >= T)
        return w, 1 if is_later else 0

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Operation must be a list or tuple")
        if not isinstance(op[0], str):
            raise ValueError("Operation command must be a string")

        cmd = op[0]

        if cmd == "instant":
            if len(op) != 3:
                raise ValueError("Invalid instant operation")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Wall time must be int")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("Fold must be int")
            if fold not in (0, 1):
                raise ValueError("Fold must be 0 or 1")
            if abs(w) > 10**13:
                raise ValueError("Wall time out of range")
            results.append(resolve(w, fold))

        elif cmd == "wall":
            if len(op) != 2:
                raise ValueError("Invalid wall operation")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("Instant must be int")
            if abs(x) > 10**13:
                raise ValueError("Instant out of range")
            results.append(wall_and_fold(x))

        elif cmd == "add":
            if len(op) != 5:
                raise ValueError("Invalid add operation")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Wall time must be int")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("Fold must be int")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("Days must be int")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("Seconds must be int")
            if fold not in (0, 1):
                raise ValueError("Fold must be 0 or 1")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("Values out of range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(wall_and_fold(x2))

        else:
            raise ValueError("Unknown operation")

    return results

