def table_zone_eval(zone, ops):
    # Validate zone
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone structure")
    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial must be an int")
    if abs(initial) > 50400:
        raise ValueError("initial out of range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list or tuple")
    for t, off in transitions:
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("transition t must be an int")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("transition off must be an int")
        if abs(off) > 50400:
            raise ValueError("transition off out of range")
        if abs(t) > 10**13:
            raise ValueError("transition t out of range")
    N = len(transitions)
    if N > 0:
        T_ext = [t for t, off in transitions]
        OFF_trans = [off for t, off in transitions]
        # Check sorted and spacing
        for i in range(1, N):
            if T_ext[i] <= T_ext[i-1]:
                raise ValueError("transitions not strictly increasing")
            if T_ext[i] - T_ext[i-1] < 172800:
                raise ValueError("transitions too close")
        # Check offset changes
        if abs(OFF_trans[0] - initial) > 86400:
            raise ValueError("first offset change too large")
        for i in range(1, N):
            if abs(OFF_trans[i] - OFF_trans[i-1]) > 86400:
                raise ValueError("offset change too large")
    else:
        T_ext = []
        OFF_trans = []

    # Precompute arrays for fast lookup
    # OFF[i] is offset for interval i. Interval 0 is before first transition.
    OFF = [initial] + OFF_trans
    # L[i] = t_i + OFF[i] for i>0, L[0] = t_0 + initial
    L = [T_ext[i] + OFF[i] for i in range(N)]
    # R[i] = t_{i+1} + OFF[i] for i<N-1, R[N-1] = inf
    R = [T_ext[i+1] + OFF[i] for i in range(N-1)] + [float('inf')]

    # Validate ops
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops must be list or tuple")

    results = []

    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Each op must be list or tuple")
        name = op[0]
        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant op requires 3 arguments")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w must be int")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            if abs(w) > 10**13:
                raise ValueError("w out of range")

            idx = bisect.bisect_right(R, w) - 1
            if idx < 0:
                # Before first transition
                x = w - initial
                results.append(x)
                continue

            # Check interval idx
            if w >= L[idx]:
                x1 = w - OFF[idx]
                # Check if there's another match in idx-1 (overlap)
                # Overlap happens if OFF[idx-1] > OFF[idx] and w < R[idx-1]
                # But bisect ensures w >= R[idx-1], so no overlap possible in this branch.
                # Wait, if w < L[idx], we might be in a gap.
                # If w >= L[idx], it's a valid instant. Could there be another?
                # Only if w is in overlap [L[idx], R[idx-1]), but w >= R[idx-1] prevents this.
                # So unique match.
                results.append(x1)
            else:
                # w < L[idx]. Since w >= R[idx-1], this is a gap.
                # Gap between idx-1 and idx.
                a = OFF[idx-1]
                b = OFF[idx]
                if fold == 0:
                    results.append(w - a)
                else:
                    results.append(w - b)

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall op requires 2 arguments")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("x must be int")
            if abs(x) > 10**13:
                raise ValueError("x out of range")

            idx = bisect.bisect_right(T_ext, x) - 1
            if idx < 0:
                off = initial
            else:
                off = OFF[idx]
            w = x + off

            # Check if x is later match
            f = 0
            if idx > 0:
                prev_off = OFF[idx-1]
                if prev_off > off:
                    # Overlap exists. x is later if it falls in overlap part of interval idx
                    # Overlap part: [t_idx, t_idx + prev_off - off)
                    t_idx = T_ext[idx]
                    if x < t_idx + prev_off - off:
                        f = 1
            results.append((w, f))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add op requires 5 arguments")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w must be int")
            if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("days must be int")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("secs must be int")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("values out of range")

            w2 = w + 86400 * days
            x1 = table_zone_eval((initial, transitions), [("instant", w2, fold)])[0]
            x2 = x1 + secs
            # Reuse wall logic
            idx = bisect.bisect_right(T_ext, x2) - 1
            if idx < 0:
                off = initial
            else:
                off = OFF[idx]
            w2_wall = x2 + off
            f = 0
            if idx > 0:
                prev_off = OFF[idx-1]
                if prev_off > off:
                    t_idx = T_ext[idx]
                    if x2 < t_idx + prev_off - off:
                        f = 1
            results.append((w2_wall, f))
        else:
            raise ValueError("Unknown operation")

    return results

