        elif len(candidates) == 1:
            return candidates[0]
        else:
            # 0 matches -> Gap
            # Find gap transition
            # Gaps occur where offset rises: a -> b with b > a
            # Transition i changes offset from OFF[i] to OFF[i+1]
            # Gap interval [T_ext[i] + OFF[i], T_ext[i] + OFF[i+1])
            for i in range(N):
                a = OFF[i]
                b = OFF[i+1]
                if b > a:
                    gap_start = T_ext[i] + a
                    gap_end = T_ext[i] + b
                    if gap_start <= w < gap_end:
                        if fold == 0:
                            return w - a
                        else:
                            return w - b
            # Should not happen per spec
            raise ValueError("w not in any interval or gap")

