        if not isinstance(x, int) or isinstance(x, bool):
            raise ValueError("x must be int")
        if abs(x) > 10**13:
            raise ValueError("x out of range")

        k = bisect.bisect_right(T_ext, x)
        if k == 0:
            off = OFF[0]
            idx = 0
        else:
            off = OFF[k]
            idx = k

        w = x + off

        # Check if x is later match (fold=1)
