        if idx > 0:
            prev_off = OFF[idx-1]
            # Overlap if prev_off > off
            if prev_off > off:
                # Overlap interval in wall time: [T_ext[idx-1] + off, T_ext[idx-1] + prev_off)
                # x is later if it falls in the overlap part of interval idx
                # Overlap part in x: [T_ext[idx-1], T_ext[idx-1] + prev_off - off)
                t_idx = T_ext[idx-1]
                if x < t_idx + prev_off - off:
