    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list or tuple")

    T_ext = []
    OFF_trans = []
    N = len(transitions)

    for i, t_off in enumerate(transitions):
        if not isinstance(t_off, (list, tuple)) or len(t_off) != 2:
            raise ValueError("transition entry must be a list or tuple of 2 items")
        t, off = t_off

        if isinstance(t, bool) or not isinstance(t, int):
            raise ValueError("transition t must be an int")
        if isinstance(off, bool) or not isinstance(off, int):
            raise ValueError("transition off must be an int")

        if abs(t) > 10**13:
            raise ValueError("transition t out of range")
        if abs(off) > 50400:
            raise ValueError("transition off out of range")

        if i == 0:
            if abs(off - initial) > 86400:
                raise ValueError("first offset change too large")
        else:
            if t <= T_ext[i-1]:
                raise ValueError("transitions not strictly increasing")
            if t - T_ext[i-1] < 172800:
                raise ValueError("transitions too close")
            if abs(off - OFF_trans[i-1]) > 86400:
                raise ValueError("offset change too large")

        T_ext.append(t)
        OFF_trans.append(off)

    OFF = [initial] + OFF_trans

    # Precompute wall time interval boundaries
    W_start = []
    W_end = []

    for i in range(N + 1):
        start_t = T_ext[i-1] if i > 0 else -float('inf')
        end_t = T_ext[i] if i < N else float('inf')
        off = OFF[i]
        W_start.append(start_t + off)
        W_end.append(end_t + off)

    # Validate ops
    if not isinstance(ops, (list, tuple)):
        raise ValueError("ops must be list or tuple")

    results = []

