        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall op requires 2 arguments")
            x = op[1]
            results.append(to_wall(x))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add op requires 5 arguments")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if isinstance(w, bool) or not isinstance(w, int):
                raise ValueError("w must be int")
            if isinstance(fold, bool) or not isinstance(fold, int) or fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")
            if isinstance(days, bool) or not isinstance(days, int):
                raise ValueError("days must be int")
            if isinstance(secs, bool) or not isinstance(secs, int):
                raise ValueError("secs must be int")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("values out of range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(to_wall(x2))
        else:
            raise ValueError("Unknown operation")

    return results

