from typing import List, Tuple, Union

def table_zone_eval(zone: Tuple[Union[int, List[Tuple[int, int]]], List[Tuple[int, int]]], ops: List[List]) -> List:
    """
    Evaluates time zone operations based on a table of offset changes.

    Args:
        zone: A tuple (initial, transitions) where initial is the offset before the first transition,
              and transitions is a list of (t, off) tuples.
        ops: A list of operations to evaluate.

    Returns:
        A list of results from the operations.

    Raises:
        ValueError: If inputs are invalid.
    """
    # Validate zone structure
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("Invalid zone structure")

    initial, transitions = zone

    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("Initial offset must be an integer")
    if abs(initial) > 50400:
        raise ValueError("Initial offset out of range")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("Transitions must be a list or tuple")

    if len(transitions) > 100000:
        raise ValueError("Too many transitions")

    # Validate and process transitions
    valid_transitions = []
    prev_t = -float('inf')

    for i, trans in enumerate(transitions):
        if not isinstance(trans, (list, tuple)) or len(trans) != 2:
            raise ValueError("Invalid transition format")

        t, off = trans

        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("Transition time must be an integer")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("Transition offset must be an integer")
        if abs(off) > 50400:
            raise ValueError("Transition offset out of range")
        if abs(t) > 10**13:
            raise ValueError("Transition time out of range")

        if t <= prev_t:
            raise ValueError("Transitions must be strictly increasing")
        if t - prev_t < 172800 and i > 0:
            raise ValueError("Transitions must be at least 172800 seconds apart")
        if i > 0 and abs(off - transitions[i-1][1]) > 86400:
            raise ValueError("Offset change too large")

        valid_transitions.append((t, off))
        prev_t = t

    N = len(valid_transitions)
    L = [0] * (N + 1)
    R = [0] * (N + 1)
    offs = [0] * (N + 1)

    offs[0] = initial
    L[0] = -float('inf')

    for i in range(N):
        t, off = valid_transitions[i]
        offs[i+1] = off
        L[i+1] = t + off
        R[i] = t + off

    R[N] = float('inf')

    L_list = L
    R_list = R
    offs_list = offs
    times_list = [t for t, off in valid_transitions]

    def resolve(w: int, fold: int) -> int:
        """
        Resolves a wall time w to an instant x given fold.
        """
        if fold not in (0, 1):
            raise ValueError("Fold must be 0 or 1")

        idx = bisect.bisect_right(L_list, w)

        candidates = []

        # Check interval idx-1
        if idx - 1 >= 0:
            if w < R_list[idx - 1]:
                candidates.append(w - offs_list[idx - 1])

        # Check interval idx
        if idx <= N:
            if w < R_list[idx]:
                candidates.append(w - offs_list[idx])

        if not candidates:
            # Gap case
            if fold == 0:
                return w - offs_list[idx - 1]
            else:
                return w - offs_list[idx]
        else:
            if len(candidates) == 1:
                return candidates[0]
            else:
                candidates.sort()
                if fold == 0:
                    return candidates[0]
                else:
                    return candidates[1]

    def wall_time(x: int) -> Tuple[int, int]:
        """
        Computes the wall time and fold for instant x.
        """
        idx = bisect.bisect_right(times_list, x)
        off = offs_list[idx]
        w = x + off

        if idx > 0:
            T = valid_transitions[idx - 1][0]
            off_a = offs_list[idx - 1]
            off_b = offs_list[idx]
            if off_b < off_a:
                if T + off_b <= x < T + off_a:
                    return (w, 1)

        return (w, 0)

    def add_wall_time(w: int, fold: int, days: int, secs: int) -> Tuple[int, int]:
        """
        Adds days and seconds to a wall time.
        """
        w2 = w + 86400 * days
        x1 = resolve(w2, fold)
        x2 = x1 + secs
        return wall_time(x2)

    results = []

    for op in ops:
        if not isinstance(op, (list, tuple)) or len(op) < 1:
            raise ValueError("Invalid operation format")

        op_type = op[0]

        if op_type == "instant":
            if len(op) != 3:
                raise ValueError("Invalid instant operation")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Wall time must be an integer")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("Fold must be an integer")
            if abs(w) > 10**13:
                raise ValueError("Wall time out of range")
            if fold not in (0, 1):
                raise ValueError("Fold must be 0 or 1")

            result = resolve(w, fold)
            results.append(result)

        elif op_type == "wall":
            if len(op) != 2:
                raise ValueError("Invalid wall operation")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("Instant must be an integer")
            if abs(x) > 10**13:
                raise ValueError("Instant out of range")

            result = wall_time(x)
            results.append(result)

        elif op_type == "add":
            if len(op) != 5:
                raise ValueError("Invalid add operation")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("Wall time must be an integer")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("Fold must be an integer")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("Days must be an integer")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("Seconds must be an integer")
            if abs(w) > 10**13:
                raise ValueError("Wall time out of range")
            if abs(days) > 10**6:
                raise ValueError("Days out of range")
            if abs(secs) > 10**13:
                raise ValueError("Seconds out of range")
            if fold not in (0, 1):
                raise ValueError("Fold must be 0 or 1")

            result = add_wall_time(w, fold, days, secs)
            results.append(result)

        else:
            raise ValueError("Unknown operation type")

    return results

import heapq

def petri_starts(places, transitions, until, limit):
    # Input Validation
    if type(places) is not dict:
        raise ValueError("places must be a dict")
    if type(transitions) not in (list, tuple):
        raise ValueError("transitions must be a list or tuple")
    if type(until) is not int:
        raise ValueError("until must be an int")
    if type(limit) is not int:
        raise ValueError("limit must be an int")
    if not (0 <= until <= 10**12):
        raise ValueError("until out of range")
    if not (1 <= limit <= 2000):
        raise ValueError("limit out of range")
    if not (0 <= len(transitions) <= 50):
        raise ValueError("transitions count out of range")

    for k, v in places.items():
        if type(k) is not str or not k:
            raise ValueError("place name must be non-empty str")
        if type(v) is not int:
            raise ValueError("place tokens must be int")
        if not (0 <= v <= 10**6):
            raise ValueError("place tokens out of range")

    seen_names = set()
    for t in transitions:
        if type(t) is not tuple or len(t) != 6:
            raise ValueError("transition must be a tuple of 6 elements")
        name, inputs, outputs, duration, priority, servers = t

        if type(name) is not str or not name:
            raise ValueError("transition name must be non-empty str")
        if name in seen_names:
            raise ValueError("duplicate transition name")
        seen_names.add(name)

        if type(inputs) is not dict or not inputs:
            raise ValueError("inputs must be a non-empty dict")
        if type(outputs) is not dict:
            raise ValueError("outputs must be a dict")

        for place, w in inputs.items():
            if place not in places:
                raise ValueError("input place not in places")
            if type(w) is not int:
                raise ValueError("input weight must be int")
            if not (1 <= w <= 1000):
                raise ValueError("input weight out of range")

        for place, w in outputs.items():
            if place not in places:
                raise ValueError("output place not in places")
            if type(w) is not int:
                raise ValueError("output weight must be int")
            if not (1 <= w <= 1000):
                raise ValueError("output weight out of range")

        if type(duration) is not int:
            raise ValueError("duration must be int")
        if not (0 <= duration <= 10**12):
            raise ValueError("duration out of range")

        if type(priority) is not int:
            raise ValueError("priority must be int")

        if type(servers) is not int:
            raise ValueError("servers must be int")
        if not (1 <= servers <= 10**6):
            raise ValueError("servers out of range")

    # Simulation
    tokens = dict(places)
    in_progress = {t[0]: 0 for t in transitions}
    heap = []
    results = []
    t = 0

    trans_list = list(transitions)

    while True:
        if len(results) >= limit or t > until:
            break

        # 1. Process completions at t
        while heap and heap[0][0] == t:
            ct, idx, name = heapq.heappop(heap)
            in_progress[name] -= 1
            outputs = trans_list[idx][2]
            for place, weight in outputs.items():
                tokens[place] += weight

        if len(results) >= limit or t > until:
            break

        # 2. Try to start enabled transitions
        started_any = True
        while started_any:
            started_any = False
            enabled = []
            for idx, (name, inputs, outputs, duration, priority, servers) in enumerate(trans_list):
                if in_progress[name] >= servers:
                    continue
                can_fire = True
                for place, weight in inputs.items():
                    if tokens[place] < weight:
                        can_fire = False
                        break
                if can_fire:
                    enabled.append((priority, idx, name, inputs, outputs, duration))

            if not enabled:
                break

            enabled.sort(key=lambda x: (x[0], x[1]))
            _, idx, name, inputs, outputs, duration = enabled[0]

            # Start firing
            for place, weight in inputs.items():
                tokens[place] -= weight
            results.append((t, name))
            started_any = True

            if duration == 0:
                for place, weight in outputs.items():
                    tokens[place] += weight
            else:
                in_progress[name] += 1
                heapq.heappush(heap, (t + duration, idx, name))

            if len(results) >= limit or t > until:
                break

        # 3. Advance time
        if len(results) >= limit or t > until:
            break

        if not heap:
            break # No in-progress firings

        t = heap[0][0]
        if t > until:
            break

    return results

import heapq
from typing import List, Tuple, Dict, Set

def gate_trace(gates: List[Tuple], stimuli: List[Tuple], watch: List[str], until: int) -> Dict[str, List[Tuple]]:
    # --- Validation ---
    if not isinstance(until, int) or until < 0:
        raise ValueError("until must be a non-negative integer")

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    gate_list = []
    out_signals = set()
    all_signals = set()
    gate_map = {}

    for g in gates:
        if not isinstance(g, (list, tuple)) or len(g) != 4:
            raise ValueError("Each gate must be a tuple of 4 elements")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError("Gate output must be a non-empty string")
        if out in out_signals:
            raise ValueError("Gate outputs must be unique")
        if op not in valid_ops:
            raise ValueError(f"Invalid operation: {op}")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("Inputs must be a list or tuple")
        for i in ins:
            if not isinstance(i, str) or not i:
                raise ValueError("Input names must be non-empty strings")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"{op} requires exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} requires 2 to 4 inputs")
        if not isinstance(delay, int) or delay < 0 or delay > 10**12:
            raise ValueError("Delay must be an integer between 0 and 10^12")

        out_signals.add(out)
        for i in ins:
            all_signals.add(i)
        all_signals.add(out)
        gate_map[out] = (op, ins, delay)
        gate_list.append((out, op, ins, delay))

    stimuli_map = {}
    stimuli_times = set()
    for s in stimuli:
        if not isinstance(s, (list, tuple)) or len(s) != 3:
            raise ValueError("Each stimulus must be a tuple of 3 elements")
        t, sig, val = s
        if not isinstance(t, int) or t < 0:
            raise ValueError("Stimulus time must be a non-negative integer")
        if sig not in all_signals:
            raise ValueError(f"Unknown stimulus signal: {sig}")
        if sig in out_signals:
            raise ValueError(f"Cannot stimulate a driven signal: {sig}")
        if val not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

        if t not in stimuli_map:
            stimuli_map[t] = []
        stimuli_map[t].append((sig, val))
        stimuli_times.add(t)

    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Unknown watch signal: {w}")

    # Cycle detection
    adj = {s: [] for s in all_signals}
    for out, op, ins, delay in gate_list:
        for i in ins:
            adj[i].append(out)

    visited = set()
    rec_stack = set()

    def dfs(u):
        visited.add(u)
        rec_stack.add(u)
        for v in adj[u]:
            if v not in visited:
                if dfs(v):
                    return True
            elif v in rec_stack:
                return True
        rec_stack.remove(u)
        return False

    for s in all_signals:
        if s not in visited:
            if dfs(s):
                raise ValueError("Cycle detected in gate dependencies")

    # --- Simulation Setup ---
    current_values = {s: 0 for s in all_signals}
    pending_assignments = {}  # signal -> (due_time, value)
    last_values = {s: 0 for s in all_signals}

    # Event times management using a min-heap for efficiency
    pending_times_heap = []
    heapq.heappush(pending_times_heap, 0)
    for t in stimuli_times:
        if t <= until:
            heapq.heappush(pending_times_heap, t)

    # Gate lookup by input for evaluation
    gates_by_input = {s: [] for s in all_signals}
    for idx, (out, op, ins, delay) in enumerate(gate_list):
        for i in ins:
            gates_by_input[i].append(idx)

    watch_traces = {w: [] for w in watch}

    def eval_gate(op, inputs_vals):
        if op == "AND":
            return 1 if all(inputs_vals) else 0
        if op == "OR":
            return 1 if any(inputs_vals) else 0
        if op == "XOR":
            return sum(inputs_vals) % 2
        if op == "NAND":
            return 0 if all(inputs_vals) else 1
        if op == "NOR":
            return 0 if any(inputs_vals) else 1
        if op == "NOT":
            return 0 if inputs_vals[0] else 1
        if op == "BUF":
            return inputs_vals[0]
        return 0

    # Deduplicate heap entries
    seen_times = {0}
    for t in stimuli_times:
        if t <= until and t not in seen_times:
            heapq.heappush(pending_times_heap, t)
            seen_times.add(t)

    while pending_times_heap:
        t = heapq.heappop(pending_times_heap)

        if t > until:
            continue

        # --- Instant t processing ---
        round_num = 0
        while True:
            # Determine signals that changed in this round
            changed_signals = set()
            before_values = dict(current_values)

            if round_num == 0:
                # Round 1: Apply stimuli and pending assignments due at t
                if t in stimuli_map:
                    for sig, val in stimuli_map[t]:
                        current_values[sig] = val

                assignments_at_t = []
                for sig, (due, val) in list(pending_assignments.items()):
                    if due == t:
                        assignments_at_t.append((sig, val))

                for sig, val in assignments_at_t:
                    current_values[sig] = val
                    del pending_assignments[sig]
            else:
                # Round 2+: Apply pending assignments due at t (queued by previous round)
                assignments_at_t = []
                for sig, (due, val) in list(pending_assignments.items()):
                    if due == t:
                        assignments_at_t.append((sig, val))

                for sig, val in assignments_at_t:
                    current_values[sig] = val
                    del pending_assignments[sig]

            # Identify changed signals
            for s in all_signals:
                if current_values[s] != before_values[s]:
                    changed_signals.add(s)

            # Evaluate gates
            if round_num == 0 and t == 0:
                gates_to_eval = set(range(len(gate_list)))
            else:
                gates_to_eval = set()
                for s in changed_signals:
                    for idx in gates_by_input[s]:
                        gates_to_eval.add(idx)

            delta_assigned = False
            for idx in gates_to_eval:
                out, op, ins, delay = gate_list[idx]
                inputs_vals = [current_values[i] for i in ins]
                new_val = eval_gate(op, inputs_vals)

                if new_val != current_values[out]:
                    # Delete own pending assignment
                    if out in pending_assignments:
                        del pending_assignments[out]

                    due_time = t + delay
                    if due_time <= until:
                        pending_assignments[out] = (due_time, new_val)
                        if due_time == t:
                            delta_assigned = True
                        else:
                            if due_time not in seen_times:
                                heapq.heappush(pending_times_heap, due_time)
                                seen_times.add(due_time)

            if not delta_assigned:
                break

            round_num += 1

        # Record traces
        for w in watch:
            if current_values[w] != last_values[w]:
                watch_traces[w].append((t, current_values[w]))

        # Update last_values
        for s in all_signals:
            last_values[s] = current_values[s]

    return watch_traces

import collections
import heapq

def gate_trace(gates, stimuli, watch, until):
    # --- Validation and Parsing ---

    # Parse gates
    gate_list = []
    gate_by_out = {}
    all_signals = set()

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}

    for item in gates:
        out, op, ins, delay = item

        if not isinstance(out, str) or not out:
            raise ValueError("Gate output must be a non-empty string.")
        if out in gate_by_out:
            raise ValueError(f"Duplicate gate output: {out}")
        if op not in valid_ops:
            raise ValueError(f"Invalid operation: {op}")
        if not isinstance(ins, (list, tuple)) or not all(isinstance(s, str) and s for s in ins):
            raise ValueError("Inputs must be non-empty strings.")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"NOT and BUF require exactly 1 input.")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} requires 2 to 4 inputs.")
        if not isinstance(delay, int) or not (0 <= delay <= 10**12):
            raise ValueError("Delay must be an integer between 0 and 10^12.")

        gate_list.append({'out': out, 'op': op, 'ins': list(ins), 'delay': delay})
        gate_by_out[out] = gate_list[-1]
        all_signals.add(out)
        for s in ins:
            all_signals.add(s)

    # Build dependency graph for cycle detection
    # Nodes are signals. Edge x -> y if x is input to gate with output y.
    # Actually, for cycle detection, we care about signal dependencies.
    # If gate G has output y and inputs x1, x2, then y depends on x1, x2.
    # Cycle means y depends on y (directly or indirectly).
    # Graph: x -> y (x drives y).
    adj = collections.defaultdict(list)
    in_degree = collections.defaultdict(int)

    for g in gate_list:
        for inp in g['ins']:
            adj[inp].append(g['out'])
            in_degree[g['out']] += 1 # Count dependencies? No, in_degree for topo sort usually counts incoming edges.
            # Here edge is inp -> out. So out has incoming edge from inp.
            # Wait, standard topo sort: edges u -> v. in_degree[v]++.
            # Here u=inp, v=out. So in_degree[out]++.

    # Kahn's algorithm for cycle detection
    queue = collections.deque([s for s in all_signals if in_degree[s] == 0])
    visited_count = 0
    temp_in_degree = dict(in_degree)

    while queue:
        u = queue.popleft()
        visited_count += 1
        for v in adj[u]:
            temp_in_degree[v] -= 1
            if temp_in_degree[v] == 0:
                queue.append(v)

    if visited_count != len(all_signals):
        raise ValueError("Cycle detected in gate dependencies.")

    # Identify primary inputs
    primary_inputs = all_signals - set(gate_by_out.keys())

    # Parse stimuli
    stimuli_by_time = collections.defaultdict(list)
    for item in stimuli:
        time, signal, value = item
        if not isinstance(time, int) or not (0 <= time <= 10**12):
            raise ValueError("Stimulus time must be an integer between 0 and 10^12.")
        if signal not in primary_inputs:
            raise ValueError(f"Stimulus signal '{signal}' is not a primary input or unknown.")
        if value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1.")
        stimuli_by_time[time].append((signal, value))

    # Validate watch
    for w in watch:
        if w not in all_signals:
            raise ValueError(f"Watch signal '{w}' is unknown.")

    # Validate until
    if not isinstance(until, int) or not (0 <= until <= 10**12):
        raise ValueError("Until must be an integer between 0 and 10^12.")

    # --- Simulation ---

    # State
    current_values = {s: 0 for s in all_signals}
    pending = {} # signal -> (due_time, value)

    # Trace
    trace = {w: [] for w in watch}
    last_values = {w: 0 for w in watch} # Value at previous instant

    # Event management
    # We need to process times in order.
    # Events: Stimuli times, Assignment due times.
    # We can use a min-heap for next event time.
    # But since we process all events at time t together, we can just iterate.

    # Collect all event times
    event_times = set()
    event_times.add(0)
    for t in stimuli_by_time:
        event_times.add(t)
    # Assignments start empty, so no times yet.

    sorted_times = sorted(event_times)
    time_idx = 0

    while time_idx < len(sorted_times):
        t = sorted_times[time_idx]
        if t > until:
            break

        # --- Round 1: Batch ---
        changed = set()

        # Apply Stimuli
        if t in stimuli_by_time:
            for sig, val in stimuli_by_time[t]:
                if current_values[sig] != val:
                    current_values[sig] = val
                    changed.add(sig)

        # Apply Pending Assignments due at t
        # We need to collect them first to avoid modifying dict while iterating if we were,
        # but we can just filter.
        signals_to_apply = [sig for sig, (dt, val) in pending.items() if dt == t]
        for sig in signals_to_apply:
            val = pending[sig][1]
            if current_values[sig] != val:
                current_values[sig] = val
                changed.add(sig)
            del pending[sig]

        # --- Evaluation Rounds ---
        # Loop for delta rounds
        while True:
            # Determine gates to evaluate
            gates_to_eval = set()
            if t == 0:
                # First round of instant 0: every gate
                gates_to_eval = {id(g) for g in gate_list}
            else:
                for g in gate_list:
                    if any(inp in changed for inp in g['ins']):
                        gates_to_eval.add(id(g))

            if not gates_to_eval:
                break

            new_changed = set()
            new_pending = {} # Temp storage for new assignments

            for g in gate_list:
                if id(g) not in gates_to_eval:
                    continue

                # Compute
                vals = [current_values[inp] for inp in g['ins']]
                op = g['op']
                out = g['out']
                delay = g['delay']

                if op == "AND":
                    new_val = 1 if all(vals) else 0
                elif op == "OR":
                    new_val = 1 if any(vals) else 0
                elif op == "XOR":
                    new_val = 1 if sum(vals) % 2 else 0
                elif op == "NAND":
                    new_val = 0 if all(vals) else 1
                elif op == "NOR":
                    new_val = 1 if not any(vals) else 0
                elif op == "NOT":
                    new_val = 1 - vals[0]
                elif op == "BUF":
                    new_val = vals[0]
                else:
                    new_val = 0 # Should not happen

                if new_val != current_values[out]:
                    # Delete existing pending assignment for this output
                    if out in pending:
                        del pending[out]

                    # Schedule new assignment
                    due = t + delay
                    if due == t:
                        # Due in next round of this instant
                        # We apply it immediately in the logic flow?
                        # Spec: "queues (out := value) due at t + delay. A delay of 0 means due in the next round of this same instant."
                        # And "In the later rounds apply the assignments due at t".
                        # So we queue it, and it will be applied in the next iteration of this loop (which acts as next round).
                        # But wait, my loop structure is Evaluate -> Check -> Apply?
                        # No, I need to apply it to update current_values for the next evaluation round?
                        # Actually, for the next round, the value must be updated.
                        # So yes, if delay 0, we update current_values immediately?
                        # Or do we queue it and apply it in the "Apply" phase of next round?
                        # Spec: "In the later rounds apply the assignments due at t".
                        # This implies a distinct Apply phase.
                        # But my loop is just Evaluate.
                        # Let's restructure loop to be: Evaluate -> Queue -> If due at t, Apply -> Update changed -> Repeat.

                        new_pending[out] = new_val
                    else:
                        pending[out] = (due, new_val)

            # Apply new assignments due at t (delay 0)
            if new_pending:
                for out, val in new_pending.items():
                    if current_values[out] != val:
                        current_values[out] = val
                        new_changed.add(out)
                changed = new_changed
            else:
                break

        # --- Record Trace ---
        for w in watch:
            if current_values[w] != last_values[w]:
                trace[w].append((t, current_values[w]))
                last_values[w] = current_values[w]

        time_idx += 1

        # Advance time: find next event time
        # Next event is min(next stimulus time, next pending assignment due time)
        # We can maintain a heap for pending assignments due times.
        # But since we process all at time t, we can just look ahead.
        # However, pending assignments might be due at times > until.

        # Let's use a heap for pending assignment due times.
        # But we need to handle duplicates and updates.
        # Since each signal has at most one pending assignment, we can just scan or use heap.
        # Scanning is O(G), which is small (60).

        next_time = float('inf')

        # Next stimulus
        if time_idx < len(sorted_times):
            next_time = min(next_time, sorted_times[time_idx])

        # Next pending assignment
        for sig, (dt, val) in pending.items():
            if dt <= until:
                next_time = min(next_time, dt)

        if next_time == float('inf') or next_time > until:
            break

        # Insert next_time into sorted_times?
        # We can just update time_idx to point to the correct time.
        # But sorted_times is static.
        # Better to maintain a heap for event times.
        # But stimuli are static.
        # Let's just re-scan or manage a pointer.
        # Since sorted_times is sorted, we can just find the next time >= current t.
        # But we need to include dynamic assignment times.

        # Let's use a heap for all event times.
        # But we already processed t.
        # We need to push new assignment times.
        # And we have static stimulus times.

        # Let's refactor event management to use a heap.
        pass

    # Refactoring event management for correctness and efficiency
    # Reset and redo with heap

    # Reset state
    current_values = {s: 0 for s in all_signals}
    pending = {}
    trace = {w: [] for w in watch}
    last_values = {w: 0 for w in watch}

    # Event heap: (time, type, data)
    # Type 0: Stimulus, Type 1: Assignment
    # But we process all at time t together.
    # So just store times.
    # We need to know which times have stimuli.

    # Heap of event times
    event_heap = []
    if 0 <= until:
        heapq.heappush(event_heap, 0)

    for t in stimuli_by_time:
        if t <= until:
            heapq.heappush(event_heap, t)

    # To avoid duplicates in heap
    processed_times = set()

    while event_heap:
        t = heapq.heappop(event_heap)
        if t in processed_times:
            continue
        if t > until:
            break
        processed_times.add(t)

        # --- Round 1: Batch ---
        changed = set()

        # Apply Stimuli
        if t in stimuli_by_time:
            for sig, val in stimuli_by_time[t]:
                if current_values[sig] != val:
                    current_values[sig] = val
                    changed.add(sig)

        # Apply Pending Assignments due at t
        signals_to_apply = [sig for sig, (dt, val) in pending.items() if dt == t]
        for sig in signals_to_apply:
            val = pending[sig][1]
            if current_values[sig] != val:
                current_values[sig] = val
                changed.add(sig)
            del pending[sig]

        # --- Evaluation Rounds ---
        while True:
            gates_to_eval = set()
            if t == 0:
                gates_to_eval = {id(g) for g in gate_list}
            else:
                for g in gate_list:
                    if any(inp in changed for inp in g['ins']):
                        gates_to_eval.add(id(g))

            if not gates_to_eval:
                break

            new_changed = set()
            new_pending = {}

            for g in gate_list:
                if id(g) not in gates_to_eval:
                    continue

                vals = [current_values[inp] for inp in g['ins']]
                op = g['op']
                out = g['out']
                delay = g['delay']

                if op == "AND":
                    new_val = 1 if all(vals) else 0
                elif op == "OR":
                    new_val = 1 if any(vals) else 0
                elif op == "XOR":
                    new_val = 1 if sum(vals) % 2 else 0
                elif op == "NAND":
                    new_val = 0 if all(vals) else 1
                elif op == "NOR":
                    new_val = 1 if not any(vals) else 0
                elif op == "NOT":
                    new_val = 1 - vals[0]
                elif op == "BUF":
                    new_val = vals[0]
                else:
                    new_val = 0

                if new_val != current_values[out]:
                    if out in pending:
                        del pending[out]

                    due = t + delay
                    if due == t:
                        new_pending[out] = new_val
                    else:
                        if due <= until:
                            pending[out] = (due, new_val)
                            heapq.heappush(event_heap, due)

            if new_pending:
                for out, val in new_pending.items():
                    if current_values[out] != val:
                        current_values[out] = val
                        new_changed.add(out)
                changed = new_changed
            else:
                break

        # --- Record Trace ---
        for w in watch:
            if current_values[w] != last_values[w]:
                trace[w].append((t, current_values[w]))
                last_values[w] = current_values[w]

    return trace

import heapq
from collections import defaultdict

def gate_trace(gates, stimuli, watch, until):
    # --- Validation ---

    # Check types and basic constraints
    if not isinstance(until, int) or isinstance(until, bool) or until < 0 or until > 10**12:
        raise ValueError("Invalid 'until'")

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    gate_map = {} # out -> (op, ins, delay)
    all_outputs = set()
    all_inputs = set()
    all_signals = set()

    # Validate gates
    for g in gates:
        if not isinstance(g, (list, tuple)) or len(g) != 4:
            raise ValueError("Invalid gate definition")
        out, op, ins, delay = g

        if not isinstance(out, str) or not out:
            raise ValueError("Gate output must be a non-empty string")
        if out in all_outputs:
            raise ValueError("Duplicate gate output")
        all_outputs.add(out)

        if op not in valid_ops:
            raise ValueError(f"Invalid operation: {op}")

        if not isinstance(ins, (list, tuple)):
            raise ValueError("Inputs must be a list or tuple")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError(f"NOT/BUF must have exactly 1 input")
        if op in ("AND", "OR", "XOR", "NAND", "NOR") and not (2 <= len(ins) <= 4):
            raise ValueError(f"{op} must have 2 to 4 inputs")

        for i in ins:
            if not isinstance(i, str) or not i:
                raise ValueError("Gate input name must be a non-empty string")
            all_inputs.add(i)

        if not isinstance(delay, int) or isinstance(delay, bool) or delay < 0 or delay > 10**12:
            raise ValueError("Gate delay must be an int 0..10^12")

        gate_map[out] = (op, list(ins), delay)
        all_signals.update(ins)
        all_signals.add(out)

    # Validate stimuli
    stimuli_map = defaultdict(list)
    primary_inputs = set()

    # Identify primary inputs (signals that are not outputs)
    primary_inputs = all_signals - all_outputs

    for s in stimuli:
        if not isinstance(s, (list, tuple)) or len(s) != 3:
            raise ValueError("Invalid stimulus definition")
        time, signal, value = s

        if not isinstance(time, int) or isinstance(time, bool) or time < 0 or time > 10**12:
            raise ValueError("Stimulus time must be an int 0..10^12")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal name must be a non-empty string")
        if not isinstance(value, int) or isinstance(value, bool) or value not in (0, 1):
            raise ValueError("Stimulus value must be 0 or 1")

        if signal not in all_signals:
            raise ValueError(f"Unknown stimulus signal: {signal}")
        if signal in all_outputs:
            raise ValueError(f"Stimulus signal '{signal}' is driven by a gate")

        stimuli_map[time].append((signal, value))
        primary_inputs.add(signal)
        all_signals.add(signal)

    # Validate watch
    watch_signals = set(watch)
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch name must be a non-empty string")
        if w not in all_signals:
            raise ValueError(f"Unknown watch signal: {w}")

    # Cycle Detection
    # Build adjacency list: input -> [outputs]
    adj = defaultdict(list)
    for out, (op, ins, delay) in gate_map.items():
        for inp in ins:
            adj[inp].append(out)

    # DFS for cycle detection
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {s: WHITE for s in all_signals}

    def has_cycle(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                return True
            if color[v] == WHITE:
                if has_cycle(v):
                    return True
        color[u] = BLACK
        return False

    for s in all_signals:
        if color[s] == WHITE:
            if has_cycle(s):
                raise ValueError("Cycle detected in gate dependencies")

    # --- Initialization ---

    # Current values of all signals
    values = {s: 0 for s in all_signals}

    # Pending assignments: signal -> (due_time, value)
    pending = {}

    # Dependency map for gates: signal -> list of gate keys (outputs)
    gates_by_input = defaultdict(list)
    for out, (op, ins, delay) in gate_map.items():
        for inp in ins:
            gates_by_input[inp].append(out)

    # Event queue for times
    event_times = set()
    event_times.add(0)
    for t in stimuli_map:
        if t <= until:
            event_times.add(t)

    # Sort times
    sorted_times = sorted([t for t in event_times if t <= until])

    # Trace storage
    traces = {w: [] for w in watch}

    # Previous instant values (initially 0 for all)
    prev_values = {s: 0 for s in all_signals}

    # --- Simulation ---

    for t in sorted_times:
        # Round 1
        changed = set()

        # 1. Apply Stimuli
        if t in stimuli_map:
            for sig, val in stimuli_map[t]:
                if values[sig] != val:
                    changed.add(sig)
                values[sig] = val

        # 2. Apply Pending Assignments due at t
        # Collect keys to iterate, as we might modify pending dict? 
        # Actually we don't modify pending here, but we might delete later.
        # We need to apply all pending assignments due at t.
        # Note: pending dict might contain assignments due at t that were queued in previous rounds.
        pending_due_t = [sig for sig, (due, val) in pending.items() if due == t]

        # Apply them
        # Order doesn't strictly matter for correctness of values as they are independent updates
        # but let's be deterministic.
        for sig in pending_due_t:
            due_time, val = pending[sig]
            # Double check due_time is still t (could have been cancelled? No, cancelled removes from dict)
            # But if cancelled, it's not in dict.
            if values[sig] != val:
                changed.add(sig)
            values[sig] = val
            # Remove from pending? 
            # Spec: "apply every pending assignment". 
            # If we leave it in pending, it might be applied again?
            # But we iterate over a snapshot or list.
            # However, if we don't remove it, and a gate evaluation happens, it might delete it.
            # If we remove it, it's gone.
            # Let's remove it to avoid re-application if logic loops?
            # But wait, if delay > 0, it's due at t. It's applied once.
            # If delay == 0, it's due at t. Applied once.
            # So we should remove it.
            del pending[sig]

        # 3. Evaluate Gates
        # In first round of instant 0, evaluate all gates.
        # Otherwise, evaluate gates with changed inputs.
        evaluate_all = (t == 0)

        # We need to evaluate gates whose inputs changed.
        # Since we might have multiple rounds, we need to track changed signals per round.
        # But here in Round 1, 'changed' tracks signals changed by stimuli/pending.

        gates_to_eval = []
        if evaluate_all:
            gates_to_eval = list(gate_map.keys())
        else:
            # Find gates that depend on any changed signal
            for sig in changed:
                if sig in gates_by_input:
                    gates_to_eval.extend(gates_by_input[sig])
            # Remove duplicates and sort for determinism?
            gates_to_eval = sorted(list(set(gates_to_eval)))

        new_pending = {}
        for out in gates_to_eval:
            op, ins, delay = gate_map[out]

            # Delete own pending assignment if exists
            if out in pending:
                del pending[out]

            # Compute value
            if op == "NOT":
                val = 1 if values[ins[0]] == 0 else 0
            elif op == "BUF":
                val = values[ins[0]]
            elif op == "AND":
                val = 1
                for i in ins:
                    if values[i] == 0:
                        val = 0
                        break
            elif op == "OR":
                val = 0
                for i in ins:
                    if values[i] == 1:
                        val = 1
                        break
            elif op == "XOR":
                val = 0
                for i in ins:
                    val ^= values[i]
            elif op == "NAND":
                val = 1
                for i in ins:
                    if values[i] == 0:
                        val = 1
                        break
                else:
                    val = 0
            elif op == "NOR":
                val = 0
                for i in ins:
                    if values[i] == 1:
                        val = 1
                        break
                else:
                    val = 0

            # If computed value differs from current output value
            if val != values[out]:
                due_time = t + delay
                if due_time <= until:
                    # Queue new assignment
                    # If delay == 0, due at t (next round)
                    # If delay > 0, due at due_time
                    pending[out] = (due_time, val)
                    if due_time not in event_times:
                        event_times.add(due_time)

        # Record changes for trace?
        # No, trace is recorded after all rounds of instant t.

        # Round Loop for delta cycles
        while pending:
            # Check if any pending assignment is due at t
            pending_due_t = [sig for sig, (due, val) in pending.items() if due == t]
            if not pending_due_t:
                break

            # Next Round: Apply pending assignments
            changed = set()
            for sig in pending_due_t:
                due_time, val = pending[sig]
                if values[sig] != val:
                    changed.add(sig)
                values[sig] = val
                del pending[sig]

            # Evaluate gates with changed inputs
            gates_to_eval = []
            for sig in changed:
                if sig in gates_by_input:
                    gates_to_eval.extend(gates_by_input[sig])
            gates_to_eval = sorted(list(set(gates_to_eval)))

            for out in gates_to_eval:
                op, ins, delay = gate_map[out]

                # Delete own pending
                if out in pending:
                    del pending[out]

                # Compute
                if op == "NOT":
                    val = 1 if values[ins[0]] == 0 else 0
                elif op == "BUF":
                    val = values[ins[0]]
                elif op == "AND":
                    val = 1
                    for i in ins:
                        if values[i] == 0:
                            val = 0
                            break
                elif op == "OR":
                    val = 0
                    for i in ins:
                        if values[i] == 1:
                            val = 1
                            break
                elif op == "XOR":
                    val = 0
                    for i in ins:
                        val ^= values[i]
                elif op == "NAND":
                    val = 1
                    for i in ins:
                        if values[i] == 0:
                            val = 1
                            break
                    else:
                        val = 0
                elif op == "NOR":
                    val = 0
                    for i in ins:
                        if values[i] == 1:
                            val = 1
                            break
                    else:
                        val = 0

                if val != values[out]:
                    due_time = t + delay
                    if due_time <= until:
                        pending[out] = (due_time, val)
                        if due_time not in event_times:
                            event_times.add(due_time)

        # End of instant t
        # Record trace
        for w in watch:
            if values[w] != prev_values[w]:
                traces[w].append((t, values[w]))
                prev_values[w] = values[w]

    return traces

def gate_trace(gates, stimuli, watch, until):
    # --- Validation ---

    # Type checks
    if not isinstance(gates, (list, tuple)): raise ValueError("gates must be list/tuple")
    if not isinstance(stimuli, (list, tuple)): raise ValueError("stimuli must be list/tuple")
    if not isinstance(watch, (list, tuple)): raise ValueError("watch must be list/tuple")
    if not isinstance(until, int) or isinstance(until, bool): raise ValueError("until must be int")

    # Check until range
    if until < 0: raise ValueError("until must be >= 0")

    # Parse gates
    gate_list = []
    gate_map = {} # out -> gate info
    all_signals = set()
    primary_inputs = set()

    # Helper to check op
    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}

    for g in gates:
        if not isinstance(g, tuple) or len(g) != 4:
            raise ValueError("Each gate must be a tuple (out, op, ins, delay)")
        out, op, ins, delay = g

        if not isinstance(out, str) or not out: raise ValueError("Gate out must be non-empty string")
        if out in gate_map: raise ValueError(f"Duplicate gate output: {out}")
        if op not in valid_ops: raise ValueError(f"Invalid op: {op}")
        if not isinstance(ins, (list, tuple)): raise ValueError("ins must be list/tuple")
        if not all(isinstance(i, str) and i for i in ins): raise ValueError("ins elements must be non-empty strings")
        if not isinstance(delay, int) or isinstance(delay, bool): raise ValueError("delay must be int")
        if delay < 0 or delay > 10**12: raise ValueError("delay out of range")

        if op in ("NOT", "BUF"):
            if len(ins) != 1: raise ValueError(f"{op} requires 1 input")
        else:
            if len(ins) < 2 or len(ins) > 4: raise ValueError(f"{op} requires 2-4 inputs")

        gate_list.append({'out': out, 'op': op, 'ins': list(ins), 'delay': delay})
        gate_map[out] = gate_list[-1]
        all_signals.add(out)
        for i in ins:
            all_signals.add(i)

    # Identify primary inputs
    # A signal is primary input if it is not an output of any gate
    driven_signals = set(gate_map.keys())
    primary_inputs = all_signals - driven_signals

    # Parse stimuli
    stimuli_list = []
    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Each stimulus must be tuple (time, signal, value)")
        time, signal, value = s
        if not isinstance(time, int) or isinstance(time, bool): raise ValueError("stimulus time must be int")
        if time < 0: raise ValueError("stimulus time must be >= 0")
        if not isinstance(signal, str) or not signal: raise ValueError("stimulus signal must be non-empty string")
        if signal not in primary_inputs: raise ValueError(f"Stimulus signal '{signal}' is not a primary input")
        if value not in (0, 1): raise ValueError("stimulus value must be 0 or 1")
        stimuli_list.append((time, signal, value))

    # Check watch signals
    watch_list = list(watch)
    for w in watch_list:
        if not isinstance(w, str) or not w: raise ValueError("Watch signal must be non-empty string")
        if w not in all_signals: raise ValueError(f"Watch signal '{w}' is unknown")

    # Check for cycles
    # Graph: ins -> out
    adj = {s: [] for s in all_signals}
    for g in gate_list:
        for i in g['ins']:
            adj[i].append(g['out'])

    # DFS for cycle detection
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {s: WHITE for s in all_signals}

    def has_cycle(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                return True
            if color[v] == WHITE:
                if has_cycle(v):
