    # --- Simulation ---

    # Sort stimuli by time, but keep original order for same time?
    # Actually, we process them in list order at time t.
    # Sorting by time helps to find events.
    # But we need to preserve relative order for same time.
    # Python sort is stable.
    stimuli_list.sort(key=lambda x: x[0])

    # State
    signal_values = {s: 0 for s in all_signals}
    pending = {} # signal -> (due_time, value)

    # Dependency map: signal -> list of gates that depend on it
    # We need to quickly find gates to evaluate.
    # Since N is small, we can just iterate all gates or build map.
    # Map: input_signal -> list of gate indices
    input_to_gates = {s: [] for s in all_signals}
    for idx, g in enumerate(gate_list):
