    # Watch history
    watch_history = {w: 0 for w in watch_list}
    trace = {w: [] for w in watch_list}

    # Simulation variables
    current_time = 0
    s_idx = 0 # pointer to next stimulus
    n_stimuli = len(stimuli_list)

