        next_pending = min((t for t, v in pending.values()), default=float('inf'))
        return min(next_stim, next_pending)

    while current_time <= until:
        # 1. Process Stimuli at current_time
        # We need to apply them in list order.
        # But we must snapshot values before applying to detect changes.

        # Snapshot before batch
        prev_values = dict(signal_values)

        # Apply stimuli
        while s_idx < n_stimuli and stimuli_list[s_idx][0] == current_time:
            _, sig, val = stimuli_list[s_idx]
            signal_values[sig] = val
            s_idx += 1

        # Apply pending assignments due at current_time
        # Find all assignments due at current_time
        # Note: pending dict might have multiple entries, but each signal unique.
        # We need to apply all that are due.
        due_signals = [sig for sig, (t, v) in pending.items() if t == current_time]

        for sig in due_signals:
            _, val = pending[sig]
            signal_values[sig] = val
            del pending[sig]

