                    if i in changed_signals:
                        has_changed_input = True
                        break
                if has_changed_input:
                    gates_to_eval.append(idx)

        # Process gates
        # We might schedule new assignments.
        # If delay is 0, they are due at current_time, triggering next round.

        # We need to process gates. Order?
        # "Every gate ... computes its function".
        # If multiple gates evaluate, they read current values.
        # Does order matter?
        # If gate A outputs to B, and B is input to C.
        # If A evaluates and changes B (delay 0), B changes in pending.
