        # We need to check if any assignment was scheduled with due_time == current_time
        while any(t == current_time for t, v in pending.values()):
            # Batch step for later rounds
            # Apply assignments due at current_time
            # Snapshot again?
            # "A signal 'changed' in the round if its value after the batch differs from before it."
            # So yes, snapshot before this batch.
            prev_values = dict(signal_values)

            due_signals = [sig for sig, (t, v) in pending.items() if t == current_time]
            for sig in due_signals:
