            gates_to_eval = []
            for idx, g in enumerate(gate_list):
                has_changed_input = False
                for i in g['ins']:
                    if i in changed_signals:
                        has_changed_input = True
                        break
                if has_changed_input:
                    gates_to_eval.append(idx)

            for idx in gates_to_eval:
                g = gate_list[idx]
                out = g['out']
                delay = g['delay']

                inputs = [signal_values[i] for i in g['ins']]

                op = g['op']
                if op == "AND":
                    new_val = 1 if all(inputs) else 0
                elif op == "OR":
                    new_val = 1 if any(inputs) else 0
                elif op == "XOR":
                    new_val = sum(inputs) % 2
                elif op == "NAND":
                    new_val = 0 if all(inputs) else 1
                elif op == "NOR":
                    new_val = 1 if not any(inputs) else 0
                elif op == "NOT":
                    new_val = 1 - inputs[0]
                elif op == "BUF":
                    new_val = inputs[0]
                else:
                    new_val = 0

                if out in pending:
                    del pending[out]

                if new_val != signal_values[out]:
                    due = current_time + delay
                    if due <= until:
                        pending[out] = (due, new_val)

        # 4. Record Trace
        # Trace recorded after instant t is fully processed (all rounds done)
        # "The trace of a watched signal has (t, v) for each instant t whose final value v ... differs from the final value at the previous simulated instant"
        for w in watch_list:
            if signal_values[w] != watch_history[w]:
                trace[w].append((current_time, signal_values[w]))
                watch_history[w] = signal_values[w]

        # 5. Advance Time
        next_t = get_next_time()
        if next_t > until:
            break
        if next_t == float('inf'):
            break
        current_time = next_t

    return trace

def gate_trace(gates, stimuli, watch, until):
    # --- Validation ---

    if not isinstance(until, int) or isinstance(until, bool):
