            if len(ins) != 1:
                raise ValueError(f"{op} requires 1 input")
        else:
            if len(ins) < 2 or len(ins) > 4:
                raise ValueError(f"{op} requires 2-4 inputs")

        gate_list.append({'out': out, 'op': op, 'ins': list(ins), 'delay': delay})
        gate_map[out] = gate_list[-1]
        all_signals.add(out)
        driven_signals.add(out)
        for i in ins:
            all_signals.add(i)

    primary_inputs = all_signals - driven_signals

    stimuli_list = []
    for s in stimuli:
        if not isinstance(s, tuple) or len(s) != 3:
            raise ValueError("Stimulus must be tuple (time, signal, value)")
        time, signal, value = s

        if not isinstance(time, int) or isinstance(time, bool):
