    for g in gate_list:
        for i in g['ins']:
            adj[i].append(g['out'])

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {s: WHITE for s in all_signals}

    def has_cycle(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                return True
            if color[v] == WHITE:
                if has_cycle(v):
                    return True
        color[u] = BLACK
        return False

    for s in all_signals:
        if color[s] == WHITE:
            if has_cycle(s):
