def weak_infer(term: tuple) -> str:
    # Type classes
    class Type: pass
    class TVar(Type):
        def __init__(self, id): self.id = id
        def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
        def __hash__(self): return hash(self.id)
    class TInt(Type): pass
    class TBool(Type): pass
    class TStr(Type): pass
    class TUnit(Type): pass
    class TList(Type):
        def __init__(self, elem): self.elem = elem
        def __eq__(self, other): return isinstance(other, TList) and self.elem == other.elem
        def __hash__(self): return hash(self.elem)
    class TRef(Type):
        def __init__(self, content): self.content = content
        def __eq__(self, other): return isinstance(other, TRef) and self.content == other.content
        def __hash__(self): return hash(self.content)
    class TFunc(Type):
        def __init__(self, args, ret): self.args = args; self.ret = ret
        def __eq__(self, other): return isinstance(other, TFunc) and self.args == other.args and self.ret == other.ret
        def __hash__(self): return hash((self.args, self.ret))

    # Validation
    def validate_term(term):
        if not isinstance(term, tuple) or len(term) == 0:
            raise ValueError("Malformed")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed")

        if tag == "int":
            if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
                raise ValueError("Malformed")
        elif tag == "bool":
            if len(term) != 2 or not isinstance(term[1], bool):
                raise ValueError("Malformed")
        elif tag == "str":
            if len(term) != 2 or not isinstance(term[1], str):
                raise ValueError("Malformed")
        elif tag == "unit":
            if len(term) != 1:
                raise ValueError("Malformed")
        elif tag == "var":
            if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed")
        elif tag == "fn":
            if len(term) != 3:
                raise ValueError("Malformed")
            params, body = term[1], term[2]
            if not isinstance(params, tuple) or len(params) == 0:
                raise ValueError("Malformed")
            if len(set(params)) != len(params):
                raise ValueError("Malformed")
            if not all(isinstance(p, str) and p for p in params):
                raise ValueError("Malformed")
            validate_term(body)
        elif tag == "call":
            if len(term) != 3:
                raise ValueError("Malformed")
            f, args = term[1], term[2]
            if not isinstance(args, tuple) or len(args) == 0:
                raise ValueError("Malformed")
            validate_term(f)
            for a in args: validate_term(a)
        elif tag == "let":
            if len(term) != 4:
                raise ValueError("Malformed")
            name, e1, e2 = term[1], term[2], term[3]
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed")
            validate_term(e1)
            validate_term(e2)
        elif tag == "letrec":
            if len(term) != 4:
                raise ValueError("Malformed")
            name, e1, e2 = term[1], term[2], term[3]
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed")
            validate_term(e1)
            validate_term(e2)
        elif tag == "nil":
            if len(term) != 1:
                raise ValueError("Malformed")
        elif tag == "cons":
            if len(term) != 3:
                raise ValueError("Malformed")
            h, t = term[1], term[2]
            validate_term(h)
            validate_term(t)
        elif tag == "match":
            if len(term) != 6:
                raise ValueError("Malformed")
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            validate_term(s)
            validate_term(e_nil)
            validate_term(e_cons)
            if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn:
                raise ValueError("Malformed")
            if hn == tn:
                raise ValueError("Malformed")
        elif tag == "ref":
            if len(term) != 2:
                raise ValueError("Malformed")
            validate_term(term[1])
        elif tag == "get":
            if len(term) != 2:
                raise ValueError("Malformed")
            validate_term(term[1])
        elif tag == "set":
            if len(term) != 3:
                raise ValueError("Malformed")
            validate_term(term[1])
            validate_term(term[2])
        else:
            raise ValueError("Unknown tag")

    validate_term(term)

    sub = {}
    fresh_var_counter = [0]
    var_order = []

    def fresh():
        fresh_var_counter[0] += 1
        vid = fresh_var_counter[0]
        var_order.append(vid)
        return TVar(vid)

    def free_vars(t):
        if isinstance(t, TVar):
            return {t.id}
        elif isinstance(t, TFunc):
            res = set()
            for a in t.args: res.update(free_vars(a))
            res.update(free_vars(t.ret))
            return res
        elif isinstance(t, TList): return free_vars(t.elem)
        elif isinstance(t, TRef): return free_vars(t.content)
        return set()

    def apply_sub(t):
        if isinstance(t, TVar):
            if t.id in sub:
                return apply_sub(sub[t.id])
            return t
        elif isinstance(t, TFunc):
            return TFunc(tuple(apply_sub(a) for a in t.args), apply_sub(t.ret))
        elif isinstance(t, TList):
            return TList(apply_sub(t.elem))
        elif isinstance(t, TRef):
            return TRef(apply_sub(t.content))
        return t

    def unify(t1, t2):
        t1 = apply_sub(t1)
        t2 = apply_sub(t2)
        if t1 == t2: return
        if isinstance(t1, TVar):
            if t1.id in free_vars(t2): raise ValueError("Infinite type")
            sub[t1.id] = t2
        elif isinstance(t2, TVar):
            if t2.id in free_vars(t1): raise ValueError("Infinite type")
            sub[t2.id] = t1
        elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
            if len(t1.args) != len(t2.args): raise ValueError("Arity mismatch")
            for a1, a2 in zip(t1.args, t2.args):
                unify(a1, a2)
            unify(t1.ret, t2.ret)
        elif isinstance(t1, TList) and isinstance(t2, TList):
            unify(t1.elem, t2.elem)
        elif isinstance(t1, TRef) and isinstance(t2, TRef):
            unify(t1.content, t2.content)
        else:
            raise ValueError("Type mismatch")

    def freshen_type(t, var_map=None):
        if var_map is None: var_map = {}
        if isinstance(t, TVar):
            if t.id not in var_map:
                var_map[t.id] = fresh()
            return var_map[t.id]
        elif isinstance(t, TFunc):
            return TFunc(tuple(freshen_type(a, var_map) for a in t.args), freshen_type(t.ret, var_map))
        elif isinstance(t, TList):
            return TList(freshen_type(t.elem, var_map))
        elif isinstance(t, TRef):
            return TRef(freshen_type(t.content, var_map))
        return t

    def apply_mapping(t, mapping):
        if isinstance(t, TVar):
            if t.id in mapping:
                return apply_mapping(mapping[t.id], mapping)
            return t
        elif isinstance(t, TFunc):
            return TFunc(tuple(apply_mapping(a, mapping) for a in t.args), apply_mapping(t.ret, mapping))
        elif isinstance(t, TList):
            return TList(apply_mapping(t.elem, mapping))
        elif isinstance(t, TRef):
            return TRef(apply_mapping(t.content, mapping))
        return t

    def generalize(t, env):
        t = apply_sub(t)
        env_free = set()
        for ty in env.values():
            env_free.update(free_vars(apply_sub(ty)))
        qvars = free_vars(t) - env_free
        mapping = {}
        for vid in qvars:
            mapping[vid] = fresh()
        return apply_mapping(t, mapping)

    def is_value(t):
        tag = t[0]
        if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
            return True
        if tag == "cons":
            return is_value(t[1]) and is_value(t[2])
        return False

    initial_env = {
        "plus": TFunc((TInt, TInt), TInt),
        "eq": TFunc((TVar(0), TVar(0)), TBool),
        "size": TFunc((TStr,), TInt)
    }

    def infer(term, env):
        tag = term[0]
        if tag == "int": return TInt
        if tag == "bool": return TBool
        if tag == "str": return TStr
        if tag == "unit": return TUnit
        if tag == "var":
            name = term[1]
            if name not in env: raise ValueError("Unbound variable")
            return freshen_type(env[name])
        if tag == "fn":
            params, body = term[1], term[2]
            param_types = tuple(fresh() for _ in params)
            new_env = env.copy()
            for p, pt in zip(params, param_types):
                new_env[p] = pt
            ret_type = infer(body, new_env)
            return TFunc(param_types, ret_type)
        if tag == "call":
            f, args = term[1], term[2]
            f_type = infer(f, env)
            f_type = apply_sub(f_type)
            if not isinstance(f_type, TFunc): raise ValueError("Not a function")
            if len(args) != len(f_type.args): raise ValueError("Arity mismatch")
            arg_types = tuple(infer(a, env) for a in args)
            for at, pt in zip(arg_types, f_type.args):
                unify(at, pt)
            return apply_sub(f_type.ret)
        if tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            t1 = infer(e1, env)
            if is_value(e1):
                t1 = generalize(t1, env)
            new_env = env.copy()
            new_env[name] = t1
            return infer(e2, new_env)
        if tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            if not isinstance(e1, tuple) or e1[0] != "fn":
                raise ValueError("letrec e1 must be fn")
            T_name = fresh()
            new_env = env.copy()
            new_env[name] = T_name
            t1 = infer(e1, new_env)
            t1 = apply_sub(t1)
            t1 = generalize(t1, env)
            new_env[name] = t1
            return infer(e2, new_env)
        if tag == "nil":
            return TList(fresh())
        if tag == "cons":
            h, t = term[1], term[2]
            ht = infer(h, env)
            tt = infer(t, env)
            tt = apply_sub(tt)
            if not isinstance(tt, TList): raise ValueError("cons t must be List")
            unify(ht, tt.elem)
            return apply_sub(tt)
        if tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            s_type = infer(s, env)
            s_type = apply_sub(s_type)
            if not isinstance(s_type, TList): raise ValueError("match s must be List")
            A = s_type.elem

            new_env_cons = env.copy()
            new_env_cons[hn] = A
            new_env_cons[tn] = TList(A)

            t_nil = infer(e_nil, env)
            t_cons = infer(e_cons, new_env_cons)
            unify(t_nil, t_cons)
            return apply_sub(t_nil)
        if tag == "ref":
            e = term[1]
            e_type = infer(e, env)
            return TRef(e_type)
        if tag == "get":
            r = term[1]
            r_type = infer(r, env)
            r_type = apply_sub(r_type)
            if not isinstance(r_type, TRef): raise ValueError("get r must be Ref")
            return r_type.content
        if tag == "set":
            r, e = term[1], term[2]
            r_type = infer(r, env)
            r_type = apply_sub(r_type)
            if not isinstance(r_type, TRef): raise ValueError("set r must be Ref")
            e_type = infer(e, env)
            unify(e_type, r_type.content)
            return TUnit
        raise ValueError("Unknown tag")

    final_type = infer(term, initial_env)
    final_type = apply_sub(final_type)

    # Collect vars in order of first appearance
    seen = []
    def collect(t):
        if isinstance(t, TVar):
            if t.id not in seen: seen.append(t.id)
        elif isinstance(t, TFunc):
            for a in t.args: collect(a)
            collect(t.ret)
        elif isinstance(t, TList): collect(t.elem)
        elif isinstance(t, TRef): collect(t.content)
    collect(final_type)
    var_map = {vid: f"t{i+1}" for i, vid in enumerate(seen)}

    def fmt(t):
        if isinstance(t, TVar):
            return var_map[t.id]
        elif isinstance(t, TInt): return "Int"
        elif isinstance(t, TBool): return "Bool"
        elif isinstance(t, TStr): return "Str"
        elif isinstance(t, TUnit): return "Unit"
        elif isinstance(t, TList): return f"List<{fmt(t.elem)}>"
        elif isinstance(t, TRef): return f"Ref<{fmt(t.content)}>"
        elif isinstance(t, TFunc):
            if len(t.args) == 1:
                p = fmt(t.args[0])
                if isinstance(t.args[0], TFunc): p = f"({p})"
                return f"{p} -> {fmt(t.ret)}"
            else:
                ps = ", ".join(fmt(a) for a in t.args)
                return f"({ps}) -> {fmt(t.ret)}"
        return "?"

    return fmt(final_type)

def weak_infer(term):
    def validate_term(term):
        if not isinstance(term, tuple) or len(term) == 0:
            raise ValueError("Malformed")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed")
        if tag == 'int':
            if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
                raise ValueError("Malformed")
        elif tag == 'bool':
            if len(term) != 2 or not isinstance(term[1], bool):
                raise ValueError("Malformed")
        elif tag == 'str':
            if len(term) != 2 or not isinstance(term[1], str):
                raise ValueError("Malformed")
        elif tag == 'unit':
            if len(term) != 1:
                raise ValueError("Malformed")
        elif tag == 'var':
            if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed")
        elif tag == 'fn':
            if len(term) != 3:
                raise ValueError("Malformed")
            params = term[1]
            if not isinstance(params, tuple) or len(params) == 0 or len(set(params)) != len(params):
                raise ValueError("Malformed")
            if any(not isinstance(p, str) or not p for p in params):
                raise ValueError("Malformed")
            validate_term(term[2])
        elif tag == 'call':
            if len(term) != 3:
                raise ValueError("Malformed")
            validate_term(term[1])
            args = term[2]
            if not isinstance(args, tuple) or len(args) == 0:
                raise ValueError("Malformed")
            for a in args:
                validate_term(a)
        elif tag == 'let':
            if len(term) != 4:
                raise ValueError("Malformed")
            name = term[1]
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed")
            validate_term(term[2])
            validate_term(term[3])
        elif tag == 'letrec':
            if len(term) != 4:
                raise ValueError("Malformed")
            name = term[1]
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed")
            validate_term(term[2])
            validate_term(term[3])
        elif tag == 'nil':
            if len(term) != 1:
                raise ValueError("Malformed")
        elif tag == 'cons':
            if len(term) != 3:
                raise ValueError("Malformed")
            validate_term(term[1])
            validate_term(term[2])
        elif tag == 'match':
            if len(term) != 6:
                raise ValueError("Malformed")
            validate_term(term[1])
            validate_term(term[2])
            hn, tn = term[3], term[4]
            if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn:
                raise ValueError("Malformed")
            if hn == tn:
                raise ValueError("Malformed")
            validate_term(term[5])
        elif tag == 'ref':
            if len(term) != 2:
                raise ValueError("Malformed")
            validate_term(term[1])
        elif tag == 'get':
            if len(term) != 2:
                raise ValueError("Malformed")
            validate_term(term[1])
        elif tag == 'set':
            if len(term) != 3:
                raise ValueError("Malformed")
            validate_term(term[1])
            validate_term(term[2])
        else:
            raise ValueError("Unknown tag")

    validate_term(term)

    fresh_counter = [0]
    subst = {}

    def fresh_tvar():
        fresh_counter[0] += 1
        return ('TVar', fresh_counter[0])

    def apply_subst(t):
        if t[0] == 'TVar':
            if t in subst:
                return apply_subst(subst[t])
            return t
        if t[0] == 'Fun':
            return ('Fun', tuple(apply_subst(p) for p in t[1]), apply_subst(t[2]))
        if t[0] in ('List', 'Ref'):
            return (t[0], apply_subst(t[1]))
        return t

    def occurs(x, t):
        t = apply_subst(t)
        if t[0] == 'TVar' and t[1] == x[1]:
            return True
        if t[0] == 'Fun':
            for p in t[1]:
                if occurs(x, p): return True
            return occurs(x, t[2])
        if t[0] in ('List', 'Ref'):
            return occurs(x, t[1])
        return False

    def unify(t1, t2):
        t1 = apply_subst(t1)
        t2 = apply_subst(t2)
        if t1 == t2:
            return
        if t1[0] == 'TVar':
            if t2[0] == 'TVar' and t1[1] == t2[1]:
                return
            if occurs(t1[1], t2):
                raise ValueError("Infinite type")
            subst[t1] = t2
            return
        if t2[0] == 'TVar':
            if occurs(t2[1], t1):
                raise ValueError("Infinite type")
            subst[t2] = t1
            return
        if t1[0] != t2[0]:
            raise ValueError("Type mismatch")
        if t1[0] == 'Fun':
            if len(t1[1]) != len(t2[1]):
                raise ValueError("Arity mismatch")
            for p1, p2 in zip(t1[1], t2[1]):
                unify(p1, p2)
            unify(t1[2], t2[2])
        elif t1[0] in ('List', 'Ref'):
            unify(t1[1], t2[1])
        else:
            raise ValueError("Type mismatch")

    def free_vars(t):
        t = apply_subst(t)
        if t[0] == 'TVar':
            return {t[1]}
        if t[0] == 'Fun':
            res = set()
            for p in t[1]:
                res |= free_vars(p)
            res |= free_vars(t[2])
            return res
        if t[0] in ('List', 'Ref'):
            return free_vars(t[1])
        return set()

    def generalize(env, t):
        t = apply_subst(t)
        if t[0] == 'TVar':
            return t
        if t[0] == 'Fun':
            params, ret = t[1], t[2]
            new_params = tuple(generalize(env, p) for p in params)
            new_ret = generalize(env, ret)
            return ('Fun', new_params, new_ret)
        if t[0] in ('List', 'Ref'):
            return (t[0], generalize(env, t[1]))
        return t

    env = [{}]
    t_eq1 = fresh_tvar()
    env[0]['eq'] = ('Fun', (t_eq1, t_eq1), 'Bool')
    env[0]['plus'] = ('Fun', ('Int', 'Int'), 'Int')
    env[0]['size'] = ('Fun', ('Str',), 'Int')

    def is_value(t):
        if t[0] in ('int', 'bool', 'str', 'unit', 'var', 'fn', 'nil'):
            return True
        if t[0] == 'cons':
            return is_value(t[1]) and is_value(t[2])
        return False

    def infer(term, env):
        tag = term[0]
        if tag == 'int':
            return ('Int',)
        if tag == 'bool':
            return ('Bool',)
        if tag == 'str':
            return ('Str',)
        if tag == 'unit':
            return ('Unit',)
        if tag == 'var':
            name = term[1]
            for d in reversed(env):
                if name in d:
                    return d[name]
            raise ValueError("Unbound variable")
        if tag == 'fn':
            params_names, body = term[1], term[2]
            param_types = tuple(fresh_tvar() for _ in params_names)
            new_env = env + [dict(zip(params_names, param_types))]
            body_type = infer(body, new_env)
            return ('Fun', param_types, body_type)
        if tag == 'call':
            f, args = term[1], term[2]
            f_type = apply_subst(infer(f, env))
            if f_type[0] != 'Fun':
                raise ValueError("Call on non-function")
            if len(f_type[1]) != len(args):
                raise ValueError("Arity mismatch")
            arg_types = tuple(infer(a, env) for a in args)
            for p, a in zip(f_type[1], arg_types):
                unify(p, a)
            return f_type[2]
        if tag == 'let':
            name, e1, e2 = term[1], term[2], term[3]
            e1_type = infer(e1, env)
            if is_value(e1):
                e1_type = generalize(env, e1_type)
            new_env = env + [{name: e1_type}]
            return infer(e2, new_env)
        if tag == 'letrec':
            name, e1, e2 = term[1], term[2], term[3]
            if e1[0] != 'fn':
                raise ValueError("letrec requires fn")
            rec_type = fresh_tvar()
            new_env1 = env + [{name: rec_type}]
            e1_type = infer(e1, new_env1)
            e1_type = generalize(env, e1_type)
            new_env2 = env + [{name: e1_type}]
            return infer(e2, new_env2)
        if tag == 'nil':
            return ('List', fresh_tvar())
        if tag == 'cons':
            h, t = term[1], term[2]
            h_type = infer(h, env)
            t_type = apply_subst(infer(t, env))
            if t_type[0] != 'List':
                raise ValueError("cons tail must be list")
            unify(h_type, t_type[1])
            return t_type
        if tag == 'match':
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            s_type = apply_subst(infer(s, env))
            if s_type[0] != 'List':
                raise ValueError("match scrutinee must be list")
            list_elem = s_type[1]
            new_env = env + [{hn: list_elem, tn: s_type}]
            nil_type = infer(e_nil, new_env)
            cons_type = infer(e_cons, new_env)
            unify(nil_type, cons_type)
            return nil_type
        if tag == 'ref':
            e = term[1]
            e_type = infer(e, env)
            return ('Ref', e_type)
        if tag == 'get':
            r = term[1]
            r_type = apply_subst(infer(r, env))
            if r_type[0] != 'Ref':
                raise ValueError("get on non-ref")
            return r_type[1]
        if tag == 'set':
            r, e = term[1], term[2]
            r_type = apply_subst(infer(r, env))
            if r_type[0] != 'Ref':
                raise ValueError("set on non-ref")
            e_type = infer(e, env)
            unify(r_type[1], e_type)
            return ('Unit',)
        raise ValueError("Unknown tag")

    result_type = apply_subst(infer(term, env))

    def print_type(t):
        t = apply_subst(t)
        seen = []
        var_set = set()
        def collect(t):
            if t[0] == 'TVar':
                if t[1] not in var_set:
                    var_set.add(t[1])
                    seen.append(t[1])
            elif t[0] == 'Fun':
                for p in t[1]:
                    collect(p)
                collect(t[2])
            elif t[0] in ('List', 'Ref'):
                collect(t[1])
        collect(t)
        mapping = {vid: f"t{i+1}" for i, vid in enumerate(seen)}

        def fmt(t):
            if t[0] == 'TVar':
                return mapping[t[1]]
            if t[0] == 'Int':
                return 'Int'
            if t[0] == 'Bool':
                return 'Bool'
            if t[0] == 'Str':
                return 'Str'
            if t[0] == 'Unit':
                return 'Unit'
            if t[0] == 'List':
                return f"List<{fmt(t[1])}>"
            if t[0] == 'Ref':
                return f"Ref<{fmt(t[1])}>"
            if t[0] == 'Fun':
                params, ret = t[1], t[2]
                ret_str = fmt(ret)
                if len(params) == 1:
                    p_str = fmt(params[0])
                    if params[0][0] == 'Fun':
                        p_str = f"({p_str})"
                    return f"{p_str} -> {ret_str}"
                else:
                    p_strs = [fmt(p) for p in params]
                    return f"({', '.join(p_strs)}) -> {ret_str}"
            return '?'
        return fmt(t)

    return print_type(result_type)

import copy

class Type: pass
class TVar(Type):
    __slots__ = ('id',)
    def __init__(self, id): self.id = id
class TBase(Type):
    __slots__ = ('tag',)
    def __init__(self, tag): self.tag = tag
class TList(Type):
    __slots__ = ('elem',)
    def __init__(self, elem): self.elem = elem
class TRef(Type):
    __slots__ = ('elem',)
    def __init__(self, elem): self.elem = elem
class TFunc(Type):
    __slots__ = ('args', 'ret')
    def __init__(self, args, ret):
        self.args = tuple(args)
        self.ret = ret

def _free_vars(t):
    if isinstance(t, TVar): return {t}
    if isinstance(t, TBase): return set()
    if isinstance(t, TList): return _free_vars(t.elem)
    if isinstance(t, TRef): return _free_vars(t.elem)
    if isinstance(t, TFunc):
        res = _free_vars(t.ret)
        for a in t.args: res |= _free_vars(a)
        return res
    return set()

def _is_occurs(v, t):
    if isinstance(t, TVar): return t is v
    if isinstance(t, TBase): return False
    if isinstance(t, TList): return _is_occurs(v, t.elem)
    if isinstance(t, TRef): return _is_occurs(v, t.elem)
    if isinstance(t, TFunc):
        if _is_occurs(v, t.ret): return True
        for a in t.args:
            if _is_occurs(v, a): return True
        return False
    return False

def _apply_subst(t, subst):
    if isinstance(t, TVar):
        return _apply_subst(subst.get(t, t), subst)
    if isinstance(t, TBase): return t
    if isinstance(t, TList): return TList(_apply_subst(t.elem, subst))
    if isinstance(t, TRef): return TRef(_apply_subst(t.elem, subst))
    if isinstance(t, TFunc): return TFunc(tuple(_apply_subst(a, subst) for a in t.args), _apply_subst(t.ret, subst))
    return t

def _unify(t1, t2, subst):
    t1 = _apply_subst(t1, subst)
    t2 = _apply_subst(t2, subst)
    if t1 == t2: return subst
    if isinstance(t1, TVar):
        if t1 in subst: return _unify(subst[t1], t2, subst)
        if _is_occurs(t1, t2): raise ValueError("Infinite type")
        return {**subst, t1: t2}
    if isinstance(t2, TVar):
        if t2 in subst: return _unify(t1, subst[t2], subst)
        if _is_occurs(t2, t1): raise ValueError("Infinite type")
        return {**subst, t2: t1}
    if isinstance(t1, TBase) and isinstance(t2, TBase):
        if t1.tag != t2.tag: raise ValueError("Type mismatch")
        return subst
    if isinstance(t1, TList) and isinstance(t2, TList):
        return _unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TRef) and isinstance(t2, TRef):
        return _unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        if len(t1.args) != len(t2.args): raise ValueError("Arity mismatch")
        for a1, a2 in zip(t1.args, t2.args):
            subst = _unify(a1, a2, subst)
        return _unify(t1.ret, t2.ret, subst)
    raise ValueError("Type mismatch")

def _print_type(t):
    if isinstance(t, TVar): return f"t{t.id+1}"
    if isinstance(t, TBase): return t.tag
    if isinstance(t, TList): return f"List<{_print_type(t.elem)}>"
    if isinstance(t, TRef): return f"Ref<{_print_type(t.elem)}>"
    if isinstance(t, TFunc):
        ret_str = _print_type(t.ret)
        if len(t.args) == 1:
            p = _print_type(t.args[0])
            if isinstance(t.args[0], TFunc): p = f"({p})"
            return f"{p} -> {ret_str}"
        else:
            ps = ", ".join(_print_type(a) for a in t.args)
            return f"({ps}) -> {ret_str}"
    return str(t)

def _validate(term):
    if not isinstance(term, tuple): raise ValueError("Malformed")
    if len(term) == 0: raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Malformed")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError("Malformed")
    elif tag == "unit":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0: raise ValueError("Malformed")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed")
        if len(set(params)) != len(params): raise ValueError("Malformed")
        if not all(isinstance(p, str) and len(p) > 0 for p in params): raise ValueError("Malformed")
        _validate(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed")
        f, args = term[1], term[2]
        _validate(f)
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed")
        for a in args: _validate(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed")
        _validate(e1); _validate(e2)
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed")
        _validate(e1); _validate(e2)
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed")
        _validate(term[1]); _validate(term[2])
    elif tag == "match":
        if len(term) != 6: raise ValueError("Malformed")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        _validate(s); _validate(e_nil); _validate(e_cons)
        if not isinstance(hn, str) or len(hn) == 0: raise ValueError("Malformed")
        if not isinstance(tn, str) or len(tn) == 0: raise ValueError("Malformed")
        if hn == tn: raise ValueError("Malformed")
    elif tag == "ref":
        if len(term) != 2: raise ValueError("Malformed")
        _validate(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("Malformed")
        _validate(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("Malformed")
        _validate(term[1]); _validate(term[2])
    else:
        raise ValueError("Unknown tag")

def _is_value(term):
    if not isinstance(term, tuple): return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"): return True
    if tag == "cons": return _is_value(term[1]) and _is_value(term[2])
    return False

def weak_infer(term):
    _validate(term)

    _id_counter = 0
    def fresh():
        nonlocal _id_counter
        _id_counter += 1
        return TVar(_id_counter)

    env = {
        "plus": (TFunc([TBase("Int"), TBase("Int")], TBase("Int")), None),
        "eq": (TFunc([fresh(), fresh()], TBase("Bool")), None),
        "size": (TFunc([TBase("Str")], TBase("Int")), None)
    }

    def _infer(term, env, subst):
        tag = term[0]
        if tag == "int": return TBase("Int"), subst
        if tag == "bool": return TBase("Bool"), subst
        if tag == "str": return TBase("Str"), subst
        if tag == "unit": return TBase("Unit"), subst
        if tag == "var":
            name = term[1]
            if name not in env: raise ValueError(f"Unbound variable: {name}")
            t, quant = env[name]
            if quant:
                new_subst = {v: fresh() for v in quant}
                t = _apply_subst(t, new_subst)
                subst = {**new_subst, **subst}
            return t, subst
        if tag == "fn":
            params, body = term[1], term[2]
            fresh_params = [fresh() for _ in params]
            new_env = {p: (t, None) for p, t in zip(params, fresh_params)}
            new_env.update(env)
            body_type, subst = _infer(body, new_env, subst)
            return TFunc(fresh_params, body_type), subst
        if tag == "call":
            f, args = term[1], term[2]
            f_type, subst = _infer(f, env, subst)
            f_type = _apply_subst(f_type, subst)
            if not isinstance(f_type, TFunc): raise ValueError("Call on non-function")
            if len(args) != len(f_type.args): raise ValueError("Arity mismatch")
            arg_types = []
            for arg in args:
                at, subst = _infer(arg, env, subst)
                arg_types.append(at)
            for pt, at in zip(f_type.args, arg_types):
                subst = _unify(pt, at, subst)
            return _apply_subst(f_type.ret, subst), subst
        if tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            t1, subst = _infer(e1, env, subst)
            t1 = _apply_subst(t1, subst)
            if _is_value(e1):
                fv_t = _free_vars(t1)
                fv_env = set()
                for _, (et, _) in env.items(): fv_env |= _free_vars(et)
                quant = fv_t - fv_env
            else:
                quant = None
            new_env = {name: (t1, quant)}
            new_env.update(env)
            t2, subst = _infer(e2, new_env, subst)
            return t2, subst
        if tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            if not (isinstance(e1, tuple) and len(e1) >= 3 and e1[0] == "fn"):
                raise ValueError("letrec requires fn")
            fresh_type = fresh()
            new_env = {name: (fresh_type, None)}
            new_env.update(env)
            t1, subst = _infer(e1, new_env, subst)
            t1 = _apply_subst(t1, subst)
            subst = _unify(t1, fresh_type, subst)
            t1 = _apply_subst(t1, subst)
            fv_t = _free_vars(t1)
            fv_env = set()
            for _, (et, _) in env.items(): fv_env |= _free_vars(et)
            quant = fv_t - fv_env
            new_env2 = {name: (t1, quant)}
            new_env2.update(env)
            t2, subst = _infer(e2, new_env2, subst)
            return t2, subst
        if tag == "nil":
            return TList(fresh()), subst
        if tag == "cons":
            h, t = term[1], term[2]
            ht, subst = _infer(h, env, subst)
            tt, subst = _infer(t, env, subst)
            tt = _apply_subst(tt, subst)
            if not isinstance(tt, TList): raise ValueError("cons tail must be list")
            subst = _unify(ht, tt.elem, subst)
            return tt, subst
        if tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            st, subst = _infer(s, env, subst)
            st = _apply_subst(st, subst)
            if not isinstance(st, TList): raise ValueError("match scrutinee must be list")
            elem_type = st.elem
            new_env = {hn: (elem_type, None), tn: (TList(elem_type), None)}
            new_env.update(env)
            tn_type, subst = _infer(e_nil, new_env, subst)
            tc_type, subst = _infer(e_cons, new_env, subst)
            subst = _unify(tn_type, tc_type, subst)
            return _apply_subst(tn_type, subst), subst
        if tag == "ref":
            e = term[1]
            et, subst = _infer(e, env, subst)
            return TRef(et), subst
        if tag == "get":
            r = term[1]
            rt, subst = _infer(r, env, subst)
            rt = _apply_subst(rt, subst)
            if not isinstance(rt, TRef): raise ValueError("get on non-ref")
            return rt.elem, subst
        if tag == "set":
            r, e = term[1], term[2]
            rt, subst = _infer(r, env, subst)
            et, subst = _infer(e, env, subst)
            rt = _apply_subst(rt, subst)
            if not isinstance(rt, TRef): raise ValueError("set on non-ref")
            subst = _unify(rt.elem, et, subst)
            return TBase("Unit"), subst
        raise ValueError("Unknown tag")

    res_type, _ = _infer(term, env, {})
    return _print_type(res_type)

class Type: pass
class IntType(Type): pass
class BoolType(Type): pass
class StrType(Type): pass
class UnitType(Type): pass
class VarType(Type):
    def __init__(self, idx): self.idx = idx
class ListType(Type):
    def __init__(self, elem): self.elem = elem
class RefType(Type):
    def __init__(self, elem): self.elem = elem
class FunType(Type):
    def __init__(self, args, ret): self.args = args; self.ret = ret
class PolyType:
    def __init__(self, t, quantified): self.t = t; self.quantified = quantified

class Subst(dict): pass

class InferState:
    def __init__(self):
        self.vars = []
        self.subst = Subst()
    def fresh(self):
        v = VarType(len(self.vars))
        self.vars.append(v)
        return v

def apply(subst, t):
    if isinstance(t, VarType):
        return subst.get(t, t)
    if isinstance(t, ListType): return ListType(apply(subst, t.elem))
    if isinstance(t, RefType): return RefType(apply(subst, t.elem))
    if isinstance(t, FunType):
        return FunType([apply(subst, a) for a in t.args], apply(subst, t.ret))
    return t

def free_vars(t):
    if isinstance(t, VarType): return {t.idx}
    if isinstance(t, ListType): return free_vars(t.elem)
    if isinstance(t, RefType): return free_vars(t.elem)
    if isinstance(t, FunType):
        res = set()
        for a in t.args: res |= free_vars(a)
        res |= free_vars(t.ret)
        return res
    return set()

def occurs(v, t):
    if isinstance(t, VarType): return t.idx == v.idx
    if isinstance(t, ListType): return occurs(v, t.elem)
    if isinstance(t, RefType): return occurs(v, t.elem)
    if isinstance(t, FunType):
        return any(occurs(v, a) for a in t.args) or occurs(v, t.ret)
    return False

def unify(t1, t2, subst):
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if t1 == t2: return subst
    if isinstance(t1, VarType): return unify_var(t1, t2, subst)
    if isinstance(t2, VarType): return unify_var(t2, t1, subst)
    if isinstance(t1, ListType) and isinstance(t2, ListType):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, RefType) and isinstance(t2, RefType):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, FunType) and isinstance(t2, FunType):
        if len(t1.args) != len(t2.args): raise ValueError("arity mismatch")
        for a, b in zip(t1.args, t2.args):
            subst = unify(a, b, subst)
        return unify(t1.ret, t2.ret, subst)
    raise ValueError("type mismatch")

def unify_var(v, t, subst):
    if isinstance(t, VarType) and v.idx == t.idx: return subst
    if occurs(v, t): raise ValueError("infinite type")
    return Subst({v: t, **subst})

def is_value(term):
    if not isinstance(term, tuple): return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "nil", "fn"): return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0: raise ValueError("malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("malformed")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int): raise ValueError("malformed")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("malformed")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError("malformed")
    elif tag == "unit":
        if len(term) != 1: raise ValueError("malformed")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError("malformed")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("malformed")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("malformed")
        if len(set(params)) != len(params): raise ValueError("malformed")
        for p in params:
            if not isinstance(p, str) or not p: raise ValueError("malformed")
        validate(term[2])
    elif tag == "call":
        if len(term) != 3: raise ValueError("malformed")
        validate(term[1])
        args = term[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("malformed")
        for a in args: validate(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("malformed")
        name = term[1]
        if not isinstance(name, str) or not name: raise ValueError("malformed")
        validate(term[2])
        validate(term[3])
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("malformed")
        name = term[1]
        if not isinstance(name, str) or not name: raise ValueError("malformed")
        validate(term[2])
        validate(term[3])
    elif tag == "nil":
        if len(term) != 1: raise ValueError("malformed")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("malformed")
        validate(term[1])
        validate(term[2])
    elif tag == "match":
        if len(term) != 6: raise ValueError("malformed")
        validate(term[1])
        validate(term[2])
        h_name = term[3]
        t_name = term[4]
        if not isinstance(h_name, str) or not h_name: raise ValueError("malformed")
        if not isinstance(t_name, str) or not t_name: raise ValueError("malformed")
        if h_name == t_name: raise ValueError("malformed")
        validate(term[5])
    elif tag == "ref":
        if len(term) != 2: raise ValueError("malformed")
        validate(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("malformed")
        validate(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("malformed")
        validate(term[1])
        validate(term[2])
    else:
        raise ValueError("unknown tag")

def env_free_vars(env):
    res = set()
    for t in env.values():
        if isinstance(t, PolyType):
            res |= free_vars(t.t)
        else:
            res |= free_vars(t)
    return res

def lookup(name, env, state):
    t = env[name]
    if isinstance(t, PolyType):
        inst_subst = Subst()
        for v in t.quantified:
            inst_subst[v] = state.fresh()
        return apply(inst_subst, t.t)
    return apply(state.subst, t)

def infer(term, env, state):
    tag = term[0]
    if tag == "int": return IntType()
    if tag == "bool": return BoolType()
    if tag == "str": return StrType()
    if tag == "unit": return UnitType()
    if tag == "var":
        name = term[1]
        if name not in env: raise ValueError("unbound variable")
        return lookup(name, env, state)
    if tag == "fn":
        params = term[1]
        body = term[2]
        arg_types = [state.fresh() for _ in params]
        new_env = {**env, **{p: t for p, t in zip(params, arg_types)}}
        body_type = infer(body, new_env, state)
        return FunType(arg_types, body_type)
    if tag == "call":
        f = term[1]
        args = term[2]
        f_type = infer(f, env, state)
        f_type = apply(state.subst, f_type)
        if not isinstance(f_type, FunType): raise ValueError("not a function")
        if len(args) != len(f_type.args): raise ValueError("arity mismatch")
        arg_types = []
        for a in args:
            arg_types.append(infer(a, env, state))
        for at, pt in zip(arg_types, f_type.args):
            state.subst = unify(at, pt, state.subst)
        return apply(state.subst, f_type.ret)
    if tag == "let":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        e1_type = infer(e1, env, state)
        e1_type = apply(state.subst, e1_type)
        env_fv = env_free_vars(env)
        if is_value(e1):
            fv = free_vars(e1_type)
            to_quantify = fv - env_fv
            quantified_vars = [state.vars[i] for i in to_quantify]
            new_env = {**env, name: PolyType(e1_type, quantified_vars)}
        else:
            new_env = {**env, name: e1_type}
        return infer(e2, new_env, state)
    if tag == "letrec":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        if not (isinstance(e1, tuple) and e1[0] == "fn"):
            raise ValueError("letrec requires fn")
        fresh_var = state.fresh()
        new_env = {**env, name: fresh_var}
        e1_type = infer(e1, new_env, state)
        e1_type = apply(state.subst, e1_type)
        env_fv = env_free_vars(env)
        fv = free_vars(e1_type)
        to_quantify = fv - env_fv
        quantified_vars = [state.vars[i] for i in to_quantify]
        new_env2 = {**env, name: PolyType(e1_type, quantified_vars)}
        return infer(e2, new_env2, state)
    if tag == "nil":
        return ListType(state.fresh())
    if tag == "cons":
        h = term[1]
        t = term[2]
        h_type = infer(h, env, state)
        t_type = infer(t, env, state)
        t_type = apply(state.subst, t_type)
        if not isinstance(t_type, ListType): raise ValueError("cons expects List")
        state.subst = unify(h_type, t_type.elem, state.subst)
        return t_type
    if tag == "match":
        s = term[1]
        e_nil = term[2]
        hn = term[3]
        tn = term[4]
        e_cons = term[5]
        s_type = infer(s, env, state)
        s_type = apply(state.subst, s_type)
        if not isinstance(s_type, ListType): raise ValueError("match expects List")
        A = s_type.elem
        new_env1 = {**env, hn: A}
        new_env2 = {**env, tn: ListType(A)}
        t_nil = infer(e_nil, new_env1, state)
        t_cons = infer(e_cons, new_env2, state)
        state.subst = unify(t_nil, t_cons, state.subst)
        return apply(state.subst, t_nil)
    if tag == "ref":
        e = term[1]
        e_type = infer(e, env, state)
        return RefType(e_type)
    if tag == "get":
        r = term[1]
        r_type = infer(r, env, state)
        r_type = apply(state.subst, r_type)
        if not isinstance(r_type, RefType): raise ValueError("get expects Ref")
        return r_type.elem
    if tag == "set":
        r = term[1]
        e = term[2]
        r_type = infer(r, env, state)
        r_type = apply(state.subst, r_type)
        if not isinstance(r_type, RefType): raise ValueError("set expects Ref")
        e_type = infer(e, env, state)
        state.subst = unify(e_type, r_type.elem, state.subst)
        return UnitType()
    raise ValueError("unknown tag")

def print_type(t):
    if isinstance(t, IntType): return "Int"
    if isinstance(t, BoolType): return "Bool"
    if isinstance(t, StrType): return "Str"
    if isinstance(t, UnitType): return "Unit"
    if isinstance(t, VarType): return f"t{t.idx+1}"
    if isinstance(t, ListType): return f"List<{print_type(t.elem)}>"
    if isinstance(t, RefType): return f"Ref<{print_type(t.elem)}>"
    if isinstance(t, FunType):
        args_str = ", ".join(print_type(a) for a in t.args)
        ret_str = print_type(t.ret)
        if len(t.args) == 1:
            p = print_type(t.args[0])
            if isinstance(t.args[0], FunType):
                return f"({p}) -> {ret_str}"
            return f"{p} -> {ret_str}"
        else:
            return f"({args_str}) -> {ret_str}"
    raise ValueError("unknown type")

def weak_infer(term):
    validate(term)
    state = InferState()
    plus_type = FunType([IntType(), IntType()], IntType())
    size_type = FunType([StrType()], IntType())
    eq_var = state.fresh()
    eq_type = FunType([eq_var, eq_var], BoolType())
    env = {
        "plus": plus_type,
        "eq": PolyType(eq_type, [eq_var]),
        "size": size_type
    }
    result = infer(term, env, state)
    result = apply(state.subst, result)
    return print_type(result)

class TypeVar:
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return f"t{self.id}"

class IntType: pass
class BoolType: pass
class StrType: pass
class UnitType: pass

class ListType:
    def __init__(self, elem): self.elem = elem
class RefType:
    def __init__(self, elem): self.elem = elem

class FuncType:
    def __init__(self, params, ret):
        self.params = params
        self.ret = ret

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit"): return True
    if tag == "var": return True
    if tag == "fn": return True
    if tag == "nil": return True
    if tag == "cons": return is_value(term[1]) and is_value(term[2])
    return False

def free_vars(t):
    if isinstance(t, TypeVar): return {t}
    if isinstance(t, (IntType, BoolType, StrType, UnitType)): return set()
    if isinstance(t, ListType): return free_vars(t.elem)
    if isinstance(t, RefType): return free_vars(t.elem)
    if isinstance(t, FuncType):
        res = set()
        for p in t.params: res.update(free_vars(p))
        res.update(free_vars(t.ret))
        return res
    return set()

def occurs(v, t):
    if isinstance(t, TypeVar): return t.id == v.id
    if isinstance(t, (IntType, BoolType, StrType, UnitType)): return False
    if isinstance(t, ListType): return occurs(v, t.elem)
    if isinstance(t, RefType): return occurs(v, t.elem)
    if isinstance(t, FuncType):
        for p in t.params:
            if occurs(v, p): return True
        return occurs(v, t.ret)
    return False

def apply_subst(t, subst):
    if isinstance(t, TypeVar):
        return subst.get(t, t)
    if isinstance(t, ListType):
        return ListType(apply_subst(t.elem, subst))
    if isinstance(t, RefType):
        return RefType(apply_subst(t.elem, subst))
    if isinstance(t, FuncType):
        return FuncType(tuple(apply_subst(p, subst) for p in t.params), apply_subst(t.ret, subst))
    return t

def unify(t1, t2, subst):
    t1 = apply_subst(t1, subst)
    t2 = apply_subst(t2, subst)
    if isinstance(t1, TypeVar) and isinstance(t2, TypeVar) and t1.id == t2.id:
        return subst
    if isinstance(t1, TypeVar):
        if t1 in subst:
            return unify(subst[t1], t2, subst)
        if occurs(t1, t2):
            raise ValueError("Infinite type")
        new_subst = {**subst, t1: t2}
        return unify(apply_subst(t1, new_subst), apply_subst(t2, new_subst), new_subst)
    if isinstance(t2, TypeVar):
        return unify(t2, t1, subst)
    if isinstance(t1, IntType) and isinstance(t2, IntType): return subst
    if isinstance(t1, BoolType) and isinstance(t2, BoolType): return subst
    if isinstance(t1, StrType) and isinstance(t2, StrType): return subst
    if isinstance(t1, UnitType) and isinstance(t2, UnitType): return subst
    if isinstance(t1, ListType) and isinstance(t2, ListType):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, RefType) and isinstance(t2, RefType):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, FuncType) and isinstance(t2, FuncType):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            subst = unify(p1, p2, subst)
        return unify(t1.ret, t2.ret, subst)
    raise ValueError("Type mismatch")

def weak_infer(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")

    # Validation
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term")

    def validate(t):
        if not isinstance(t, tuple) or len(t) == 0: raise ValueError("Malformed")
        tg = t[0]
        if not isinstance(tg, str): raise ValueError("Malformed")
        if tg == "int":
            if len(t) != 2 or not isinstance(t[1], int) or isinstance(t[1], bool): raise ValueError("Malformed")
        elif tg == "bool":
            if len(t) != 2 or not isinstance(t[1], bool): raise ValueError("Malformed")
        elif tg == "str":
            if len(t) != 2 or not isinstance(t[1], str) or not t[1]: raise ValueError("Malformed")
        elif tg == "unit":
            if len(t) != 1: raise ValueError("Malformed")
        elif tg == "var":
            if len(t) != 2 or not isinstance(t[1], str) or not t[1]: raise ValueError("Malformed")
        elif tg == "fn":
            if len(t) != 3: raise ValueError("Malformed")
            params, body = t[1], t[2]
            if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed")
            if not all(isinstance(p, str) and p for p in params): raise ValueError("Malformed")
            if len(set(params)) != len(params): raise ValueError("Malformed")
            validate(body)
        elif tg == "call":
            if len(t) != 3: raise ValueError("Malformed")
            f, args = t[1], t[2]
            if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed")
            validate(f)
            for a in args: validate(a)
        elif tg == "let":
            if len(t) != 4: raise ValueError("Malformed")
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(name, str) or not name: raise ValueError("Malformed")
            validate(e1); validate(e2)
        elif tg == "letrec":
            if len(t) != 4: raise ValueError("Malformed")
            name, e1, e2 = t[1], t[2], t[3]
            if not isinstance(name, str) or not name: raise ValueError("Malformed")
            validate(e1); validate(e2)
            if e1[0] != "fn": raise ValueError("letrec requires fn")
        elif tg == "nil":
            if len(t) != 1: raise ValueError("Malformed")
        elif tg == "cons":
            if len(t) != 3: raise ValueError("Malformed")
            validate(t[1]); validate(t[2])
        elif tg == "match":
            if len(t) != 5: raise ValueError("Malformed")
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            if not isinstance(hn, str) or not hn: raise ValueError("Malformed")
            if not isinstance(tn, str) or not tn: raise ValueError("Malformed")
            if hn == tn: raise ValueError("Malformed")
            validate(s); validate(e_nil); validate(e_cons)
        elif tg == "ref":
            if len(t) != 2: raise ValueError("Malformed")
            validate(t[1])
        elif tg == "get":
            if len(t) != 2: raise ValueError("Malformed")
            validate(t[1])
        elif tg == "set":
            if len(t) != 3: raise ValueError("Malformed")
            validate(t[1]); validate(t[2])
        else:
            raise ValueError("Unknown tag")

    validate(term)

    # Inference state
    fresh_count = 0
    subst = {}
    env = {}
    a = fresh_count; fresh_count += 1; env['plus'] = FuncType((IntType(), IntType()), IntType())
    env['eq'] = FuncType((TypeVar(a), TypeVar(a)), BoolType())
    env['size'] = FuncType((StrType(),), IntType())

    def fresh():
        nonlocal fresh_count
        fresh_count += 1
        return TypeVar(fresh_count)

    def get_env_types():
        res = set()
        for ty in env.values():
            res.update(free_vars(ty))
        return res

    def _infer(t):
        tag = t[0]
        if tag == "int": return IntType()
        if tag == "bool": return BoolType()
        if tag == "str": return StrType()
        if tag == "unit": return UnitType()
        if tag == "var":
            name = t[1]
            if name not in env: raise ValueError("Unbound variable")
            return apply_subst(env[name], subst)
        if tag == "fn":
            params, body = t[1], t[2]
            fp = tuple(fresh() for _ in params)
            old_env = env.copy()
            for p, ty in zip(params, fp): env[p] = ty
            bt = _infer(body)
            env = old_env
            return FuncType(fp, bt)
        if tag == "call":
            f, args = t[1], t[2]
            ft = apply_subst(_infer(f), subst)
            if not isinstance(ft, FuncType): raise ValueError("Call on non-function")
            if len(ft.params) != len(args): raise ValueError("Arity mismatch")
            ats = [_infer(a) for a in args]
            for p, at in zip(ft.params, ats):
                subst = unify(p, at, subst)
            return apply_subst(ft.ret, subst)
        if tag == "let":
            name, e1, e2 = t[1], t[2], t[3]
            e1t = apply_subst(_infer(e1), subst)
            if is_value(e1):
                env_fv = get_env_types()
                fv = free_vars(e1t)
                quantified = fv - env_fv
                nt = e1t
                for v in quantified:
                    nt = apply_subst(nt, {v: fresh()})
                e1t = nt
            env[name] = e1t
            return _infer(e2)
        if tag == "letrec":
            name, e1, e2 = t[1], t[2], t[3]
            env_fv = get_env_types()
            nt = fresh()
            old_env = env.copy()
            env[name] = nt
            e1t = apply_subst(_infer(e1), subst)
            subst = unify(nt, e1t, subst)
            fv = free_vars(e1t)
            quantified = fv - env_fv
            gt = e1t
            for v in quantified:
                gt = apply_subst(gt, {v: fresh()})
            e1t = gt
            env = old_env
            env[name] = e1t
            return _infer(e2)
        if tag == "nil":
            return ListType(fresh())
        if tag == "cons":
            h, tail = t[1], t[2]
            ht = _infer(h)
            tt = apply_subst(_infer(tail), subst)
            if not isinstance(tt, ListType): raise ValueError("cons requires list tail")
            subst = unify(ht, tt.elem, subst)
            return apply_subst(tt, subst)
        if tag == "match":
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            st = apply_subst(_infer(s), subst)
            if not isinstance(st, ListType): raise ValueError("match requires list")
            A = st.elem
            old_env = env.copy()
            env[hn] = A; env[tn] = ListType(A)
            nilt = _infer(e_nil)
            consn = _infer(e_cons)
            subst = unify(nilt, consn, subst)
            env = old_env
            return apply_subst(nilt, subst)
        if tag == "ref":
            return RefType(_infer(t[1]))
        if tag == "get":
            rt = apply_subst(_infer(t[1]), subst)
            if not isinstance(rt, RefType): raise ValueError("get requires ref")
            return rt.elem
        if tag == "set":
            rt = apply_subst(_infer(t[1]), subst)
            if not isinstance(rt, RefType): raise ValueError("set requires ref")
            et = _infer(t[2])
            subst = unify(rt.elem, et, subst)
            return UnitType()
        raise ValueError("Unknown tag")

    res_type = _infer(term)
    res_type = apply_subst(res_type, subst)

    # Formatting
    var_map = {}
    counter = [0]
    def assign(v):
        if v not in var_map:
            counter[0] += 1
            var_map[v] = counter[0]
        return f"t{var_map[v]}"

    def fmt(t):
        if isinstance(t, TypeVar): return assign(t)
        if isinstance(t, IntType): return "Int"
        if isinstance(t, BoolType): return "Bool"
        if isinstance(t, StrType): return "Str"
        if isinstance(t, UnitType): return "Unit"
        if isinstance(t, ListType): return f"List<{fmt(t.elem)}>"
        if isinstance(t, RefType): return f"Ref<{fmt(t.elem)}>"
        if isinstance(t, FuncType):
            params_str = ", ".join(fmt(p) for p in t.params)
            ret_str = fmt(t.ret)
            if len(t.params) == 1:
                p = t.params[0]
                if isinstance(p, FuncType):
                    return f"({params_str}) -> {ret_str}"
                else:
                    return f"{params_str} -> {ret_str}"
            else:
                return f"({params_str}) -> {ret_str}"
        return str(t)

    return fmt(res_type)

import sys

class Type: pass
class TVar(Type):
    def __init__(self, idx): self.idx = idx
class TInt(Type): pass
class TBool(Type): pass
class TStr(Type): pass
class TUnit(Type): pass
class TList(Type):
    def __init__(self, t): self.t = t
class TRef(Type):
    def __init__(self, t): self.t = t
class TFunc(Type):
    def __init__(self, args, ret): self.args = args; self.ret = ret

var_counter = 0
var_order = []

def fresh():
    global var_counter
    idx = var_counter
    var_counter += 1
    var_order.append(idx)
    return TVar(idx)

def apply_sub(t, subs):
    if isinstance(t, TVar):
        while t in subs:
            t = subs[t]
        return t
    elif isinstance(t, TList):
        return TList(apply_sub(t.t, subs))
    elif isinstance(t, TRef):
        return TRef(apply_sub(t.t, subs))
    elif isinstance(t, TFunc):
        return TFunc(tuple(apply_sub(a, subs) for a in t.args), apply_sub(t.ret, subs))
    return t

def occurs(v, t):
    if isinstance(t, TVar):
        return t == v
    elif isinstance(t, TList):
        return occurs(v, t.t)
    elif isinstance(t, TRef):
        return occurs(v, t.t)
    elif isinstance(t, TFunc):
        return any(occurs(v, a) for a in t.args) or occurs(v, t.ret)
    return False

def unify(t1, t2, subs):
    t1 = apply_sub(t1, subs)
    t2 = apply_sub(t2, subs)
    if t1 == t2: return
    if isinstance(t1, TVar):
        if isinstance(t2, TVar):
            subs[t1] = t2
        else:
            if occurs(t1, t2): raise ValueError
            subs[t1] = t2
    elif isinstance(t2, TVar):
        if occurs(t2, t1): raise ValueError
        subs[t2] = t1
    elif type(t1) != type(t2):
        raise ValueError
    elif isinstance(t1, TFunc):
        if len(t1.args) != len(t2.args): raise ValueError
        for a, b in zip(t1.args, t2.args): unify(a, b, subs)
        unify(t1.ret, t2.ret, subs)
    elif isinstance(t1, TList):
        unify(t1.t, t2.t, subs)
    elif isinstance(t1, TRef):
        unify(t1.t, t2.t, subs)
    else:
        raise ValueError

def get_free_vars(t, fvs):
    if isinstance(t, TVar):
        fvs.add(t.idx)
    elif isinstance(t, TList):
        get_free_vars(t.t, fvs)
    elif isinstance(t, TRef):
        get_free_vars(t.t, fvs)
    elif isinstance(t, TFunc):
        for a in t.args: get_free_vars(a, fvs)
        get_free_vars(t.ret, fvs)

def get_env_free_vars(env):
    fvs = set()
    for scope in env:
        for _, (t, _) in scope.items():
            get_free_vars(t, fvs)
    return fvs

def gen(t, env, subs):
    t = apply_sub(t, subs)
    return t

def instantiate(t):
    if isinstance(t, TVar):
        return fresh()
    elif isinstance(t, TList):
        return TList(instantiate(t.t))
    elif isinstance(t, TRef):
        return TRef(instantiate(t.t))
    elif isinstance(t, TFunc):
        return TFunc(tuple(instantiate(a) for a in t.args), instantiate(t.ret))
    return t

def is_value(term):
    tag = term[0]
    if tag in ('int', 'bool', 'str', 'unit'): return True
    if tag == 'var': return True
    if tag == 'fn': return True
    if tag == 'nil': return True
    if tag == 'cons': return is_value(term[1]) and is_value(term[2])
    return False

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term")
    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
    elif tag == 'str':
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
    elif tag == 'unit':
        if len(term) != 1: raise ValueError("Malformed unit")
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed var")
    elif tag == 'fn':
        if len(term) != 3: raise ValueError("Malformed fn")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed fn params")
        if len(params) != len(set(params)):
            raise ValueError("Duplicate fn params")
        if not all(isinstance(p, str) and p for p in params):
            raise ValueError("Malformed fn param names")
        validate(term[2])
    elif tag == 'call':
        if len(term) != 3: raise ValueError("Malformed call")
        if not isinstance(term[2], tuple) or len(term[2]) == 0:
            raise ValueError("Malformed call args")
        validate(term[1])
        for a in term[2]: validate(a)
    elif tag == 'let':
        if len(term) != 4: raise ValueError("Malformed let")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed let name")
        validate(term[2])
        validate(term[3])
    elif tag == 'letrec':
        if len(term) != 4: raise ValueError("Malformed letrec")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed letrec name")
        validate(term[2])
        validate(term[3])
    elif tag == 'nil':
        if len(term) != 1: raise ValueError("Malformed nil")
    elif tag == 'cons':
        if len(term) != 3: raise ValueError("Malformed cons")
        validate(term[1])
        validate(term[2])
    elif tag == 'match':
        if len(term) != 6: raise ValueError("Malformed match")
        validate(term[1])
        validate(term[2])
        validate(term[5])
        hn, tn = term[3], term[4]
        if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn:
            raise ValueError("Malformed match names")
        if hn == tn: raise ValueError("Match names must differ")
    elif tag == 'ref':
        if len(term) != 2: raise ValueError("Malformed ref")
        validate(term[1])
    elif tag == 'get':
        if len(term) != 2: raise ValueError("Malformed get")
        validate(term[1])
    elif tag == 'set':
        if len(term) != 3: raise ValueError("Malformed set")
        validate(term[1])
        validate(term[2])
    else:
        raise ValueError("Unknown tag")

def print_type(t, subs):
    t = apply_sub(t, subs)
    def fmt(t):
        if isinstance(t, TVar):
            return f"t{t.idx}"
        elif isinstance(t, TInt): return "Int"
        elif isinstance(t, TBool): return "Bool"
        elif isinstance(t, TStr): return "Str"
        elif isinstance(t, TUnit): return "Unit"
        elif isinstance(t, TList):
            return f"List<{fmt(t.t)}>"
        elif isinstance(t, TRef):
            return f"Ref<{fmt(t.t)}>"
        elif isinstance(t, TFunc):
            if len(t.args) == 1:
                p = fmt(t.args[0])
                if isinstance(t.args[0], TFunc):
                    p = f"({p})"
                return f"{p} -> {fmt(t.ret)}"
            else:
                ps = ", ".join(fmt(a) for a in t.args)
                return f"({ps}) -> {fmt(t.ret)}"
        return str(t)
    return fmt(t)

def weak_infer(term):
    global var_counter, var_order
    var_counter = 0
    var_order = []
    validate(term)
    env = [{}]
    subs = {}

    def bind(name, t, generalized):
        env[-1][name] = (t, generalized)

    def lookup(name):
        for scope in reversed(env):
            if name in scope:
                return scope[name]
        raise ValueError(f"Unbound variable {name}")

    def pop_scope():
        env.pop()

    def push_scope():
        env.append({})

    def infer(t):
        tag = t[0]
        if tag == 'int': return TInt()
        if tag == 'bool': return TBool()
        if tag == 'str': return TStr()
        if tag == 'unit': return TUnit()
        if tag == 'var':
            name = t[1]
            t_val, gen = lookup(name)
            if gen:
                return instantiate(t_val)
            return t_val
        if tag == 'fn':
            params = t[1]
            body = t[2]
            push_scope()
            param_types = []
            for p in params:
                pt = fresh()
                param_types.append(pt)
                bind(p, pt, False)
            body_type = infer(body)
            pop_scope()
            return TFunc(tuple(param_types), body_type)
        if tag == 'call':
            f = t[1]
            args = t[2]
            f_type = infer(f)
            if not isinstance(f_type, TFunc):
                raise ValueError("Call on non-function")
            if len(f_type.args) != len(args):
                raise ValueError("Arity mismatch")
            arg_types = [infer(a) for a in args]
            for pt, at in zip(f_type.args, arg_types):
                unify(pt, at, subs)
            return f_type.ret
        if tag == 'let':
            name = t[1]
            e1 = t[2]
            e2 = t[3]
            t1 = infer(e1)
            if is_value(e1):
                t_gen = gen(t1, env, subs)
                bind(name, t_gen, True)
            else:
                bind(name, t1, False)
            return infer(e2)
        if tag == 'letrec':
            name = t[1]
            e1 = t[2]
            e2 = t[3]
            if e1[0] != 'fn':
                raise ValueError("letrec requires fn")
            push_scope()
            bind(name, fresh(), True)
            t1 = infer(e1)
            pop_scope()
            t_gen = gen(t1, env, subs)
            bind(name, t_gen, True)
            return infer(e2)
        if tag == 'nil':
            return TList(fresh())
        if tag == 'cons':
            h = t[1]
            tt = t[2]
            th = infer(h)
            t_list = infer(tt)
            if not isinstance(t_list, TList):
                raise ValueError("cons tail must be List")
            unify(th, t_list.t, subs)
            return t_list
        if tag == 'match':
            s = t[1]
            e_nil = t[2]
            hn = t[3]
            tn = t[4]
            e_cons = t[5]
            t_list = infer(s)
            if not isinstance(t_list, TList):
                raise ValueError("match scrutinee must be List")
            t_elem = t_list.t
            push_scope()
            bind(hn, t_elem, False)
            bind(tn, TList(t_elem), False)
            t_cons = infer(e_cons)
            t_nil = infer(e_nil)
            unify(t_cons, t_nil, subs)
            pop_scope()
            return t_cons
        if tag == 'ref':
            e = t[1]
            t_e = infer(e)
            return TRef(t_e)
        if tag == 'get':
            r = t[1]
            t_r = infer(r)
            if not isinstance(t_r, TRef):
                raise ValueError("get on non-Ref")
            return t_r.t
        if tag == 'set':
            r = t[1]
            e = t[2]
            t_r = infer(r)
            if not isinstance(t_r, TRef):
                raise ValueError("set on non-Ref")
            t_e = infer(e)
            unify(t_r.t, t_e, subs)
            return TUnit()

    result = infer(term)
    return print_type(result, subs)

import copy

class Type:
    def __init__(self, tag, **kw):
        self.tag = tag
        for k, v in kw.items():
            setattr(self, k, v)
    def __repr__(self):
        return f"<Type {self.tag}>"

def unify(t1, t2, subst):
    def apply(s, t):
        if isinstance(t, Type) and t.tag == 'tvar':
            return s.get(t, t)
        if not isinstance(t, Type): return t
        new_fields = {}
        for k in t.__dict__:
            if k == 'tag': continue
            v = getattr(t, k)
            if isinstance(v, Type):
                new_fields[k] = apply(s, v)
            elif isinstance(v, list):
                new_fields[k] = [apply(s, x) for x in v]
            else:
                new_fields[k] = v
        res = Type(t.tag, **new_fields)
        if hasattr(t, 'id'): res.id = t.id
        return res

    t1 = apply(subst, t1)
    t2 = apply(subst, t2)

    if isinstance(t1, Type) and t1.tag == 'tvar':
        if t1 is t2: return subst
        if isinstance(t2, Type) and t2.tag == 'tvar':
            if t1.id is None or t2.id is None or t1.id == t2.id:
                if t1 is not t2: subst[t1] = t2
                return subst
            raise ValueError("Type mismatch")
        if occurs_in(t1, t2): raise ValueError("Infinite type")
        subst[t1] = t2
        return subst
    if isinstance(t2, Type) and t2.tag == 'tvar':
        return unify(t2, t1, subst)
    if isinstance(t1, Type) and isinstance(t2, Type) and t1.tag == t2.tag:
        if t1.tag in ('int', 'bool', 'str', 'unit'): return subst
        if t1.tag == 'list': return unify(t1.elem, t2.elem, subst)
        if t1.tag == 'ref': return unify(t1.elem, t2.elem, subst)
        if t1.tag == 'fun':
            if len(t1.args) != len(t2.args): raise ValueError("Arity mismatch")
            s = subst
            for a, b in zip(t1.args, t2.args): s = unify(a, b, s)
            s = unify(t1.ret, t2.ret, s)
            return s
    raise ValueError("Type mismatch")

def occurs_in(v, t):
    if isinstance(t, Type) and t.tag == 'tvar': return v is t
    if not isinstance(t, Type): return False
    if t.tag in ('list', 'ref'): return occurs_in(v, t.elem)
    if t.tag == 'fun':
        for a in t.args:
            if occurs_in(v, a): return True
        return occurs_in(v, t.ret)
    return False

def free_vars(t):
    if isinstance(t, Type) and t.tag == 'tvar': return {t}
    if not isinstance(t, Type): return set()
    vs = set()
    if t.tag in ('list', 'ref'): vs |= free_vars(t.elem)
    elif t.tag == 'fun':
        for a in t.args: vs |= free_vars(a)
        vs |= free_vars(t.ret)
    return vs

def instantiate(t, qvars):
    mapping = {v: Type('tvar') for v in qvars}
    def apply(s, t):
        if isinstance(t, Type) and t.tag == 'tvar': return s.get(t, t)
        if not isinstance(t, Type): return t
        new_fields = {}
        for k in t.__dict__:
            if k == 'tag': continue
            v = getattr(t, k)
            if isinstance(v, Type): new_fields[k] = apply(s, v)
            elif isinstance(v, list): new_fields[k] = [apply(s, x) for x in v]
            else: new_fields[k] = v
        res = Type(t.tag, **new_fields)
        if hasattr(t, 'id'): res.id = t.id
        return res
    return apply(mapping, t)

def get_env_vars(env):
    vs = set()
    for binding in env:
        for t, _ in binding.values():
            vs |= free_vars(t)
    return vs

def is_value(term):
    if not isinstance(term, tuple) or len(term) == 0: return False
    tag = term[0]
    if tag in ('int', 'bool', 'str', 'unit', 'var', 'fn', 'nil'): return True
    if tag == 'cons': return is_value(term[1]) and is_value(term[2])
    return False

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0: raise ValueError
    tag = term[0]
    if not isinstance(tag, str): raise ValueError
    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError
    elif tag == 'str':
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError
    elif tag == 'unit':
        if len(term) != 1: raise ValueError
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError
    elif tag == 'fn':
        if len(term) != 3: raise ValueError
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or not params or len(set(params)) != len(params): raise ValueError
        if not all(isinstance(p, str) and p for p in params): raise ValueError
        validate(body)
    elif tag == 'call':
        if len(term) != 3: raise ValueError
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or not args: raise ValueError
        validate(f)
        for a in args: validate(a)
    elif tag == 'let':
        if len(term) != 4: raise ValueError
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name: raise ValueError
        validate(e1); validate(e2)
    elif tag == 'letrec':
        if len(term) != 4: raise ValueError
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name: raise ValueError
        validate(e1); validate(e2)
    elif tag == 'nil':
        if len(term) != 1: raise ValueError
    elif tag == 'cons':
        if len(term) != 3: raise ValueError
        validate(term[1]); validate(term[2])
    elif tag == 'match':
        if len(term) != 6: raise ValueError
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not hn: raise ValueError
        if not isinstance(tn, str) or not tn: raise ValueError
        if hn == tn: raise ValueError
        validate(s); validate(e_nil); validate(e_cons)
    elif tag == 'ref':
        if len(term) != 2: raise ValueError
        validate(term[1])
    elif tag == 'get':
        if len(term) != 2: raise ValueError
        validate(term[1])
    elif tag == 'set':
        if len(term) != 3: raise ValueError
        validate(term[1]); validate(term[2])
    else:
        raise ValueError("Unknown tag")

def infer(term, env, subst):
    tag = term[0]
    if tag == 'int': return Type('int'), subst
    if tag == 'bool': return Type('bool'), subst
    if tag == 'str': return Type('str'), subst
    if tag == 'unit': return Type('unit'), subst
    if tag == 'var':
        name = term[1]
        for binding in reversed(env):
            if name in binding:
                t, qvars = binding[name]
                return instantiate(t, qvars), subst
        raise ValueError("Unbound variable")
    if tag == 'fn':
        params, body = term[1], term[2]
        param_types = [Type('tvar') for _ in params]
        new_env = env + [{p: (pt, set()) for p, pt in zip(params, param_types)}]
        ret_type, subst = infer(body, new_env, subst)
        return Type('fun', args=param_types, ret=ret_type), subst
    if tag == 'call':
        f, args = term[1], term[2]
        f_type, subst = infer(f, env, subst)
        f_type = unify(Type('tvar'), f_type, {}).get(list(f_type.__dict__.keys())[0], f_type) if False else f_type
        # Apply subst properly
        def apply_subst(s, t):
            if isinstance(t, Type) and t.tag == 'tvar': return s.get(t, t)
            if not isinstance(t, Type): return t
            nf = {}
            for k in t.__dict__:
                if k == 'tag': continue
                v = getattr(t, k)
                if isinstance(v, Type): nf[k] = apply_subst(s, v)
                elif isinstance(v, list): nf[k] = [apply_subst(s, x) for x in v]
                else: nf[k] = v
            res = Type(t.tag, **nf)
            if hasattr(t, 'id'): res.id = t.id
            return res
        f_type = apply_subst(subst, f_type)
        if not isinstance(f_type, Type) or f_type.tag != 'fun': raise ValueError("Not a function")
        if len(args) != len(f_type.args): raise ValueError("Arity mismatch")
        arg_types = []
        for a in args:
            at, subst = infer(a, env, subst)
            arg_types.append(at)
        for pt, at in zip(f_type.args, arg_types):
            subst = unify(pt, at, subst)
        ret = apply_subst(subst, f_type.ret)
        return ret, subst
    if tag == 'let':
        name, e1, e2 = term[1], term[2], term[3]
        t1, subst = infer(e1, env, subst)
        t1 = apply_subst(subst, t1)
        if is_value(e1):
            qvars = free_vars(t1) - get_env_vars(env)
        else:
            qvars = set()
        new_env = env + [{name: (t1, qvars)}]
        return infer(e2, new_env, subst)
    if tag == 'letrec':
        name, e1, e2 = term[1], term[2], term[3]
        if not (isinstance(e1, tuple) and e1[0] == 'fn'): raise ValueError("letrec requires fn")
        fresh_var = Type('tvar')
        temp_env = env + [{name: (fresh_var, set())}]
        t1, subst = infer(e1, temp_env, subst)
        t1 = apply_subst(subst, t1)
        qvars = free_vars(t1) - get_env_vars(env)
        new_env = env + [{name: (t1, qvars)}]
        return infer(e2, new_env, subst)
    if tag == 'nil':
        return Type('list', elem=Type('tvar')), subst
    if tag == 'cons':
        h, t = term[1], term[2]
        ht, subst = infer(h, env, subst)
        ht = apply_subst(subst, ht)
        tt, subst = infer(t, env, subst)
        tt = apply_subst(subst, tt)
        if not isinstance(tt, Type) or tt.tag != 'list': raise ValueError("cons tail must be list")
        subst = unify(ht, tt.elem, subst)
        return tt, subst
    if tag == 'match':
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        st, subst = infer(s, env, subst)
        st = apply_subst(subst, st)
        if not isinstance(st, Type) or st.tag != 'list': raise ValueError("match scrutinee must be list")
        elem_type = st.elem
        new_env = env + [{hn: (elem_type, set()), tn: (Type('list', elem=elem_type), set())}]
        tn_type, subst = infer(e_nil, new_env, subst)
        tn_type = apply_subst(subst, tn_type)
        te_type, subst = infer(e_cons, new_env, subst)
        te_type = apply_subst(subst, te_type)
        subst = unify(tn_type, te_type, subst)
        return apply_subst(subst, tn_type), subst
    if tag == 'ref':
        e, = term[1]
        et, subst = infer(e, env, subst)
        return Type('ref', elem=et), subst
    if tag == 'get':
        r, = term[1]
        rt, subst = infer(r, env, subst)
        rt = apply_subst(subst, rt)
        if not isinstance(rt, Type) or rt.tag != 'ref': raise ValueError("get on non-ref")
        return rt.elem, subst
    if tag == 'set':
        r, e = term[1], term[2]
        rt, subst = infer(r, env, subst)
        rt = apply_subst(subst, rt)
        if not isinstance(rt, Type) or rt.tag != 'ref': raise ValueError("set on non-ref")
        et, subst = infer(e, env, subst)
        et = apply_subst(subst, et)
        subst = unify(et, rt.elem, subst)
        return Type('unit'), subst
    raise ValueError("Unknown tag")

def weak_infer(term):
    validate(term)
    # Initial env
    v_eq = Type('tvar')
    env = [
        {"plus": (Type('fun', args=[Type('int'), Type('int')], ret=Type('int')), set())},
        {"eq": (Type('fun', args=[v_eq, v_eq], ret=Type('bool')), {v_eq})},
        {"size": (Type('fun', args=[Type('str')], ret=Type('int')), set())}
    ]
    subst = {}
    res_type, _ = infer(term, env, subst)
    res_type = apply_subst(subst, res_type)

    counter = []
    def print_type(t):
        if isinstance(t, Type) and t.tag == 'tvar':
            if not hasattr(t, 'id'):
                t.id = len(counter) + 1
                counter.append(t)
            return f"t{t.id}"
        if isinstance(t, Type):
            if t.tag == 'int': return "Int"
            if t.tag == 'bool': return "Bool"
            if t.tag == 'str': return "Str"
            if t.tag == 'unit': return "Unit"
            if t.tag == 'list': return f"List<{print_type(t.elem)}>"
            if t.tag == 'ref': return f"Ref<{print_type(t.elem)}>"
            if t.tag == 'fun':
                args_str = ", ".join(print_type(a) for a in t.args)
                ret_str = print_type(t.ret)
                if len(t.args) == 1:
                    p = print_type(t.args[0])
                    if t.args[0].tag == 'fun': p = f"({p})"
                    return f"{p} -> {ret_str}"
                else:
                    return f"({args_str}) -> {ret_str}"
        return str(t)

    return print_type(res_type)

class TypeVar:
    __slots__ = ('id',)
    def __init__(self, id):
        self.id = id
    def __eq__(self, other):
        return isinstance(other, TypeVar) and self.id == other.id
    def __hash__(self):
        return self.id

class BaseType:
    __slots__ = ('name',)
    def __init__(self, name):
        self.name = name
    def __eq__(self, other):
        return isinstance(other, BaseType) and self.name == other.name
    def __hash__(self):
        return hash(self.name)

class ListType:
    __slots__ = ('inner',)
    def __init__(self, inner):
        self.inner = inner
    def __eq__(self, other):
        return isinstance(other, ListType) and self.inner == other.inner
    def __hash__(self):
        return hash(('List', self.inner))

class RefType:
    __slots__ = ('inner',)
    def __init__(self, inner):
        self.inner = inner
    def __eq__(self, other):
        return isinstance(other, RefType) and self.inner == other.inner
    def __hash__(self):
        return hash(('Ref', self.inner))

class FuncType:
    __slots__ = ('args', 'ret')
    def __init__(self, args, ret):
        self.args = args
        self.ret = ret
    def __eq__(self, other):
        return isinstance(other, FuncType) and self.args == other.args and self.ret == other.ret
    def __hash__(self):
        return hash(('Func', self.args, self.ret))

class TypeScheme:
    __slots__ = ('type', 'vars')
    def __init__(self, type, vars):
        self.type = type
        self.vars = vars

def apply_subst(subst, t):
    if isinstance(t, TypeVar):
        return subst.get(t, t)
    elif isinstance(t, BaseType):
        return t
    elif isinstance(t, ListType):
        return ListType(apply_subst(subst, t.inner))
    elif isinstance(t, RefType):
        return RefType(apply_subst(subst, t.inner))
    elif isinstance(t, FuncType):
        return FuncType(tuple(apply_subst(subst, a) for a in t.args), apply_subst(subst, t.ret))
    return t

def occurs(var, t):
    if isinstance(t, TypeVar):
        return t == var
    elif isinstance(t, BaseType):
        return False
    elif isinstance(t, ListType) or isinstance(t, RefType):
        return occurs(var, t.inner)
    elif isinstance(t, FuncType):
        return any(occurs(var, a) for a in t.args) or occurs(var, t.ret)
    return False

def unify(t1, t2, subst):
    t1 = apply_subst(subst, t1)
    t2 = apply_subst(subst, t2)
    if t1 == t2:
        return subst
    if isinstance(t1, TypeVar):
        if occurs(t1, t2):
            raise ValueError("Infinite type")
        return {**subst, t1: t2}
    if isinstance(t2, TypeVar):
        if occurs(t2, t1):
            raise ValueError("Infinite type")
        return {**subst, t2: t1}
    if isinstance(t1, BaseType) and isinstance(t2, BaseType):
        if t1.name != t2.name:
            raise ValueError("Type mismatch")
        return subst
    if isinstance(t1, ListType) and isinstance(t2, ListType):
        return unify(t1.inner, t2.inner, subst)
    if isinstance(t1, RefType) and isinstance(t2, RefType):
        return unify(t1.inner, t2.inner, subst)
    if isinstance(t1, FuncType) and isinstance(t2, FuncType):
        if len(t1.args) != len(t2.args):
            raise ValueError("Arity mismatch")
        for a, b in zip(t1.args, t2.args):
            subst = unify(a, b, subst)
        return unify(t1.ret, t2.ret, subst)
    raise ValueError("Type mismatch")

def free_vars(t):
    if isinstance(t, TypeVar):
        return {t}
    elif isinstance(t, BaseType):
        return set()
    elif isinstance(t, ListType) or isinstance(t, RefType):
        return free_vars(t.inner)
    elif isinstance(t, FuncType):
        vs = set()
        for a in t.args:
            vs |= free_vars(a)
        return vs | free_vars(t.ret)
    return set()

def generalize(t, env):
    env_vars = set()
    for s in env.values():
        env_vars |= free_vars(s.type)
    to_quantify = free_vars(t) - env_vars
    return TypeScheme(t, frozenset(to_quantify))

def instantiate(scheme, fresh_func):
    sub = {}
    for v in scheme.vars:
        new_v = fresh_func()
        sub[v] = new_v
    return apply_subst(sub, scheme.type)

def is_value(term):
    tag = term[0]
    if tag in ('int', 'bool', 'str', 'unit', 'var', 'nil'):
        return True
    if tag == 'fn':
        return True
    if tag == 'cons':
        return is_value(term[2]) and is_value(term[3])
    return False

def validate(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed tag")

    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
    elif tag == 'str':
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
    elif tag == 'unit':
        if len(term) != 1:
            raise ValueError("Malformed unit")
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed var")
    elif tag == 'fn':
        if len(term) != 3:
            raise ValueError("Malformed fn")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed fn params")
        if len(set(params)) != len(params):
            raise ValueError("Duplicate fn params")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("Malformed fn param")
        validate(term[2])
    elif tag == 'call':
        if len(term) != 3:
            raise ValueError("Malformed call")
        validate(term[1])
        args = term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("Malformed call args")
        for a in args:
            validate(a)
    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed let")
        if not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed let name")
        validate(term[2])
        validate(term[3])
    elif tag == 'letrec':
        if len(term) != 4:
            raise ValueError("Malformed letrec")
        if not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed letrec name")
        validate(term[2])
        if term[2][0] != 'fn':
            raise ValueError("letrec e1 must be fn")
        validate(term[3])
    elif tag == 'nil':
        if len(term) != 1:
            raise ValueError("Malformed nil")
    elif tag == 'cons':
        if len(term) != 3:
            raise ValueError("Malformed cons")
        validate(term[2])
        validate(term[3])
    elif tag == 'match':
        if len(term) != 6:
            raise ValueError("Malformed match")
        validate(term[1])
        validate(term[2])
        if not isinstance(term[3], str) or not term[3]:
            raise ValueError("Malformed match hn")
        if not isinstance(term[4], str) or not term[4]:
            raise ValueError("Malformed match tn")
        if term[3] == term[4]:
            raise ValueError("hn and tn must differ")
        validate(term[5])
    elif tag == 'ref':
        if len(term) != 2:
            raise ValueError("Malformed ref")
        validate(term[1])
    elif tag == 'get':
        if len(term) != 2:
            raise ValueError("Malformed get")
        validate(term[1])
    elif tag == 'set':
        if len(term) != 3:
            raise ValueError("Malformed set")
        validate(term[1])
        validate(term[2])
    else:
        raise ValueError("Unknown tag")

def weak_infer(term):
    validate(term)

    fresh_counter = [0]
    def fresh_var():
        v = TypeVar(fresh_counter[0])
        fresh_counter[0] += 1
        return v

    subst = {}

    v0 = fresh_var()
    init_env = {
        "plus": TypeScheme(FuncType((BaseType("Int"), BaseType("Int")), BaseType("Int")), frozenset()),
        "eq": TypeScheme(FuncType((v0, v0), BaseType("Bool")), frozenset({v0})),
        "size": TypeScheme(FuncType((BaseType("Str"),), BaseType("Int")), frozenset()),
    }

    def infer(term, env):
        nonlocal subst
        tag = term[0]

        if tag == 'int':
            return BaseType("Int")
        elif tag == 'bool':
            return BaseType("Bool")
        elif tag == 'str':
            return BaseType("Str")
        elif tag == 'unit':
            return BaseType("Unit")
        elif tag == 'var':
            name = term[1]
            if name not in env:
                raise ValueError("Unbound variable")
            scheme = env[name]
            return instantiate(scheme, fresh_var)
        elif tag == 'fn':
            params = term[1]
            body = term[2]
            param_types = tuple(fresh_var() for _ in params)
            new_env = {p: TypeScheme(t, frozenset()) for p, t in zip(params, param_types)}
            new_env.update(env)
            ret_type = infer(body, new_env)
            return FuncType(param_types, ret_type)
        elif tag == 'call':
            f_term = term[1]
            args = term[2]
            f_type = infer(f_term, env)
            if not isinstance(f_type, FuncType):
                raise ValueError("Call on non-function")
            if len(f_type.args) != len(args):
                raise ValueError("Arity mismatch")
            arg_types = tuple(infer(a, env) for a in args)
            for p, a in zip(f_type.args, arg_types):
                subst = unify(p, a, subst)
            return apply_subst(subst, f_type.ret)
        elif tag == 'let':
            name = term[1]
            e1 = term[2]
            e2 = term[3]
            t1 = infer(e1, env)
            if is_value(e1):
                t1_scheme = generalize(t1, env)
            else:
                t1_scheme = TypeScheme(t1, frozenset())
            new_env = {name: t1_scheme}
            new_env.update(env)
            return infer(e2, new_env)
        elif tag == 'letrec':
            name = term[1]
            e1 = term[2]
            e2 = term[3]
            X = fresh_var()
            new_env1 = {name: TypeScheme(X, frozenset())}
            new_env1.update(env)
            t1 = infer(e1, new_env1)
            subst = unify(X, t1, subst)
            t1_gen = generalize(t1, env)
            new_env2 = {name: t1_gen}
            new_env2.update(env)
            return infer(e2, new_env2)
        elif tag == 'nil':
            return ListType(fresh_var())
        elif tag == 'cons':
            h = term[2]
            t = term[3]
            h_type = infer(h, env)
            t_type = infer(t, env)
            if not isinstance(t_type, ListType):
                raise ValueError("Cons tail must be list")
            subst = unify(h_type, t_type.inner, subst)
            return t_type
        elif tag == 'match':
            s = term[1]
            e_nil = term[2]
            hn = term[3]
            tn = term[4]
            e_cons = term[5]
            s_type = infer(s, env)
            if not isinstance(s_type, ListType):
                raise ValueError("Match scrutinee must be list")
            A = s_type.inner
            new_env = {hn: TypeScheme(A, frozenset()), tn: TypeScheme(ListType(A), frozenset())}
            new_env.update(env)
            t_nil = infer(e_nil, new_env)
            t_cons = infer(e_cons, new_env)
            subst = unify(t_nil, t_cons, subst)
            return apply_subst(subst, t_nil)
        elif tag == 'ref':
            e = term[1]
            e_type = infer(e, env)
            return RefType(e_type)
        elif tag == 'get':
            r = term[1]
            r_type = infer(r, env)
            if not isinstance(r_type, RefType):
                raise ValueError("Get on non-ref")
            return r_type.inner
        elif tag == 'set':
            r = term[1]
            e = term[2]
            r_type = infer(r, env)
            if not isinstance(r_type, RefType):
                raise ValueError("Set on non-ref")
            e_type = infer(e, env)
            subst = unify(r_type.inner, e_type, subst)
            return BaseType("Unit")
        else:
            raise ValueError("Unknown tag")

    result_type = infer(term, init_env)
    result_type = apply_subst(subst, result_type)

    var_list = sorted(free_vars(result_type), key=lambda v: v.id)
    var_map = {v: i + 1 for i, v in enumerate(var_list)}

    def print_type(t):
        if isinstance(t, TypeVar):
            return f"t{var_map[t]}"
        elif isinstance(t, BaseType):
            return t.name
        elif isinstance(t, ListType):
            return f"List[{print_type(t.inner)}]"
        elif isinstance(t, RefType):
            return f"Ref[{print_type(t.inner)}]"
        elif isinstance(t, FuncType):
            args_strs = [print_type(a) for a in t.args]
            if len(t.args) == 1:
                p_str = args_strs[0]
                if isinstance(t.args[0], FuncType):
                    p_str = f"({p_str})"
            else:
                p_str = f"({', '.join(args_strs)})"
            r_str = print_type(t.ret)
            return f"{p_str} -> {r_str}"
        return str(t)

    return print_type(result_type)

import sys

class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.kind == other.kind and self.args == other.args
    def __hash__(self):
        return hash((self.kind, self.args))

# Type variable naming generator: a, b, ..., z, aa, ab, ..., az, ba, ...
def var_name_gen():
    chars = 'abcdefghijklmnopqrstuvwxyz'
    i = 0
    while True:
        s = ''
        n = i
        while n >= 0:
            s = chars[n % 26] + s
            n = n // 26 - 1
        yield s
        i += 1

VAR_NAMES = var_name_gen()
SUBST = {}

def fresh_var():
    return next(VAR_NAMES)

def find(v):
    while isinstance(v, str) and v in SUBST:
        v = SUBST[v]
    return v

def occurs(v, t):
    t = find(t)
    if isinstance(t, str):
        return v == t
    if t.kind == 'fun':
        return occurs(v, t.args[0]) or occurs(v, t.args[1])
    if t.kind == 'list':
        return occurs(v, t.args[0])
    if t.kind == 'tuple':
        return any(occurs(v, arg) for arg in t.args)
    return False

def unify(t1, t2):
    t1 = find(t1)
    t2 = find(t2)
    if t1 == t2:
        return
    if isinstance(t1, str):
        if occurs(t1, t2):
            raise ValueError("Infinite type")
        SUBST[t1] = t2
    elif isinstance(t2, str):
        if occurs(t2, t1):
            raise ValueError("Infinite type")
        SUBST[t2] = t1
    elif t1.kind == 'fun' and t2.kind == 'fun':
        unify(t1.args[0], t2.args[0])
        unify(t1.args[1], t2.args[1])
    elif t1.kind == 'list' and t2.kind == 'list':
        unify(t1.args[0], t2.args[0])
    elif t1.kind == 'tuple' and t2.kind == 'tuple':
        if len(t1.args) != len(t2.args):
            raise ValueError("Type mismatch")
        for a, b in zip(t1.args, t2.args):
            unify(a, b)
    else:
        raise ValueError("Type mismatch")

def apply_subst(t):
    t = find(t)
    if isinstance(t, str):
        return t
    if t.kind == 'fun':
        return Type('fun', apply_subst(t.args[0]), apply_subst(t.args[1]))
    if t.kind == 'list':
        return Type('list', apply_subst(t.args[0]))
    if t.kind == 'tuple':
        return Type('tuple', *(apply_subst(arg) for arg in t.args))
    return t

def free_vars(t):
    t = find(t)
    if isinstance(t, str):
        return {t}
    if t.kind == 'fun':
        return free_vars(t.args[0]) | free_vars(t.args[1])
    if t.kind == 'list':
        return free_vars(t.args[0])
    if t.kind == 'tuple':
        res = set()
        for arg in t.args:
            res |= free_vars(arg)
        return res
    return set()

def env_free_vars(env):
    res = set()
    for frame in env:
        for name, val in frame.items():
            if isinstance(val, tuple) and len(val) == 2:
                res |= val[0]
            else:
                res |= free_vars(val)
    return res

def instantiate(scheme):
    qvars, ty = scheme
    new_vars = {v: fresh_var() for v in qvars}
    old_subst = SUBST.copy()
    for old, new in new_vars.items():
        SUBST[old] = new
    res = apply_subst(ty)
    SUBST.clear()
    SUBST.update(old_subst)
    return res

def generalize(env, ty):
    fv = free_vars(ty)
    env_fv = env_free_vars(env)
    quant_vars = fv - env_fv
    return (quant_vars, ty)

def pretty_print(t):
    t = find(t)
    if isinstance(t, str):
        return t
    if t.kind == 'fun':
        return f'({pretty_print(t.args[0])} {pretty_print(t.args[1])})'
    if t.kind == 'list':
        return f'(List {pretty_print(t.args[0])})'
    if t.kind == 'tuple':
        if len(t.args) == 0:
            return '(Tuple)'
        return f'(Tuple {" ".join(pretty_print(arg) for arg in t.args)})'
    return str(t)

def rename_vars(t):
    t = find(t)
    if isinstance(t, str):
        return t
    if t.kind == 'fun':
        return Type('fun', rename_vars(t.args[0]), rename_vars(t.args[1]))
    if t.kind == 'list':
        return Type('list', rename_vars(t.args[0]))
    if t.kind == 'tuple':
        return Type('tuple', *(rename_vars(arg) for arg in t.args))
    return t

def collect_vars_in_string(t):
    # Collect vars in order of first appearance in the string representation
    s = pretty_print(t)
    chars = 'abcdefghijklmnopqrstuvwxyz'
    var_map = {}
    counter = [0]
    def next_name():
        if counter[0] < 26:
            res = chars[counter[0]]
            counter[0] += 1
            return res
        n = counter[0]
        s = ''
        while n >= 0:
            s = chars[n % 26] + s
            n = n // 26 - 1
        counter[0] += 1
        return s

    def rename(s_t):
        s_t = find(s_t)
        if isinstance(s_t, str):
            if s_t not in var_map:
                var_map[s_t] = next_name()
            return var_map[s_t]
        if s_t.kind == 'fun':
            return Type('fun', rename(s_t.args[0]), rename(s_t.args[1]))
        if s_t.kind == 'list':
            return Type('list', rename(s_t.args[0]))
        if s_t.kind == 'tuple':
            return Type('tuple', *(rename(arg) for arg in s_t.args))
        return s_t

    return rename(t)

def infer(term, env):
    if isinstance(term, bool):
        return 'Bool'
    if isinstance(term, int):
        return 'Int'
    if isinstance(term, str):
        for frame in reversed(env):
            if term in frame:
                val = frame[term]
                if isinstance(val, tuple):
                    return instantiate(val)
                else:
                    return val
        raise ValueError("Unbound variable")
    if isinstance(term, tuple):
        if len(term) == 0:
            raise ValueError("Malformed term")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed term")
        if tag == 'lam':
            if len(term) != 3 or not isinstance(term[1], str) or len(term[1]) == 0:
                raise ValueError("Malformed lambda")
            x, body = term[1], term[2]
            tx = fresh_var()
            new_env = env + [{x: tx}]
            tb = infer(body, new_env)
            return Type('fun', tx, tb)
        elif tag == 'app':
            if len(term) != 3:
                raise ValueError("Malformed app")
            f, a = term[1], term[2]
            tf = infer(f, env)
            ta = infer(a, env)
            tr = fresh_var()
            unify(tf, Type('fun', ta, tr))
            return tr
        elif tag == 'if':
            if len(term) != 4:
                raise ValueError("Malformed if")
            c, t, e = term[1], term[2], term[3]
            tc = infer(c, env)
            unify(tc, 'Bool')
            tt = infer(t, env)
            te = infer(e, env)
            unify(tt, te)
            return tt
        elif tag == 'let':
            if len(term) != 4:
                raise ValueError("Malformed let")
            x, e1, e2 = term[1], term[2], term[3]
            if not isinstance(x, str) or len(x) == 0:
                raise ValueError("Malformed let")
            te1 = infer(e1, env)
            scheme = generalize(env, te1)
            new_env = env + [{x: scheme}]
            return infer(e2, new_env)
        elif tag == 'letrec':
            if len(term) != 3:
                raise ValueError("Malformed letrec")
            group, body = term[1], term[2]
            if not isinstance(group, tuple) or len(group) == 0:
                raise ValueError("Malformed letrec group")
            names = []
            exprs = []
            for item in group:
                if not isinstance(item, tuple) or len(item) != 2:
                    raise ValueError("Malformed letrec pair")
                n, e = item
                if not isinstance(n, str) or len(n) == 0:
                    raise ValueError("Malformed letrec name")
                if n in names:
                    raise ValueError("Duplicate letrec name")
                names.append(n)
                exprs.append(e)
            fresh_types = [fresh_var() for _ in names]
            rec_env = env + {n: ft for n, ft in zip(names, fresh_types)}
            group_types = [infer(e, rec_env) for e in exprs]
            schemes = [generalize(env, gt) for gt in group_types]
            final_env = env + {n: s for n, s in zip(names, schemes)}
            return infer(body, final_env)
        elif tag == 'tuple':
            if len(term) < 2:
                raise ValueError("Malformed tuple")
            if len(term) == 2:
                raise ValueError("Tuple with n=1 is invalid")
            args = term[1:]
            types = [infer(a, env) for a in args]
            return Type('tuple', *types)
        elif tag == 'proj':
            if len(term) != 4:
                raise ValueError("Malformed proj")
            i, n, e = term[1], term[2], term[3]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Malformed proj index")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Malformed proj length")
            if n < 2 or i < 0 or i >= n:
                raise ValueError("Malformed proj indices")
            te = infer(e, env)
            te = find(te)
            if te.kind != 'tuple':
                raise ValueError("Type mismatch")
            if len(te.args) != n:
                raise ValueError("Type mismatch")
            return te.args[i]
        else:
            raise ValueError("Unknown tag")
    raise ValueError("Malformed term")

def group_type(term):
    global SUBST
    SUBST = {}
    env = [
        {
            'add': (set(), Type('fun', 'Int', Type('fun', 'Int', 'Int'))),
            'eq': ({'a'}, Type('fun', 'a', Type('fun', 'a', 'Bool'))),
            'nil': ({'a'}, Type('list', 'a')),
            'cons': ({'a'}, Type('fun', 'a', Type('fun', Type('list', 'a'), Type('list', 'a')))),
            'head': ({'a'}, Type('fun', Type('list', 'a'), 'a')),
            'tail': ({'a'}, Type('fun', Type('list', 'a'), Type('list', 'a'))),
            'isnil': ({'a'}, Type('fun', Type('list', 'a'), 'Bool'))
        }
    ]
    try:
        ty = infer(term, env)
        ty = rename_vars(ty)
        return pretty_print(ty)
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

