        t = unifier.find(t)
        if isinstance(t, str):
            return new_subst.get(t, t)
        if t.kind == 'fun':
            return Type('fun', apply_subst(t.args[0]), apply_subst(t.args[1]))
        if t.kind == 'list':
            return Type('list', apply_subst(t.args[0]))
        if t.kind == 'tuple':
            return Type('tuple', *(apply_subst(x) for x in t.args))
        return t
    return apply_subst(ty)

def generalize(env, ty):
    fv = free_vars(ty)
    env_fv = env_free_vars(env)
    quant_vars = fv - env_fv
    return (quant_vars, ty)

