        return f'(-> {to_str(t.args[0])} {to_str(t.args[1])})'
    if t.kind == 'list':
        return f'(List {to_str(t.args[0])})'
    if t.kind == 'tuple':
        if not t.args:
            return '(Tuple)'
        return f'(Tuple {" ".join(to_str(x) for x in t.args)})'
    return str(t)

