    chars = 'abcdefghijklmnopqrstuvwxyz'
    if idx < 26:
        return chars[idx]
    res = ''
    idx += 1
    while idx > 0:
        idx -= 1
        res = chars[idx % 26] + res
        idx //= 26
    return res

