        name = t.args[0]
        new_name = mapping.get(name, name)
        return Type('var', new_name)
    if t.kind == 'fun':
        return Type('fun', rename_vars(t.args[0], mapping), rename_vars(t.args[1], mapping))
    if t.kind == 'list':
        return Type('list', rename_vars(t.args[0], mapping))
    if t.kind == 'tuple':
        return Type('tuple', *(rename_vars(x, mapping) for x in t.args))
    return t

def infer(term, env, unifier):
    if isinstance(term, bool):
        return 'Bool'
    if isinstance(term, int):
        return 'Int'
    if isinstance(term, str):
        for frame in reversed(env):
            if term in frame:
                val = frame[term]
                if isinstance(val, tuple):
                    return instantiate(val, unifier)
                else:
                    return unifier.apply(val)
        raise ValueError("Unbound variable")
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    if len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed term")

    if tag == 'lam':
        if len(term) != 3 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Malformed lambda")
        x, body = term[1], term[2]
        tx = unifier.fresh()
        new_env = env + [{x: tx}]
        tb = infer(body, new_env, unifier)
        return Type('fun', tx, tb)

    elif tag == 'app':
        if len(term) != 3:
            raise ValueError("Malformed app")
