        tf = infer(f, env, unifier)
        ta = infer(a, env, unifier)
        tr = unifier.fresh()
        unifier.unify(tf, Type('fun', ta, tr))
        return tr

    elif tag == 'if':
        if len(term) != 4:
            raise ValueError("Malformed if")
        c, t, e = term[1], term[2], term[3]
        tc = infer(c, env, unifier)
        unifier.unify(tc, 'Bool')
        tt = infer(t, env, unifier)
        te = infer(e, env, unifier)
        unifier.unify(tt, te)
        return tt

    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed let")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or len(x) == 0:
            raise ValueError("Malformed let")
        te1 = infer(e1, env, unifier)
        scheme = generalize(env, te1)
        new_env = env + [{x: scheme}]
        return infer(e2, new_env, unifier)

    elif tag == 'letrec':
        if len(term) != 3:
            raise ValueError("Malformed letrec")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("Malformed letrec group")
        names = []
        exprs = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Malformed letrec pair")
            n, e = item
            if not isinstance(n, str) or len(n) == 0:
                raise ValueError("Malformed letrec name")
            if n in names:
                raise ValueError("Duplicate letrec name")
            names.append(n)
            exprs.append(e)

        fresh_types = {n: unifier.fresh() for n in names}
        rec_env = env + [fresh_types]

        for n, e in zip(names, exprs):
            te = infer(e, rec_env, unifier)
            unifier.unify(fresh_types[n], te)

        schemes = {}
        for n in names:
            scheme = generalize(env, fresh_types[n])
