        ty = infer(term, env, unifier)
        ty = unifier.apply(ty)
        ordered = get_ordered_vars(ty)
        mapping = {v: get_name(i) for i, v in enumerate(ordered)}
        ty = rename_vars(ty, mapping)
        return to_str(ty)
    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

import re

class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.kind == other.kind and self.args == other.args
    def __hash__(self):
        return hash((self.kind, self.args))

class Unifier:
    def __init__(self):
        self.subst = {}
        self.counter = 0

    def fresh(self):
        v = f'v{self.counter}'
        self.counter += 1
        return v

    def find(self, v):
        while isinstance(v, str) and v in self.subst:
            v = self.subst[v]
        return v

    def occurs(self, v, t):
        t = self.find(t)
        if isinstance(t, str):
            return v == t
        if t.kind == 'fun':
            return self.occurs(v, t.args[0]) or self.occurs(v, t.args[1])
        if t.kind == 'list':
            return self.occurs(v, t.args[0])
        if t.kind == 'tuple':
            return any(self.occurs(v, arg) for arg in t.args)
        return False

    def unify(self, t1, t2):
        t1 = self.find(t1)
        t2 = self.find(t2)
        if t1 == t2:
            return
        if isinstance(t1, str):
            if self.occurs(t1, t2):
                raise ValueError("Infinite type")
            self.subst[t1] = t2
        elif isinstance(t2, str):
            if self.occurs(t2, t1):
                raise ValueError("Infinite type")
            self.subst[t2] = t1
        elif t1.kind == 'fun' and t2.kind == 'fun':
            self.unify(t1.args[0], t2.args[0])
            self.unify(t1.args[1], t2.args[1])
        elif t1.kind == 'list' and t2.kind == 'list':
            self.unify(t1.args[0], t2.args[0])
        elif t1.kind == 'tuple' and t2.kind == 'tuple':
            if len(t1.args) != len(t2.args):
                raise ValueError("Type mismatch")
            for a, b in zip(t1.args, t2.args):
                self.unify(a, b)
        else:
            raise ValueError("Type mismatch")

    def apply(self, t):
        t = self.find(t)
        if isinstance(t, str):
            return t
        if t.kind == 'fun':
            return Type('fun', self.apply(t.args[0]), self.apply(t.args[1]))
        if t.kind == 'list':
            return Type('list', self.apply(t.args[0]))
        if t.kind == 'tuple':
            return Type('tuple', *(self.apply(x) for x in t.args))
        return t

