            fresh_types = [TVar(fresh_id()) for _ in names]
            env_rec = env + [(nm, Scheme(set(), ft)) for nm, ft in zip(names, fresh_types)]
            inferred_types = [infer(ex, env_rec) for ex in exprs]

            subst = {}
            for ft, it in zip(fresh_types, inferred_types):
                subst = unify(ft, it, subst)

            final_types = [apply_type(ft, subst) for ft in fresh_types]
            env_outside = env
            schemes_rec = []
            for nm, ft in zip(names, final_types):
                schemes_rec.append((nm, generalize(env_outside, ft)))
            env_new = env + schemes_rec
            return infer(body, env_new)

        elif tag == "tuple":
            elements = t[1:]
            n = len(elements)
            if n == 1: raise ValueError("Tuple size 1 not allowed")
            if n == 0: return TTuple([])
            types = [infer(e, env) for e in elements]
            return TTuple(types)

        elif tag == "proj":
            if len(t) != 4: raise ValueError("proj wrong length")
            i, n, e = t[1], t[2], t[3]
            if isinstance(i, bool) or isinstance(n, bool): raise ValueError("i/n must be ints not bools")
            if not isinstance(i, int) or not isinstance(n, int): raise ValueError("i/n must be ints")
            if n < 2: raise ValueError("proj n must be >= 2")
            if not (0 <= i < n): raise ValueError("proj i out of range")
            te = infer(e, env)
            fresh_elts = [TVar(fresh_id()) for _ in range(n)]
            target = TTuple(fresh_elts)
            subst = unify(te, target)
            return apply_type(fresh_elts[i], subst)

        else:
            raise ValueError("Unknown tag")

    result_type = infer(term, env)
    return type_to_str(result_type)

import itertools

class Type:
    pass

class TVar(Type):
    __slots__ = ('id',)
    def __init__(self, id): self.id = id
    def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
    def __hash__(self): return hash(self.id)

class TInt(Type): pass
class TBool(Type): pass

class TFun(Type):
    __slots__ = ('arg', 'ret')
    def __init__(self, arg, ret): self.arg = arg; self.ret = ret
    def __eq__(self, other): return isinstance(other, TFun) and self.arg == other.arg and self.ret == other.ret
    def __hash__(self): return hash((self.arg, self.ret))

class TList(Type):
    __slots__ = ('elem',)
    def __init__(self, elem): self.elem = elem
    def __eq__(self, other): return isinstance(other, TList) and self.elem == other.elem
    def __hash__(self): return hash(self.elem)

class TTuple(Type):
    __slots__ = ('elts',)
    def __init__(self, elts): self.elts = list(elts)
    def __eq__(self, other): return isinstance(other, TTuple) and self.elts == other.elts
    def __hash__(self): return hash(tuple(self.elts))

class Scheme:
    __slots__ = ('free_vars', 'type')
    def __init__(self, free_vars, type): self.free_vars = set(free_vars); self.type = type

_id_counter = itertools.count()
def fresh_id(): return next(_id_counter)

def free_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, TFun): return free_vars(t.arg) | free_vars(t.ret)
    if isinstance(t, TList): return free_vars(t.elem)
    if isinstance(t, TTuple):
        fs = set()
        for e in t.elts: fs |= free_vars(e)
        return fs
    return set()

def apply_type(t, subst):
    if isinstance(t, TVar):
        return subst.get(t.id, t)
    if isinstance(t, TFun):
        return TFun(apply_type(t.arg, subst), apply_type(t.ret, subst))
    if isinstance(t, TList):
        return TList(apply_type(t.elem, subst))
    if isinstance(t, TTuple):
        return TTuple([apply_type(e, subst) for e in t.elts])
    return t

def occurs_check(id, t):
    if isinstance(t, TVar): return t.id == id
    if isinstance(t, TFun): return occurs_check(id, t.arg) or occurs_check(id, t.ret)
    if isinstance(t, TList): return occurs_check(id, t.elem)
    if isinstance(t, TTuple): return any(occurs_check(id, e) for e in t.elts)
    return False

def unify(t1, t2, subst=None):
    if subst is None: subst = {}
    t1 = apply_type(t1, subst)
    t2 = apply_type(t2, subst)

    if isinstance(t1, TVar):
        if t1.id in subst: return unify(subst[t1.id], t2, subst)
        if occurs_check(t1.id, t2): raise ValueError("Infinite type")
        return {**subst, t1.id: t2}
    if isinstance(t2, TVar):
        if t2.id in subst: return unify(t1, subst[t2.id], subst)
        if occurs_check(t2.id, t1): raise ValueError("Infinite type")
        return {**subst, t2.id: t1}
    if type(t1) != type(t2): raise ValueError("Type mismatch")
    if isinstance(t1, TFun):
        s1 = unify(t1.arg, t2.arg, subst)
        return unify(t1.ret, t2.ret, s1)
    if isinstance(t1, TList):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TTuple):
        if len(t1.elts) != len(t2.elts): raise ValueError("Tuple size mismatch")
        s = subst
        for a, b in zip(t1.elts, t2.elts):
            s = unify(a, b, s)
        return s
    if isinstance(t1, (TInt, TBool)):
        return subst
    raise ValueError("Unknown type")

def generalize(env, t):
    free_in_env = set()
    for _, scheme in env:
        free_in_env.update(scheme.free_vars)
    gen_vars = free_vars(t) - free_in_env
    return Scheme(gen_vars, t)

def instantiate(scheme):
    fresh_map = {v: TVar(fresh_id()) for v in scheme.free_vars}
    return apply_type(scheme.type, fresh_map)

def get_name(n):
    if n < 26:
        return chr(ord('a') + n)
    return get_name(n // 26 - 1) + chr(ord('a') + n % 26)

def type_to_str(t):
    seen = set()
    order = []
    def collect(t):
        if isinstance(t, TVar):
            if t.id not in seen:
                seen.add(t.id)
                order.append(t.id)
        elif isinstance(t, TFun):
            collect(t.arg); collect(t.ret)
        elif isinstance(t, TList):
            collect(t.elem)
        elif isinstance(t, TTuple):
            for e in t.elts: collect(e)
    collect(t)
    var_map = {vid: get_name(i) for i, vid in enumerate(order)}

    def fmt(t):
        if isinstance(t, TVar): return var_map[t.id]
        if isinstance(t, TInt): return "Int"
        if isinstance(t, TBool): return "Bool"
        if isinstance(t, TFun): return f"({fmt(t.arg)} -> {fmt(t.ret)})"
        if isinstance(t, TList): return f"(List {fmt(t.elem)})"
        if isinstance(t, TTuple):
            if not t.elts: return "(Tuple)"
            return f"(Tuple {' '.join(fmt(e) for e in t.elts)})"
        return "?"
    return fmt(t)

def group_type(term):
    a = fresh_id()
    env = [
        ("add", Scheme(set(), TFun(TInt, TFun(TInt, TInt)))),
        ("eq", Scheme({a}, TFun(TVar(a), TFun(TVar(a), TBool)))),
        ("nil", Scheme({a}, TList(TVar(a)))),
        ("cons", Scheme({a}, TFun(TVar(a), TFun(TList(TVar(a)), TList(TVar(a)))))),
        ("head", Scheme({a}, TFun(TList(TVar(a)), TVar(a)))),
        ("tail", Scheme({a}, TFun(TList(TVar(a)), TList(TVar(a))))),
        ("isnil", Scheme({a}, TFun(TList(TVar(a)), TBool))))
    ]

    def infer(t, env):
        if isinstance(t, bool): return TBool
        if isinstance(t, int): return TInt
        if isinstance(t, str):
            if not t: raise ValueError("Empty string")
            for name, scheme in env:
                if name == t: return instantiate(scheme)
            raise ValueError("Unbound variable")
        if not isinstance(t, tuple) or len(t) < 2:
            raise ValueError("Malformed term")
        tag = t[0]
        if not isinstance(tag, str): raise ValueError("Non-str tag")

        if tag == "lam":
            if len(t) != 3: raise ValueError("lam wrong length")
            x, body = t[1], t[2]
            if not isinstance(x, str) or not x: raise ValueError("Bad lambda param")
            param_type = TVar(fresh_id())
            env_new = env + [(x, Scheme(set(), param_type))]
            body_type = infer(body, env_new)
            return TFun(param_type, body_type)

        elif tag == "app":
            if len(t) != 3: raise ValueError("app wrong length")
            f, a = t[1], t[2]
            tf = infer(f, env)
            ta = infer(a, env)
            res_type = TVar(fresh_id())
            subst = unify(tf, TFun(ta, res_type))
            return apply_type(res_type, subst)

        elif tag == "if":
            if len(t) != 4: raise ValueError("if wrong length")
            c, tr, e = t[1], t[2], t[3]
            tc = infer(c, env)
            subst = unify(tc, TBool)
            tt = infer(tr, env)
            te = infer(e, env)
            subst = unify(tt, te, subst)
            return apply_type(tt, subst)

        elif tag == "let":
            if len(t) != 4: raise ValueError("let wrong length")
            x, e1, e2 = t[1], t[2], t[3]
            if not isinstance(x, str) or not x: raise ValueError("Bad let name")
            t1 = infer(e1, env)
            scheme = generalize(env, t1)
            env_new = env + [(x, scheme)]
            return infer(e2, env_new)

        elif tag == "letrec":
            if len(t) != 3: raise ValueError("letrec wrong length")
            group, body = t[1], t[2]
            if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Empty letrec group")
            names, exprs = [], []
            seen = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2: raise ValueError("Bad letrec pair")
                nm, ex = pair
                if not isinstance(nm, str) or not nm: raise ValueError("Bad letrec name")
                if nm in seen: raise ValueError("Duplicate letrec name")
                seen.add(nm)
                names.append(nm)
                exprs.append(ex)

            fresh_types = [TVar(fresh_id()) for _ in names]
            env_rec = env + [(nm, Scheme(set(), ft)) for nm, ft in zip(names, fresh_types)]
            inferred_types = [infer(ex, env_rec) for ex in exprs]

            subst = {}
            for ft, it in zip(fresh_types, inferred_types):
                subst = unify(ft, it, subst)

            final_types = [apply_type(ft, subst) for ft in fresh_types]
            env_outside = env
            schemes_rec = []
            for nm, ft in zip(names, final_types):
                schemes_rec.append((nm, generalize(env_outside, ft)))
            env_new = env + schemes_rec
            return infer(body, env_new)

        elif tag == "tuple":
            elements = t[1:]
            n = len(elements)
            if n == 1: raise ValueError("Tuple size 1 not allowed")
            if n == 0: return TTuple([])
            types = [infer(e, env) for e in elements]
            return TTuple(types)

        elif tag == "proj":
            if len(t) != 4: raise ValueError("proj wrong length")
            i, n, e = t[1], t[2], t[3]
            if isinstance(i, bool) or isinstance(n, bool): raise ValueError("i/n must be ints not bools")
            if not isinstance(i, int) or not isinstance(n, int): raise ValueError("i/n must be ints")
            if n < 2: raise ValueError("proj n must be >= 2")
            if not (0 <= i < n): raise ValueError("proj i out of range")
            te = infer(e, env)
            fresh_elts = [TVar(fresh_id()) for _ in range(n)]
            target = TTuple(fresh_elts)
            subst = unify(te, target)
            return apply_type(fresh_elts[i], subst)

        else:
            raise ValueError("Unknown tag")

    result_type = infer(term, env)
    return type_to_str(result_type)

import sys

# Increase recursion depth for large terms
sys.setrecursionlimit(10000)

class TVar:
    def __init__(self, idx):
        self.idx = idx
    def __repr__(self):
        return f"TVar({self.idx})"
    def __hash__(self):
        return hash(self.idx)
    def __eq__(self, other):
        return isinstance(other, TVar) and self.idx == other.idx

class TCon:
    def __init__(self, name, args):
        self.name = name
        self.args = args
    def __repr__(self):
        return f"TCon({self.name}, {self.args})"
    def __hash__(self):
        return hash((self.name, tuple(self.args)))
    def __eq__(self, other):
        return isinstance(other, TCon) and self.name == other.name and self.args == other.args

def tvar_name(n):
    res = []
    n += 1
    while n > 0:
        n, rem = divmod(n - 1, 26)
        res.append(chr(ord('a') + rem))
    return "".join(reversed(res))

def free_vars(t):
    if isinstance(t, TVar):
        return {t}
    if isinstance(t, TCon):
        fvs = set()
        for a in t.args:
            fvs.update(free_vars(a))
        return fvs
    return set()

def contains(tvar, t):
    if isinstance(t, TVar):
        return t == tvar
    if isinstance(t, TCon):
        return any(contains(tvar, a) for a in t.args)
    return False

def apply_subst(subst, t):
    if isinstance(t, TVar):
        while t in subst:
            t = subst[t]
        return t
    if isinstance(t, TCon):
        return TCon(t.name, [apply_subst(subst, a) for a in t.args])
    return t

def unify(t1, t2, subst):
    t1 = apply_subst(subst, t1)
    t2 = apply_subst(subst, t2)
    if t1 == t2:
        return
    if isinstance(t1, TVar):
        if contains(t1, t2):
            raise ValueError("Infinite type")
        subst[t1] = t2
        return
    if isinstance(t2, TVar):
        if contains(t2, t1):
            raise ValueError("Infinite type")
        subst[t2] = t1
        return
    if isinstance(t1, TCon) and isinstance(t2, TCon) and t1.name == t2.name and len(t1.args) == len(t2.args):
        for a1, a2 in zip(t1.args, t2.args):
            unify(a1, a2, subst)
        return
    raise ValueError("Type mismatch")

def free_vars_env(env):
    fvs = set()
    for _, (bound, t) in env.items():
        for v in free_vars(t):
            if v not in bound:
                fvs.add(v)
    return fvs

def generalize(t, env_fvs):
    fvs = free_vars(t)
    bound = tuple(v for v in fvs if v not in env_fvs)
    return bound, t

def instantiate(scheme, fresh_fn):
    bound, t = scheme
    subst = {}
    for v in bound:
        fresh = fresh_fn()
        subst[v] = fresh
    return apply_subst(subst, t)

def is_valid_term(term):
    if isinstance(term, int) and not isinstance(term, bool):
        return True
    if isinstance(term, bool):
        return True
    if isinstance(term, str):
        if not term:
            raise ValueError("Empty string")
        return True
    if not isinstance(term, tuple):
        raise ValueError("Not a tuple")
    if len(term) == 0:
        raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Non-str tag")
    if tag == "lam":
        if len(term) != 3:
            raise ValueError("lam wrong length")
        if not isinstance(term[1], str) or not term[1]:
            raise ValueError("lam bad name")
        return is_valid_term(term[2])
    if tag == "app":
        if len(term) != 3:
            raise ValueError("app wrong length")
        return is_valid_term(term[1]) and is_valid_term(term[2])
    if tag == "if":
        if len(term) != 4:
            raise ValueError("if wrong length")
        return is_valid_term(term[1]) and is_valid_term(term[2]) and is_valid_term(term[3])
    if tag == "let":
        if len(term) != 4:
            raise ValueError("let wrong length")
        if not isinstance(term[1], str) or not term[1]:
            raise ValueError("let bad name")
        return is_valid_term(term[2]) and is_valid_term(term[3])
    if tag == "letrec":
        if len(term) != 3:
            raise ValueError("letrec wrong length")
        group = term[1]
        if not isinstance(group, tuple) or len(group) == 0:
            raise ValueError("letrec bad group")
        names = set()
        for pair in group:
            if not isinstance(pair, tuple) or len(pair) != 2:
                raise ValueError("letrec bad pair")
            name, expr = pair
            if not isinstance(name, str) or not name:
                raise ValueError("letrec bad name")
            if name in names:
                raise ValueError("letrec duplicate name")
            names.add(name)
            if not is_valid_term(expr):
                raise ValueError("letrec bad expr")
        return is_valid_term(term[2])
    if tag == "tuple":
        if len(term) == 1:
            return True
        if len(term) == 2:
            raise ValueError("tuple n=1")
        for e in term[1:]:
            if not is_valid_term(e):
                raise ValueError("tuple bad elem")
        return True
    if tag == "proj":
        if len(term) != 4:
            raise ValueError("proj wrong length")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool):
            raise ValueError("proj bad i")
        if not isinstance(n, int) or isinstance(n, bool):
            raise ValueError("proj bad n")
        if n < 2:
            raise ValueError("proj n<2")
        if i < 0 or i >= n:
            raise ValueError("proj bad index")
        return is_valid_term(e)
    raise ValueError(f"Unknown tag: {tag}")

def make_env():
    env = {}
    env['add'] = ((), TCon("->", [TCon("Int", []), TCon("->", [TCon("Int", []), TCon("Int", [])])]))
    a = TVar(0); env['eq'] = ((a,), TCon("->", [TVar(a), TCon("->", [TVar(a), TCon("Bool", [])])]))
    b = TVar(1); env['nil'] = ((b,), TCon("List", [TVar(b)]))
    c = TVar(2); env['cons'] = ((c,), TCon("->", [TVar(c), TCon("->", [TCon("List", [TVar(c)]), TCon("List", [TVar(c)])])]))
    d = TVar(3); env['head'] = ((d,), TCon("->", [TCon("List", [TVar(d)]), TVar(d)]))
    e = TVar(4); env['tail'] = ((e,), TCon("->", [TCon("List", [TVar(e)]), TCon("List", [TVar(e)])]))
    f = TVar(5); env['isnil'] = ((f,), TCon("->", [TCon("List", [TVar(f)]), TCon("Bool", [])]))
    return env

def print_type(t, name_map):
    if isinstance(t, TVar):
        return name_map[t]
    if isinstance(t, TCon):
        if t.name == "->":
            return f"({print_type(t.args[0], name_map)} {print_type(t.args[1], name_map)})"
        elif t.name == "Tuple":
            if not t.args:
                return "(Tuple)"
            return f"(Tuple {' '.join(print_type(a, name_map) for a in t.args)})"
        elif t.name == "List":
            return f"(List {print_type(t.args[0], name_map)})"
        else:
            return t.name
    return str(t)

def group_type(term):
    is_valid_term(term)

    tv_counter = [0]
    def fresh():
        v = TVar(tv_counter[0])
        tv_counter[0] += 1
        return v

    env = make_env()
    subst = {}

    def infer(term, env):
        if isinstance(term, int):
            return TCon("Int", [])
        if isinstance(term, bool):
            return TCon("Bool", [])
        if isinstance(term, str):
            if term not in env:
                raise ValueError(f"Unbound variable: {term}")
            scheme = env[term]
            return instantiate(scheme, fresh)

        tag = term[0]
        if tag == "lam":
            x, body = term[1], term[2]
            tx = fresh()
            new_env = {**env, x: ((), tx)}
            tb = infer(body, new_env)
            return TCon("->", [tx, tb])
        elif tag == "app":
            f, a = term[1], term[2]
            tf = infer(f, env)
            ta = infer(a, env)
            res = fresh()
            unify(tf, TCon("->", [ta, res]), subst)
            return res
        elif tag == "if":
            c, t, e = term[1], term[2], term[3]
            tc = infer(c, env)
            unify(tc, TCon("Bool", []), subst)
            tt = infer(t, env)
            te = infer(e, env)
            unify(tt, te, subst)
            return tt
        elif tag == "let":
            x, e1, e2 = term[1], term[2], term[3]
            t1 = infer(e1, env)
            env_fvs = free_vars_env(env)
            bound, gen_t = generalize(t1, env_fvs)
            new_env = {**env, x: (bound, gen_t)}
            return infer(e2, new_env)
        elif tag == "letrec":
            group, body = term[1], term[2]
            names = [p[0] for p in group]
            type_vars = {name: fresh() for name in names}
            rec_env = {**env}
            for name, tv in type_vars.items():
                rec_env[name] = ((), tv)
            for name, expr in group:
                t_expr = infer(expr, rec_env)
                unify(type_vars[name], t_expr, subst)
            env_fvs = free_vars_env(env)
            new_env = {**env}
            for name, tv in type_vars.items():
                bound, gen_t = generalize(tv, env_fvs)
                new_env[name] = (bound, gen_t)
            return infer(body, new_env)
        elif tag == "tuple":
            elems = term[1:]
            if len(elems) == 0:
                return TCon("Tuple", [])
            types = [infer(e, env) for e in elems]
            return TCon("Tuple", types)
        elif tag == "proj":
            i, n, e = term[1], term[2], term[3]
            te = infer(e, env)
            te = apply_subst(subst, te)
            if not (isinstance(te, TCon) and te.name == "Tuple" and len(te.args) == n):
                raise ValueError("proj type mismatch")
            return te.args[i]
        else:
            raise ValueError(f"Unknown tag: {tag}")

    final_type = infer(term, env)
    final_type = apply_subst(subst, final_type)

    # Collect type variables in order of first appearance (left-to-right)
    seen = set()
    order = []
    def collect_fvs(t):
        if isinstance(t, TVar):
            if t not in seen:
                seen.add(t)
                order.append(t)
        elif isinstance(t, TCon):
            for a in t.args:
                collect_fvs(a)
    collect_fvs(final_type)

    name_map = {v: tvar_name(i) for i, v in enumerate(order)}
    return print_type(final_type, name_map)

