        if tag == "lam":
            x, body = term[1], term[2]
            tx = fresh()
            new_env = {**env, x: ((), tx)}
            tb = infer(body, new_env)
            return TCon("->", [tx, tb])
        elif tag == "app":
            f, a = term[1], term[2]
            tf = infer(f, env)
            ta = infer(a, env)
            res = fresh()
            unify(tf, TCon("->", [ta, res]), subst)
            return res
