class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args
    def __str__(self):
        if self.kind == "Var": return self.args[0]
        if self.kind == "Int": return "Int"
        if self.kind == "Bool": return "Bool"
        if self.kind == "Func": return f"({self.args[0]} -> {self.args[1]})"
        if self.kind == "List": return f"(List {self.args[0]})"
        if self.kind == "Tuple":
            if not self.args: return "(Tuple)"
            return f"(Tuple {' '.join(str(a) for a in self.args)})"
        return "?"

_var_counter = 0
def fresh():
    global _var_counter
    _var_counter += 1
    i = _var_counter
    s = ""
    while i > 0:
        i, r = divmod(i - 1, 26)
        s = chr(ord('a') + r) + s
    return Type("Var", s)

def free_vars(t):
    if t.kind == "Var": return {t.args[0]}
    if t.kind == "Func": return free_vars(t.args[0]) | free_vars(t.args[1])
    if t.kind == "List": return free_vars(t.args[0])
    if t.kind == "Tuple":
        fvs = set()
        for a in t.args: fvs |= free_vars(a)
        return fvs
    return set()

def apply_sub(t, sub):
    if t.kind == "Var" and t.args[0] in sub:
        return apply_sub(sub[t.args[0]], sub)
    return t

def occurs(var, t, sub):
    t = apply_sub(t, sub)
    if t.kind == "Var" and t.args[0] == var: return True
    if t.kind == "Func": return occurs(var, t.args[0], sub) or occurs(var, t.args[1], sub)
    if t.kind == "List": return occurs(var, t.args[0], sub)
    if t.kind == "Tuple": return any(occurs(var, a, sub) for a in t.args)
    return False

def unify(t1, t2, sub):
    t1 = apply_sub(t1, sub)
    t2 = apply_sub(t2, sub)
    if t1 is t2: return sub
    if t1.kind == "Var":
        if occurs(t1.args[0], t2, sub): raise ValueError("infinite type")
        sub[t1.args[0]] = t2
        return sub
    if t2.kind == "Var":
        if occurs(t2.args[0], t1, sub): raise ValueError("infinite type")
        sub[t2.args[0]] = t1
        return sub
    if t1.kind == t2.kind:
        if t1.kind == "Tuple":
            if len(t1.args) != len(t2.args): raise ValueError("type mismatch")
            for a, b in zip(t1.args, t2.args):
                sub = unify(a, b, sub)
            return sub
        if t1.kind == "Func":
            sub = unify(t1.args[0], t2.args[0], sub)
            sub = unify(t1.args[1], t2.args[1], sub)
            return sub
        if t1.kind == "List":
            return unify(t1.args[0], t2.args[0], sub)
        if t1 != t2: raise ValueError("type mismatch")
    raise ValueError("type mismatch")

def substitute(t, sub):
    if t.kind == "Var" and t.args[0] in sub:
        return substitute(sub[t.args[0]], sub)
    if t.kind == "Func": return Type("Func", substitute(t.args[0], sub), substitute(t.args[1], sub))
    if t.kind == "List": return Type("List", substitute(t.args[0], sub))
    if t.kind == "Tuple": return Type("Tuple", *(substitute(a, sub) for a in t.args))
    return t

def instantiate(scheme):
    fvs, t = scheme
    sub = {v: fresh() for v in fvs}
    return substitute(t, sub)

def generalize(t, env_fvs):
    fvs = free_vars(t)
    quantified = fvs - env_fvs
    return (quantified, t)

