def branch_influence(n, edges, entry, exits, targets):
    # 1. Input Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for coll in (exits, targets):
        if not isinstance(coll, (list, tuple, set)):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
        for x in coll:
            if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
                raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # 2. Build Reachable Set R
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    R = set()
    q = [entry]
    R.add(entry)
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    # 3. Construct A-Graph
    # Nodes in A are those in R that can reach END.
    # END is virtual node n. Implicit edges from exits ∩ R to END.
    exit_set = set(exits) & R
    rev_adj = [[] for _ in range(n + 1)]  # n is END
    for u, v in edges:
        if u in R and v in R:
            rev_adj[v].append(u)
    for u in exit_set:
        rev_adj[n].append(u)  # implicit edge u -> END, so in rev: END -> u

    # BFS from END in rev_adj to find A
    A = set()
    q = [n]
    A.add(n)
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in rev_adj[u]:
            if v not in A:
                A.add(v)
                q.append(v)

    # Remove END from A for processing, keep it for tree structure
    A_nodes = sorted(A - {n})
    if not A_nodes:
        return ([], sorted(set(targets) - set(A_nodes)))

    # Build forward adj for A-graph
    a_adj = [[] for _ in n + 1]
    for u, v in edges:
        if u in A and v in A:
            a_adj[u].append(v)
    for u in exit_set:
        a_adj[u].append(n)

    # Precompute predecessors in A-graph
    a_preds = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in a_adj[u]:
            a_preds[v].append(u)

    # 4. Compute Post-Dominator Tree
    # Reverse edges for dominator computation from END
    rev_a_adj = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in a_adj[u]:
            rev_a_adj[v].append(u)

    # BFS/DFS order from END in rev graph
    order = []
    visited = set()
    stack = [n]
    visited.add(n)
    while stack:
        u = stack.pop()
        order.append(u)
        for v in rev_a_adj[u]:
            if v not in visited:
                visited.add(v)
                stack.append(v)
    order = order[::-1]  # reverse post-order

    idom = {n: n}
    depth = {n: 0}
    parent = {n: n}

    def intersect(u, v):
        while u != v:
            if depth.get(u, 0) < depth.get(v, 0):
                u, v = v, u
            u = parent.get(u, n)
            if u == v:
                return v
        return u

    for v in order:
        if v == n:
            continue
        preds = a_preds[v]
        if not preds:
            idom[v] = n
        else:
            d = preds[0]
            for p in preds[1:]:
                d = intersect(d, p)
            idom[v] = d
        depth[v] = depth[idom[v]] + 1
        parent[v] = idom[v]

    # 5. Linearize Post-Dominator Tree for subtree checks
    tin = {}
    tout = {}
    dfs_stack = [n]
    timer = [0]
    # Iterative DFS for tin/tout
    while dfs_stack:
        u = dfs_stack[-1]
        if u not in tin:
            tin[u] = timer[0]
            timer[0] += 1
            # Push children in reverse order for correct traversal
            children = [v for v in range(n + 1) if parent.get(v) == u]
            dfs_stack.extend(reversed(children))
        else:
            dfs_stack.pop()
            tout[u] = timer[0]

    # 6. Compute C Closure
    target_set = set(targets)
    T_in_A = target_set & set(A_nodes)
    C = set(T_in_A)
    queue = list(C)
    in_C = set(C)

    # Process edges to find control dependencies
    # We iterate over all edges in A-graph. For each x->v, 
    # find the deepest y in C that post-dominates v.
    # If such y exists and is not a strict ancestor of x, then x is CD on y.
    # We use a worklist approach: only check edges when new nodes are added to C.
    # To avoid O(E*|C|), we maintain a set of unprocessed edges or just scan once per new y.
    # Given constraints, scanning all edges per new y might be slow. 
    # Instead, we'll scan all edges once per iteration of the fixed point.

    changed = True
    while changed:
        changed = False
        # For each edge x->v in A-graph
        for u in range(n + 1):
            for v in a_adj[u]:
                if u in in_C:
                    continue
                # Find deepest y in C that is ancestor of v in PDT
                y = v
                found_y = None
                while y != n:
                    if y in in_C:
                        found_y = y
                        break
                    y = parent[y]

                if found_y is not None:
                    # Check control dependency condition
                    # y post-dominates v (true by construction)
                    # y does not strictly post-dominate x
                    strict = (found_y != u and tin[found_y] < tin[u] < tout[found_y])
                    if not strict:
                        in_C.add(u)
                        queue.append(u)
                        changed = True
                        # No need to check other edges for this u in this pass

    # 7. Return Results
    targets_not_in_A = sorted(target_set - set(A_nodes))
    return (sorted(in_C), targets_not_in_A)

