    visited.add(n)
    while stack:
        u = stack.pop()
        order.append(u)
        for v in rev_a_adj[u]:
            if v not in visited:
                visited.add(v)
                stack.append(v)
    order = order[::-1]  # reverse post-order

    idom = {n: n}
    depth = {n: 0}
    parent = {n: n}
    ancestor = {n: n}

    def intersect(u, v):
        while u != v:
            if depth[u] < depth[v]:
                u, v = v, u
            u = ancestor[u]
            if u == v:
                return v
        return u

    for v in order:
        if v == n:
            continue
        preds = a_preds[v]
        if not preds:
            idom[v] = n
        else:
            d = preds[0]
            for p in preds[1:]:
                d = intersect(d, p)
            idom[v] = d
        depth[v] = depth[idom[v]] + 1
        parent[v] = idom[v]
        ancestor[v] = v

    # 5. Linearize Post-Dominator Tree for subtree checks
    tin = {}
    tout = {}
    timer = [0]
    # Iterative DFS for tin/tout
    stack = [n]
    while stack:
        u = stack.pop()
        if u not in tin:
            tin[u] = timer[0]
            timer[0] += 1
            stack.append(u)  # push again to process after children
            # Push children in reverse order for correct traversal
            children = [v for v in range(n + 1) if parent.get(v) == u]
            stack.extend(reversed(children))
        else:
            tout[u] = timer[0]

    # 6. Compute C Closure
    target_set = set(targets)
    T_in_A = target_set & set(A_nodes)
    C = set(T_in_A)
    queue = list(C)
    in_C = set(C)

    # To efficiently find controllers, we use the property:
    # x is CD on y iff exists x->s such that y is ancestor of s in PDT,
    # and y is not a strict ancestor of x.
    # We iterate over edges and check against current C.
    # To avoid O(E*|C|), we maintain a worklist of newly added nodes to C,
    # and only scan edges when nodes are added. We also keep track of processed edges
    # to avoid redundant checks, but given the structure, a simple BFS over the
    # implicit CD graph is sufficient if we build it lazily or scan efficiently.
    # Given constraints, we'll scan all edges once per new node in C, but limit scans.
    # Actually, we can just scan all edges once and propagate.

    changed = True
    while changed:
        changed = False
        for u in range(n + 1):
            if u in in_C:
                continue
            # Check if u is CD on any y in in_C
            # u is CD on y if exists v in a_adj[u] such that y is ancestor of v in PDT
            # and y is not strict ancestor of u.
            # We find the highest y in in_C that is ancestor of some successor.
            best_y = None
            for v in a_adj[u]:
                if v == n:
                    continue
                # Find highest ancestor of v that is in in_C
                y = v
                while y != n:
                    if y in in_C:
                        if best_y is None or depth[y] > depth[best_y]:
                            best_y = y
                        break
                    y = parent[y]

            if best_y is not None:
                # Check strict post-dominance
                strict = (best_y != u and tin.get(best_y, 0) < tin.get(u, 0) < tout.get(best_y, 0))
                if not strict:
                    in_C.add(u)
                    queue.append(u)
                    changed = True

    # 7. Return Results
    targets_not_in_A = sorted(target_set - set(A_nodes))
    return (sorted(in_C), targets_not_in_A)

