        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for coll in (exits, targets):
        if not isinstance(coll, (list, tuple, set)):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
        for x in coll:
            if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
                raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # 2. Build Reachable Set R
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    R = set()
    q = [entry]
    R.add(entry)
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    # 3. Construct A-Graph
    exit_set = set(exits) & R
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        if u in R and v in R:
            rev_adj[v].append(u)
    for u in exit_set:
        rev_adj[n].append(u)  # implicit edge u -> END, so in rev: END -> u

    # BFS from END in rev_adj to find A
    A = set()
    q = [n]
    A.add(n)
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in rev_adj[u]:
            if v not in A:
                A.add(v)
                q.append(v)

    A_nodes = sorted(A - {n})
    if not A_nodes:
        return ([], sorted(set(targets) - set(A_nodes)))

