    a_adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        if u in A and v in A:
            a_adj[u].append(v)
    for u in exit_set:
        a_adj[u].append(n)

    # Precompute predecessors in A-graph
    a_preds = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in a_adj[u]:
            a_preds[v].append(u)

    # 4. Compute Post-Dominator Tree using Lengauer-Tarjan
    # Reverse edges for dominator computation from END
    rev_a_adj = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in a_adj[u]:
            rev_a_adj[v].append(u)

    # DFS from END in rev graph
    dfn = [-1] * (n + 1)
    node = [-1] * (n + 1)
    parent = [-1] * (n + 1)
    semi = list(range(n + 1))
    idom = list(range(n + 1))
    ancestor = list(range(n + 1))
    val = list(range(n + 1))
    bucket = [[] for _ in range(n + 1)]

    stack = [n]
    dfn[n] = 0
    node[0] = n
    cnt = 0
    while stack:
        u = stack.pop()
        cnt += 1
        for v in rev_a_adj[u]:
            if dfn[v] == -1:
                dfn[v] = cnt
                node[cnt] = v
                parent[v] = u
                stack.append(v)

    # Build pred list for LT
    pred = [[] for _ in range(n + 1)]
    for u in range(n + 1):
        for v in rev_a_adj[u]:
            if dfn[v] != -1:
                pred[v].append(u)

    def find(v):
        if ancestor[v] == v:
            return v
        res = find(ancestor[v])
        if dfn[semi[val[v]]] > dfn[semi[val[ancestor[v]]]]:
            val[v] = val[ancestor[v]]
        ancestor[v] = ancestor[v]
        return val[v]

    def link(u, v):
        ancestor[v] = u
        if dfn[semi[val[v]]] < dfn[semi[val[u]]]:
            val[v] = val[u]

    def lca(u, v):
        if dfn[u] > dfn[v]:
            u, v = v, u
        u = find(u)
        v = find(v)
        if dfn[u] < dfn[v]:
            u, v = v, u
        if u == v:
            return u
        return lca(ancestor[u], v)

    for i in range(len(node)-1, -1, -1):
        v = node[i]
        for u in pred[v]:
            if dfn[u] == -1:
                continue
            w = find(u)
            if dfn[semi[w]] < dfn[semi[v]]:
                semi[v] = semi[w]
        if parent[v] != -1:
            bucket[parent[v]].append(v)
            link(parent[v], v)
        for w in bucket[v]:
            if semi[find(w)] == v:
                idom[w] = v
            else:
                idom[w] = -1

    for i in range(1, len(node)):
        v = node[i]
        if idom[v] != -1 and semi[idom[v]] != semi[v]:
            idom[v] = idom[idom[v]]

    # 5. Linearize Post-Dominator Tree for subtree checks
    tin = {}
    tout = {}
    timer = [0]
    # Build children list for PDT
    pdt_children = [[] for _ in range(n + 1)]
    for v in range(n + 1):
        if idom[v] != -1:
            pdt_children[idom[v]].append(v)

    stack = [n]
    while stack:
        u = stack.pop()
        if u not in tin:
            tin[u] = timer[0]
            timer[0] += 1
            stack.append(u)
            stack.extend(reversed(pdt_children[u]))
        else:
            tout[u] = timer[0]

    # 6. Compute C Closure
    target_set = set(targets)
    T_in_A = target_set & set(A_nodes)
    C = set(T_in_A)
    queue = list(C)
    in_C = set(C)

    # Precompute children_idom: s such that idom[s] == y
    children_idom = [[] for _ in range(n + 1)]
    for s in A_nodes:
        y = idom[s]
        if y != -1 and y in A:
            children_idom[y].append(s)

    changed = True
    while changed:
        changed = False
        new_nodes = []
        for y in queue:
            for s in children_idom[y]:
                for x in a_preds[s]:
                    if x in in_C:
                        continue
                    # Check if x is not in subtree of y
                    if not (tin[y] < tin.get(x, -1) < tout[y]):
                        in_C.add(x)
                        new_nodes.append(x)
                        changed = True
        queue = new_nodes

    # 7. Return Results
    targets_not_in_A = sorted(target_set - set(A_nodes))
    return (sorted(in_C), targets_not_in_A)

