sys.setrecursionlimit(100000)

def branch_influence(n, edges, entry, exits, targets):
    # 1. Input Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1 (bool is not an int)")
