            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")

    for coll in [exits, targets]:
        if not hasattr(coll, '__iter__'):
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
        for x in coll:
            if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < n):
                raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # 2. Build Graph & Reachable Set R
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    R = set()
    q = deque([entry])
    R.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    # Filter to R and re-index for efficiency
    r_list = sorted(R)
    r_map = {old: new for new, old in enumerate(r_list)}
    m = len(R)
    adj_r = [[] for _ in range(m)]
    rev_adj_r = [[] for _ in range(m)]
    for u in R:
        nu = r_map[u]
        for v in adj[u]:
            if v in R:
                adj_r[nu].append(r_map[v])
                rev_adj_r[r_map[v]].append(nu)

    # 3. Add END node and build A-Graph
    END = m
    total_nodes = END + 1
    adj_a = [[] for _ in range(total_nodes)]
    rev_adj_a = [[] for _ in range(total_nodes)]

    for u in range(m):
        for v in adj_r[u]:
            adj_a[u].append(v)
            rev_adj_a[v].append(u)

    exits_in_r = [r_map[e] for e in exits if e in R]
    for eu in exits_in_r:
        adj_a[eu].append(END)
        rev_adj_a[END].append(eu)

    # Compute A: nodes that can reach END
    A_set = set()
    q = deque([END])
    A_set.add(END)
    while q:
        u = q.popleft()
        for v in rev_adj_a[u]:
            if v not in A_set:
                A_set.add(v)
                q.append(v)

    # Keep only A ∪ {END} and re-index
    a_list = sorted([u for u in range(m) if u in A_set] + [END])
    a_map = {old: new for new, old in enumerate(a_list)}
    total_a = len(a_list)
    adj_final = [[] for _ in range(total_a)]
    rev_adj_final = [[] for _ in range(total_a)]

    for u in a_list:
        nu = a_map[u]
        for v in adj_a[u]:
            if v in A_set:
                adj_final[nu].append(a_map[v])
                rev_adj_final[a_map[v]].append(nu)

    # 4. Compute Post-Dominators using Lengauer-Tarjan
    root = a_map[END]
    n_nodes = total_a

    parent = [0] * n_nodes
    semi = [0] * n_nodes
    idom = [0] * n_nodes
    ancestor = [0] * n_nodes
    val = [0] * n_nodes
    dfn = [-1] * n_nodes
    ndfn = [0] * n_nodes
    cnt = 0

    semi[:] = range(n_nodes)
    ancestor[:] = range(n_nodes)
    val[:] = range(n_nodes)

    def dfs(u):
        nonlocal cnt
        dfn[u] = cnt
        ndfn[cnt] = u
        cnt += 1
        for v in rev_adj_final[u]:
            if dfn[v] == -1:
                parent[v] = u
                dfs(v)
                semi[u] = min(semi[u], semi[v])
            else:
                semi[u] = min(semi[u], dfn[v])

    dfs(root)

    def evaluate(v):
        if ancestor[v] == v:
            return v
        parent_v = parent[v]
        evaluate(parent_v)
        if dfn[ancestor[parent_v]] < dfn[ancestor[v]]:
            ancestor[v] = ancestor[parent_v]
        ancestor[v] = parent[v]
        return ancestor[v]

    def link(v, w):
        parent[w] = v
        ancestor[w] = v
        val[w] = v

    for i in range(cnt - 1, 0, -1):
        w = ndfn[i]
        for v in rev_adj_final[w]:
            if dfn[v] != -1:
                semi[w] = min(semi[w], semi[evaluate(v)])
        p = parent[w]
        link(p, w)
        if semi[w] == dfn[w]:
            idom[w] = semi[w]
        else:
            idom[w] = semi[w]

    for i in range(1, cnt):
        w = ndfn[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

    idom_orig = {}
    for i in range(cnt):
        u_orig = a_list[i]
        idom_orig[u_orig] = a_list[idom[i]]

    # 5. Identify Control Dependencies
    ctrl_dep = {}
    for x in a_list:
        if x == END: continue
        nx = a_map[x]
        for s in adj_final[nx]:
            s_orig = a_list[s]
            if s_orig == END: continue
            y_orig = idom_orig[s_orig]
            if y_orig != x and y_orig in A_set:
                ctrl_dep.setdefault(y_orig, []).append(x)

    # 6. Build C Closure
    T_in_A = [t for t in targets if t in A_set]
    C = set()
    queue = deque(T_in_A)
    visited = set(T_in_A)

    while queue:
        z = queue.popleft()
        for x in ctrl_dep.get(z, []):
            if x not in C:
                C.add(x)
                queue.append(x)

    # 7. Collect targets not in A
    targets_not_in_A = sorted(list(set(targets) - A_set))

    return (sorted(C), targets_not_in_A)

