    targets_in_A = set(targets) & A_set
    C = set(targets_in_A)
    queue = list(C)
    while queue:
        y = queue.pop()
        for x in rev_cd[y]:
            if x not in C:
                C.add(x)
                queue.append(x)

    # 6. Targets not in A
    targets_not_in_A = sorted(set(targets) - A_set)

    return (sorted(C), targets_not_in_A)

