    reachable = [False] * n
    q = [entry]
    reachable[entry] = True
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    # 2. Construct A-Graph
    # Add virtual END node n
    adj_A = [[] for _ in range(n + 1)]
    rev_adj_A = [[] for _ in range(n + 1)]
    for u in range(n):
        if not reachable[u]:
            continue
        for v in adj[u]:
            if reachable[v]:
                adj_A[u].append(v)
                rev_adj_A[v].append(u)
    exits_set = set(exits)
    for e in exits_set:
        if reachable[e]:
            adj_A[e].append(n)
            rev_adj_A[n].append(e)

    # Find A: nodes that can reach END
    can_reach_end = [False] * (n + 1)
    q = [n]
    can_reach_end[n] = True
    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in rev_adj_A[u]:
            if not can_reach_end[v]:
                can_reach_end[v] = True
                q.append(v)

