    A_nodes = [i for i in range(n + 1) if can_reach_end[i]]
    A_set = set(A_nodes)
    adj_A_filtered = [[] for _ in range(n + 1)]
    rev_adj_A_filtered = [[] for _ in range(n + 1)]
    for u in A_nodes:
        for v in adj_A[u]:
            if v in A_set:
                adj_A_filtered[u].append(v)
                rev_adj_A_filtered[v].append(u)

    # 3. Compute Post-Dominators using Lengauer-Tarjan on reversed graph
    n_nodes = n + 1
    dfs_num = [-1] * n_nodes
    parent = [-1] * n_nodes
    semi = [0] * n_nodes
    ancestor = [0] * n_nodes
    best = [0] * n_nodes
    bucket = [[] for _ in range(n_nodes)]
    idom = [0] * n_nodes

    # DFS from END
    stack = [n]
    dfs_num[n] = 0
    order = []
    while stack:
        v = stack.pop()
        order.append(v)
        for u in rev_adj_A_filtered[v]:
            if dfs_num[u] == -1:
                dfs_num[u] = len(order)
                parent[u] = v
                stack.append(u)

    def eval(v):
        if ancestor[v] == v:
            return v
        else:
            w = eval(ancestor[v])
            if semi[best[v]] > semi[best[ancestor[v]]]:
                best[v] = best[ancestor[v]]
            ancestor[v] = w
            return w

    def link(v, w):
        ancestor[v] = w
        if semi[best[v]] < semi[best[w]]:
            best[v] = best[w]

    for v in reversed(order):
        if v == n:
            continue
        w = v
        while dfs_num[w] < dfs_num[ancestor[w]]:
            w = ancestor[w]
        if dfs_num[w] < dfs_num[ancestor[w]]:
            eval(v)
        semi[v] = semi[ancestor[v]]
        bucket[semi[v]].append(v)
        link(parent[v], v)
        for u in bucket[ancestor[v]]:
            w = eval(u)
            if semi[w] < semi[u]:
                semi[u] = semi[w]
        bucket[ancestor[v]] = []

    for v in reversed(order):
        if v == n:
            continue
        if semi[v] != parent[v]:
            idom[v] = idom[v]
        else:
            idom[v] = parent[v]

    for v in reversed(order):
        if v == n:
            continue
        if idom[v] != parent[v]:
            idom[v] = idom[idom[v]]

    # Post-dominator tree: idom[v] is immediate post-dominator of v
    tree = [[] for _ in range(n_nodes)]
    for v in A_nodes:
        if v != n:
            p = idom[v]
            if p in A_set:
                tree[p].append(v)

    # Compute entry/exit times for ancestry check
    entry_time = [0] * n_nodes
    exit_time = [0] * n_nodes
    timer = 0
    stack = [n]
    while stack:
        v = stack.pop()
        if entry_time[v] == 0:
            entry_time[v] = timer
            timer += 1
            for u in tree[v]:
                stack.append(u)
            exit_time[v] = timer - 1

    def is_ancestor(u, v):
        return entry_time[u] <= entry_time[v] and exit_time[u] >= exit_time[v]

    # 4. Control Dependencies
    rev_cd = [[] for _ in range(n_nodes)]
    for x in A_nodes:
        if x == n: continue
        for s in adj_A_filtered[x]:
            if s == n: continue
            y = idom[s]
            if y == x: continue
            if y not in A_set: continue
            if is_ancestor(y, x): continue
            rev_cd[y].append(x)

    # 5. Compute C closure
    targets_in_A = set(targets) & A_set
    C = set()
    # We need the smallest C satisfying the closure property.
    # This is equivalent to finding all ancestors in the control dependence graph from T.
    # We can just do a BFS/DFS backwards from T using rev_cd.
    queue = list(targets_in_A)
    visited = set(targets_in_A)
    while queue:
        y = queue.pop()
        for x in rev_cd[y]:
            if x not in visited:
                visited.add(x)
                C.add(x)
                queue.append(x)

    # 6. Targets not in A
    targets_not_in_A = sorted(set(targets) - A_set)

    return (sorted(C), targets_not_in_A)

