                all_names.add(name)
    for p in params:
        all_names.add(p)

    phi_map = {}

    for x in all_names:
        # D(x)
        D_x = {k for k in range(n) if x in node_defs[k]}
        if x in params:
            D_x.add(entry)

        if not D_x: continue

        # P(x) closure
        P_x = set(D_x)
        queue = list(D_x)
        while queue:
            d = queue.pop()
            for y in df[d]:
                if y not in P_x:
                    P_x.add(y)
                    queue.append(y)

        # LiveIn(x)
        def_nodes_x = D_x - {entry}
        exposed_uses = {k for k in range(n) if x in node_exposed_uses[k]}
        if not exposed_uses: continue

        live_in = set()
        q = list(exposed_uses)
        visited = set(q)
        live_in.update(q)
        while q:
            curr = q.pop()
            for pred in r_rev_adj[curr]:
                if pred not in visited and pred not in def_nodes_x:
                    visited.add(pred)
                    live_in.add(pred)
                    q.append(pred)

        phi_nodes = P_x & live_in
        if phi_nodes:
            for node in phi_nodes:
                if node not in phi_map:
                    phi_map[node] = []
                phi_map[node].append(x)

    final_results = []
    for node in sorted(phi_map.keys()):
        final_results.append((node, sorted(phi_map[node])))

    return final_results

import collections

def live_phi_sites(n, edges, entry, blocks, params):
    # Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be pairs of ints")
        if not all(isinstance(x, int) and not isinstance(x, bool) for x in e):
            raise ValueError("edges must be pairs of ints")
        if not (0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges must be pairs of ints in 0..n-1")
    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists/tuples")
        for inst in v:
            if not isinstance(inst, (list, tuple)) or len(inst) != 2:
                raise ValueError("instructions must be pairs")
            if inst[0] not in ("use", "def", "upd"):
                raise ValueError("op must be one of use, def, upd")
            if not isinstance(inst[1], str) or not inst[1]:
                raise ValueError("name must be a non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params must be non-empty str")

    # Reachability
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    reachable = set()
    queue = collections.deque([entry])
    reachable.add(entry)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                queue.append(v)

    # Build reachable subgraph
    r_adj = collections.defaultdict(list)
    r_pred = collections.defaultdict(list)
    for u in reachable:
        for v in adj[u]:
            if v in reachable:
                r_adj[u].append(v)
                r_pred[v].append(u)
    reachable_nodes = sorted(reachable)

    # Dominators (Lengauer-Tarjan)
    dfs_num = {u: -1 for u in reachable_nodes}
    semi = {u: u for u in reachable_nodes}
    idom = {u: u for u in reachable_nodes}
    ancestor = {u: u for u in reachable_nodes}
    bdsc = {u: [] for u in reachable_nodes}
    parent = {u: u for u in reachable_nodes}
    label = dict(reachable_nodes)

    stack = [entry]
    dfs_num[entry] = 0
    timer = 1
    dfs_order = []
    while stack:
        u = stack.pop()
        dfs_order.append(u)
        for v in r_adj[u]:
            if dfs_num[v] == -1:
                dfs_num[v] = timer
                timer += 1
                parent[v] = u
                stack.append(v)

    def eval(v):
        if ancestor[v] == v:
            return v
        else:
            u = eval(ancestor[v])
            if semi[bdsc[ancestor[v]][0]] < semi[bdsc[v][0]]:
                bdsc[v][0] = bdsc[ancestor[v]][0]
            ancestor[v] = ancestor[ancestor[v]]
            return bdsc[v][0]

    for i in range(len(dfs_order) - 1, 0, -1):
        v = dfs_order[i]
        min_semi = v
        for w in r_pred[v]:
            if dfs_num[w] == -1:
                continue
            if semi[w] < min_semi:
                min_semi = semi[w]
        semi[v] = min_semi

        ancestor[v] = parent[v]
        for w in bdsc[parent[v]]:
            if semi[w] < semi[eval(w)]:
                bdsc[w][0] = eval(w)
        bdsc[parent[v]].append(v)

    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        w = eval(v)
        if semi[w] == v:
            idom[v] = parent[v]
        else:
            idom[v] = w

    for i in range(1, len(dfs_order)):
        v = dfs_order[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

    # Dominance Frontier
    df = {u: set() for u in reachable_nodes}
    for v in reachable_nodes:
        for w in r_pred[v]:
            if semi[w] != semi[v]:
                df[semi[w]].add(v)

    # P(x) computation
    def compute_P(x):
        D = set()
        if x in params:
            D.add(entry)
        for u in reachable_nodes:
            if u in blocks:
                for op, name in blocks[u]:
                    if op in ("def", "upd") and name == x:
                        D.add(u)
                        break
        P = set(D)
        queue = collections.deque(list(D))
        while queue:
            u = queue.popleft()
            for y in df[u]:
                if y not in P:
                    P.add(y)
                    queue.append(y)
        return P

    # Liveness
    def compute_live_in(x):
        def_x = set()
        use_up_x = set()
        for u in reachable_nodes:
            if u in blocks:
                has_def = False
                for op, name in blocks[u]:
                    if name == x:
                        if op in ("def", "upd"):
                            has_def = True
                        elif op == "use":
                            if not has_def:
                                use_up_x.add(u)
                if has_def:
                    def_x.add(u)

        live_in = set()
        queue = collections.deque(list(use_up_x))
        live_in.update(use_up_x)
        while queue:
            u = queue.popleft()
            for p in r_pred[u]:
                if p not in def_x and p not in live_in:
                    live_in.add(p)
                    queue.append(p)
        return live_in

    # Combine
    result = []
    for x in sorted(set().union(*[set(b.keys()) for b in [list(blocks[u]) for u in reachable_nodes if u in blocks]] + [params])):
        if not x: continue
        P_x = compute_P(x)
        live_x = compute_live_in(x)
        phi_nodes = sorted(P_x & live_x)
        if phi_nodes:
            result.append((phi_nodes[0], [x])) # Placeholder, will group
            # Actually, group by node
            pass

    # Group by node
    phi_map = collections.defaultdict(set)
    for x in sorted(set().union(*[set(b.keys()) for b in [list(blocks[u]) for u in reachable_nodes if u in blocks]] + [params])):
        if not x: continue
        P_x = compute_P(x)
        live_x = compute_live_in(x)
        for u in P_x & live_x:
            phi_map[u].add(x)

    result = [(u, sorted(names)) for u, names in sorted(phi_map.items())]
    return result

import sys
from collections import deque

def live_phi_sites(n, edges, entry, blocks, params):
    # 1. Input Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry an int in 0..n-1")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges a list of pairs")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges pairs length 2")
        if not (isinstance(e[0], int) and not isinstance(e[0], bool)) or not (isinstance(e[1], int) and not isinstance(e[1], bool)):
            raise ValueError("edges ints in 0..n-1")
        if not (0 <= e[0] < n and 0 <= e[1] < n):
            raise ValueError("edges ints in 0..n-1")

    if not isinstance(blocks, dict):
        raise ValueError("blocks a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or isinstance(k, bool) or not (0 <= k < n):
            raise ValueError("blocks keys ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values list/tuple")
        for inst in v:
            if not isinstance(inst, (list, tuple)) or len(inst) != 2:
                raise ValueError("blocks instructions length 2")
            if inst[0] not in ('use', 'def', 'upd'):
                raise ValueError("blocks op one of three strings")
            if not isinstance(inst[1], str) or not inst[1]:
                raise ValueError("blocks name non-empty str")

    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params collection of str")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params non-empty str")

    # 2. Reachability
    succ = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u, v in edges:
        succ[u].append(v)
        pred[v].append(u)

    reachable = set()
    queue = deque([entry])
    reachable.add(entry)
    while queue:
        u = queue.popleft()
        for v in succ[u]:
            if v not in reachable:
                reachable.add(v)
                queue.append(v)

    reachable_succ = {u: [v for v in succ[u] if v in reachable] for u in reachable}
    reachable_pred = {v: [u for u in pred[v] if u in reachable] for v in reachable}

    # 3. Dominators (Lengauer-Tarjan)
    sys.setrecursionlimit(max(100000, n + 1000))
    num = [-1] * n
    node_at = [0] * n
    parent = [-1] * n
    semi = [-1] * n
    idom = [-1] * n
    bucket = [[] for _ in range(n)]
    ancestor = [-1] * n
    val = [-1] * n
    label = [-1] * n
    size = 0

    def dfs(u, d):
        nonlocal size
        num[u] = d
        node_at[d] = u
        size = max(size, d + 1)
        for v in reachable_succ[u]:
            if num[v] == -1:
                parent[v] = u
                dfs(v, d + 1)

    dfs(entry, 0)

    def eval(v):
        if ancestor[v] == -1:
            return v
        if label[v] == v:
            return v
        compress(v)
        return label[v]

    def compress(v):
        if ancestor[ancestor[v]] != -1:
            compress(ancestor[v])
            if num[semi[label[ancestor[v]]]] < num[semi[label[v]]]:
                label[v] = label[ancestor[v]]
            ancestor[v] = ancestor[ancestor[v]]

    def link(v, w):
        ancestor[v] = w
        if num[semi[label[v]]] < num[semi[label[w]]]:
            label[v] = label[w]

    for i in range(size - 1, 0, -1):
        u = node_at[i]
        for w in reachable_succ[u]:
            if num[w] != -1:
                if num[w] < num[u]:
                    if semi[w] == -1 or num[w] < num[semi[u]]:
                        semi[u] = w
                else:
                    w_val = eval(w)
                    if num[semi[w_val]] < num[semi[u]]:
                        semi[u] = semi[w_val]
        bucket[semi[u]].append(u)
        if parent[u] != -1:
            link(parent[u], u)
            for w in bucket[parent[u]]:
                w_val = eval(w)
                if num[semi[w_val]] == num[semi[w]]:
                    idom[w] = w_val
                else:
                    idom[w] = semi[w_val]
            bucket[parent[u]] = []

    for i in range(1, size):
        u = node_at[i]
        if idom[u] != semi[u]:
            idom[u] = idom[idom[u]]
    idom[entry] = entry

    # 4. Dominance Frontier
    df = [set() for _ in range(n)]
    for v in reachable:
        for u in reachable_pred[v]:
            w = u
            while w != idom[v]:
                df[w].add(v)
                w = idom[w]

    # 5. Definitions per variable
    defs = {}
    for u in reachable:
        if u in blocks:
            for op, name in blocks[u]:
                if op in ('def', 'upd'):
                    if name not in defs:
                        defs[name] = set()
                    defs[name].add(u)

    for x in params:
        if x not in defs:
            defs[x] = set()
        defs[x].add(entry)

    all_vars = set(defs.keys())

    # 6. Upward-exposed uses
    upward_exposed = [set() for _ in range(n)]
    for u in reachable:
        if u in blocks:
            defined = set()
            for op, name in blocks[u]:
                if op in ('use', 'upd') and name not in defined:
                    upward_exposed[u].add(name)
                if op in ('def', 'upd'):
                    defined.add(name)

    # 7. P(x) and Live-In
    phi_candidates = []

    for x in all_vars:
        # P(x) closure
        p_x = set(defs[x])
        changed = True
        while changed:
            changed = False
            new_nodes = set()
            for node in p_x:
                new_nodes |= df[node]
            if not new_nodes.issubset(p_x):
                p_x |= new_nodes
                changed = True

        # Live-In(x)
        # Params do not affect liveness, so exclude entry from def/upd set for traversal
        defs_for_liveness = defs[x] - {entry} if x in params else defs[x]

        live_in_x = set()
        queue = deque([w for w in reachable if x in upward_exposed[w]])
        live_in_x.update(queue)
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for p in reachable_pred[u]:
                if p not in live_in_x and x not in defs_for_liveness:
                    live_in_x.add(p)
                    queue.append(p)

        # Combine
        needed = p_x & live_in_x
        for node in needed:
            phi_candidates.append((node, x))

    # 8. Format output
    phi_candidates.sort(key=lambda t: (t[0], t[1]))
    result = []
    if phi_candidates:
        current_node = phi_candidates[0][0]
        current_names = [phi_candidates[0][1]]
        for node, name in phi_candidates[1:]:
            if node == current_node:
                current_names.append(name)
            else:
                result.append((current_node, current_names))
                current_node = node
                current_names = [name]
        result.append((current_node, current_names))

    return result

