from collections import deque

def live_phi_sites(n, edges, entry, blocks, params):
    # 1. Input Validation
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or entry < 0 or entry >= n:
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list of pairs")
    for u, v in edges:
        if not isinstance(u, int) or not isinstance(v, int) or u < 0 or u >= n or v < 0 or v >= n:
            raise ValueError("edges must contain ints in 0..n-1")
    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or k < 0 or k >= n:
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be list/tuple")
        for op, name in v:
            if op not in ("use", "def", "upd"):
                raise ValueError("op must be one of 'use', 'def', 'upd'")
            if not isinstance(name, str) or not name:
                raise ValueError("name must be a non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a list, tuple, set or frozenset")
    params_set = set(params)
    for p in params_set:
        if not isinstance(p, str) or not p:
            raise ValueError("params must contain non-empty str")

    # 2. Reachability
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    reachable = [False] * n
    queue = deque([entry])
    reachable[entry] = True
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    reachable_nodes = [i for i in range(n) if reachable[i]]
    if not reachable_nodes:
        return []

    r_adj = [[] for _ in range(n)]
    r_pred = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in adj[u]:
            if reachable[v]:
                r_adj[u].append(v)
                r_pred[v].append(u)

    # 3. Dominators (Lengauer-Tarjan)
    # Iterative DFS to get postorder and parent pointers
    parent = [n] * n
    dfs_stack = [(entry, iter(r_adj[entry]))]
    visited_dfs = [False] * n
    visited_dfs[entry] = True
    post_order = []
    while dfs_stack:
        u, children = dfs_stack[-1]
        try:
            v = next(children)
            if not visited_dfs[v]:
                visited_dfs[v] = True
                parent[v] = u
                dfs_stack.append((v, iter(r_adj[v])))
        except StopIteration:
            post_order.append(u)
            dfs_stack.pop()

    order = list(reversed(post_order))
    pos = {u: i for i, u in enumerate(order)}

    semi = list(range(n))
    idom = [n] * n
    bucket = [[] for _ in range(n)]
    ancestor = [n] * n
    val = list(range(n))
    label = list(range(n))

    def link(u, v):
        ancestor[v] = u
        val[v] = v
        label[v] = v

    def eval_node(v):
        if ancestor[v] == n:
            return v
        if pos.get(label[ancestor[v]], -1) < pos.get(label[val[v]], -1):
            label[v] = label[val[v]]
        if ancestor[v] != n:
            label[v] = eval_node(ancestor[v])
        return label[v]

    for u in order:
        for v in r_pred[u]:
            if pos.get(v, -1) > pos[u]:
                continue
            w = v
            while pos.get(ancestor[w], -1) > pos[u]:
                w = ancestor[w]
            if pos.get(semi[w], -1) < pos.get(semi[u], -1):
                semi[u] = semi[w]
        if u != entry:
            bucket[ancestor[u]].append(u)
            link(parent[u], u)

    for u in order:
        for v in bucket[u]:
            w = eval_node(v)
            if pos.get(semi[w], -1) < pos.get(semi[v], -1):
                idom[v] = w
            else:
                idom[v] = u
        bucket[u] = []

    # 4. Dominance Frontier
    dom_children = [[] for _ in range(n)]
    for u in reachable_nodes:
        if u != entry:
            dom_children[idom[u]].append(u)

    DF = [set() for _ in range(n)]
    for u in reachable_nodes:
        for v in dom_children[u]:
            w = v
            while w != u:
                DF[w].add(u)
                w = idom[w]

    # 5. D(x) and P(x)
    defs = {}
    for u in reachable_nodes:
        if u in blocks:
            for op, name in blocks[u]:
                if op in ("def", "upd"):
                    defs.setdefault(name, set()).add(u)
    for p in params_set:
        defs.setdefault(p, set()).add(entry)

    P = {}
    for x, d_set in defs.items():
        P_x = set(d_set)
        while True:
            new_nodes = set()
            for d in P_x:
                new_nodes.update(DF[d])
            P_x.update(new_nodes)
            if not new_nodes - P_x:
                break
        P[x] = P_x

    # 6. Upward-exposed uses
    exposed_uses = {x: set() for x in P}
    for u in reachable_nodes:
        if u in blocks:
            defined = set()
            for op, name in blocks[u]:
                if name not in defined:
                    if op == "use":
                        if name in P:
                            exposed_uses[name].add(u)
                    elif op in ("def", "upd"):
                        defined.add(name)

    # 7. Live-in analysis
    live_in = {}
    for x in P:
        if not exposed_uses[x]:
            continue
        # Blockers: nodes that define x, except entry if x is a param (params don't affect liveness)
        blockers = defs.get(x, set())
        if x in params_set:
            blockers = blockers - {entry}

        q = deque(exposed_uses[x])
        live_set = set(exposed_uses[x])
        while q:
            curr = q.popleft()
            for pred in r_pred[curr]:
                if pred not in live_set and pred not in blockers:
                    live_set.add(pred)
                    q.append(pred)
        live_in[x] = live_set

    # 8. Combine P(x) and live-in(x)
    result = []
    for x in P:
        phi_nodes = P[x] & live_in.get(x, set())
        for u in phi_nodes:
            result.append((u, x))

    out = {}
    for u, x in result:
        out.setdefault(u, []).append(x)

    final = []
    for u in sorted(out.keys()):
        final.append((u, sorted(out[u])))

    return final

