        rev_adj[v].append(u)

    # 3. Reachability Analysis
    reachable = set()
    queue = deque([entry])
    reachable.add(entry)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in reachable:
                reachable.add(v)
                queue.append(v)

    # Filter to reachable only
    adj = {u: [v for v in adj[u] if v in reachable] for u in reachable}
    rev_adj = {u: [v for v in rev_adj[u] if v in reachable] for u in reachable}
