                    semi[w] = val[v]
        bucket[semi[w]].append(w)
        if parent[w] != -1:
            link(parent[w], w)

    for i in range(1, idx):
        w = rev[i]
        for b in bucket[w]:
            find(b)
            if semi[val[b]] < semi[w]:
                idom[b] = val[b]
            else:
