    results = {}

    for x in all_vars:
        # D(x)
        D_x = set()
        for u in reachable:
            if u in blocks:
                for op, var in blocks[u]:
                    if var == x and op in ("def", "upd"):
                        D_x.add(u)
        if x in params:
            D_x.add(entry)

        # P(x) closure
        P_x = set(D_x)
        worklist = list(D_x)
        while worklist:
            d = worklist.pop()
            for y in df.get(d, []):
                if y not in P_x:
                    P_x.add(y)
                    worklist.append(y)

        # Uses(x) - upward exposed uses
        Uses_x = set()
        for u in reachable:
            if u in blocks:
                seen = set()
                for op, var in blocks[u]:
                    if var == x:
                        if op in ("use", "upd"):
                            if var not in seen:
                                Uses_x.add(u)
                        if op in ("def", "upd"):
                            seen.add(var)

        # LiveIn(x)
        LiveIn_x = set(Uses_x)
        queue = deque(Uses_x)
        while queue:
            u = queue.popleft()
            for p in rev_adj[u]:
                if p not in LiveIn_x and p not in D_x:
                    LiveIn_x.add(p)
                    queue.append(p)

        # Combine
        phi_nodes = P_x & LiveIn_x
        if phi_nodes:
            results.update({node: {x} for node in phi_nodes})

    # 8. Format Output
    output = []
    for node in sorted(results.keys()):
        names = sorted(results[node])
        output.append((node, names))
    return output

