            if inst[0] not in ("use", "def", "upd"):
                raise ValueError("op must be one of use, def, upd")
            if not inst[1]:
                raise ValueError("name must be non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection of strings")
    for p in params:
        if type(p) is not str or not p:
            raise ValueError("params must be non-empty strings")

    # 2. Build Adjacency Lists
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # 3. Reachability Analysis
    reachable = [False] * n
    queue = deque([entry])
    reachable[entry] = True
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    # Filter blocks to reachable nodes only
    blocks = {u: blocks[u] for u in range(n) if reachable[u] and u in blocks}

    # 4. Dominators (Lengauer-Tarjan Iterative)
    num = [-1] * n
    rev = {}
    parent = [-1] * n
    semi = [-1] * n
    idom = [-1] * n
    ancestor = [-1] * n
    val = [-1] * n
    bucket = [[] for _ in range(n)]

    stack = [entry]
    num[entry] = 0
    rev[0] = entry
    idx = 1
    while stack:
        u = stack[-1]
        found = False
        for v in adj[u]:
            if num[v] == -1:
                num[v] = idx
                rev[idx] = v
                parent[v] = u
                idx += 1
                stack.append(v)
                found = True
                break
        if not found:
            stack.pop()

    for i in range(idx):
        semi[rev[i]] = rev[i]
        val[rev[i]] = rev[i]

