        path = []
        curr = v
        while ancestor[curr] != -1 and ancestor[ancestor[curr]] != -1:
            path.append(curr)
            curr = ancestor[curr]
        for node in reversed(path):
            if semi[val[ancestor[node]]] < semi[val[node]]:
                val[node] = val[ancestor[node]]
            ancestor[node] = ancestor[ancestor[node]]
        return val[v]

    def link(v, w):
        ancestor[v] = w
        bucket[w].append(v)

    for i in range(idx - 1, 0, -1):
        w = rev[i]
        for v in adj[w]:
            if num[v] != -1:
                if semi[val[v]] < semi[w]:
                    semi[w] = val[v]
        bucket[semi[w]].append(w)
        if parent[w] != -1:
            link(parent[w], w)

