        w = rev[i]
        for b in bucket[w]:
            find(b)
            if semi[val[b]] < semi[w]:
                idom[b] = val[b]
            else:
                idom[b] = w
        bucket[semi[w]].append(w)
        if parent[w] != -1:
            link(parent[w], w)

    for i in range(1, idx):
        w = rev[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]
    idom[entry] = entry

    # 5. Dominance Frontiers
    df = [set() for _ in range(n)]
    for y in range(n):
        if not reachable[y]: continue
        for p in rev_adj[y]:
            if not reachable[p]: continue
            if p != idom[y]:
                w = p
                while w != idom[y]:
                    df[w].add(y)
                    w = idom[w]

    # 6. Collect all variables
    all_vars = set(params)
    for u in blocks:
        for op, var in blocks[u]:
            if op in ("use", "def", "upd"):
                all_vars.add(var)

    results = {}

    # 7. Compute D(x), P(x), Uses(x), LiveIn(x) for each variable
    for x in all_vars:
        # D(x)
        D_x = set()
        for u in blocks:
            for op, var in blocks[u]:
                if var == x and op in ("def", "upd"):
                    D_x.add(u)
        if x in params:
            D_x.add(entry)

        # P(x) closure
        P_x = set(D_x)
        worklist = list(D_x)
        while worklist:
            d = worklist.pop()
            for y in df[d]:
                if y not in P_x:
                    P_x.add(y)
                    worklist.append(y)

        # Uses(x) - upward exposed uses
        Uses_x = set()
        for u in blocks:
            seen = set()
            for op, var in blocks[u]:
                if var == x:
                    if op in ("use", "upd"):
                        if var not in seen:
                            Uses_x.add(u)
                    if op in ("def", "upd"):
                        seen.add(var)

        # LiveIn(x)
        # The implicit assignment of a param does not affect liveness, so we ignore entry in D_x for BFS
        D_x_live = D_x.copy()
        if x in params:
            D_x_live.discard(entry)

        LiveIn_x = set(Uses_x)
        q = deque(Uses_x)
        while q:
            u = q.popleft()
            for p in rev_adj[u]:
                if p not in LiveIn_x and p not in D_x_live:
                    LiveIn_x.add(p)
                    q.append(p)

        # Combine
        phi_nodes = P_x & LiveIn_x
        if phi_nodes:
            for node in phi_nodes:
                results.setdefault(node, set()).add(x)

    # 8. Format Output
    output = []
    for node in sorted(results.keys()):
        output.append((node, sorted(results[node])))
    return output

