def format_sigfigs(s, sig, mode):
    allowed_modes = {
        "nearest_even", "nearest_away", "nearest_zero",
        "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"
    }

    # 1. Input Validation
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if len(s) > 100000:
        raise ValueError("s length exceeds 100000")
    if not isinstance(sig, int) or isinstance(sig, bool):
        raise ValueError("sig must be an int")
    if not (1 <= sig <= 2000):
        raise ValueError("sig must be between 1 and 2000")
    if mode not in allowed_modes:
        raise ValueError("invalid mode")

    # 2. Parse Mantissa and Exponent
    e_idx = s.find('e')
    if e_idx == -1:
        e_idx = s.find('E')

    if e_idx == -1:
        mantissa_part = s
        exp_str = ""
    else:
        mantissa_part = s[:e_idx]
        exp_str = s[e_idx+1:]

    if not mantissa_part:
        raise ValueError("invalid mantissa")

    # Extract sign and digits
    sign = 1
    if mantissa_part[0] == '-':
        sign = -1
        num_part = mantissa_part[1:]
    elif mantissa_part[0] == '+':
        num_part = mantissa_part[1:]
    else:
        num_part = mantissa_part

    if not num_part:
        raise ValueError("invalid mantissa")
    if num_part.count('.') > 1:
        raise ValueError("invalid mantissa format")
    if not all(c in '0123456789.' for c in num_part):
        raise ValueError("non-ASCII or invalid characters in mantissa")

    # Locate decimal point
    dot_idx = num_part.find('.')
    if dot_idx == -1:
        dot_idx = len(num_part)

    # Extract digits
    digits = [int(c) for c in num_part if c != '.']

    # Parse exponent
    exp_val = 0
    if exp_str:
        if exp_str[0] in '+-':
            exp_sign_char = exp_str[0]
            exp_digits_str = exp_str[1:]
        else:
            exp_sign_char = '+'
            exp_digits_str = exp_str

        if not exp_digits_str or len(exp_digits_str) > 10 or not all(c in '0123456789' for c in exp_digits_str):
            raise ValueError("invalid exponent")
        exp_val = int(exp_digits_str)
        if exp_sign_char == '-':
            exp_val = -exp_val

    # 3. Determine Significant Digits & Exponent
    first_nz = next((i for i, d in enumerate(digits) if d != 0), None)

    # Handle zero case
    if first_nz is None:
        exp_str_out = "+00"
        if sig == 1:
            return f"0{exp_str_out}"
        else:
            return f"0.{ '0'*(sig-1) }{exp_str_out}"

    # Exponent of the first significant digit
    exp_first = exp_val + dot_idx - 1 - first_nz

    available = len(digits) - first_nz

    # Extract the sig digits we will keep
    res_digits = digits[first_nz : first_nz + sig]
    # Pad with zeros if input has fewer significant digits than requested
    if len(res_digits) < sig:
        res_digits.extend([0] * (sig - len(res_digits)))

    dropped = digits[first_nz + sig :]

    # 4. Analyze Dropped Part
    is_zero = len(dropped) == 0
    is_tie = False
    is_more = False

    if not is_zero:
        if dropped[0] < 5:
            pass  # less than half
        elif dropped[0] > 5:
            is_more = True
        else:  # dropped[0] == 5
            if all(d == 0 for d in dropped[1:]):
                is_tie = True
            else:
                is_more = True

    # 5. Determine Rounding Direction
    need_round_up = False
    if mode == "toward_zero":
        need_round_up = False
    elif mode == "away_zero":
        need_round_up = not is_zero
    elif mode == "toward_neg":  # floor
        if sign > 0:
            need_round_up = False
        else:
            need_round_up = not is_zero
    elif mode == "toward_pos":  # ceiling
        if sign > 0:
            need_round_up = not is_zero
        else:
            need_round_up = False
    elif mode == "nearest_even":
        if is_more:
            need_round_up = True
        elif is_tie:
            need_round_up = (res_digits[-1] % 2 == 1)
        else:
            need_round_up = False
    elif mode == "nearest_away":
        if is_more or is_tie:
            need_round_up = True
        else:
            need_round_up = False
    elif mode == "nearest_zero":
        if is_more:
            need_round_up = True
        else:
            need_round_up = False
    elif mode == "zero_five":
        if not is_zero and res_digits[-1] in (0, 5):
            need_round_up = True
        else:
            need_round_up = False

    # 6. Apply Rounding & Carry
    if need_round_up:
        i = len(res_digits) - 1
        while i >= 0:
            res_digits[i] += 1
            if res_digits[i] < 10:
                break
            res_digits[i] = 0
            i -= 1
        if i < 0:
            # Carry overflowed all digits, e.g., 99 -> 100
            res_digits.insert(0, 1)
            exp_first += 1
            # Keep exactly sig digits for output (drop the last one if carry increased length)
            res_digits = res_digits[:sig]

    # 7. Format Output
    if sign < 0:
        sign_str = "-"
    else:
        sign_str = ""

    # Format exponent with at least 2 digits
    exp_str_out = f"{exp_first:+02d}"

    # Validate exponent range
    if not (-999999999 <= exp_first <= 999999999):
        raise ValueError("exponent out of range")

    if sig == 1:
        return f"{sign_str}{res_digits[0]}{exp_str_out}"
    else:
        rest_str = ''.join(map(str, res_digits[1:]))
        return f"{sign_str}{res_digits[0]}.{rest_str}{exp_str_out}"

