def snap_to_step(x: str, step: str, mode: str) -> str:
    """
    Rounds an exact decimal x to a multiple of an exact decimal step.
    """
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("Inputs must be strings")

    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input string too long")

    valid_modes = {"floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError(f"Invalid mode: {mode}")

    def parse_decimal(s):
        if not s:
            raise ValueError("Empty string")
        sign = 1
        if s[0] in '+-':
            sign = -1 if s[0] == '-' else 1
            s = s[1:]
        if not s:
            raise ValueError("No digits after sign")

        sci_exp = 0
        if 'e' in s or 'E' in s:
            idx = s.index('e') if 'e' in s else s.index('E')
            s_part = s[:idx]
            exp_part = s[idx+1:]
            if not exp_part:
                raise ValueError("Missing exponent")
            try:
                sci_exp = int(exp_part)
            except ValueError:
                raise ValueError("Invalid exponent")
            s = s_part
        else:
            s = s

        if not s:
            raise ValueError("No digits before exponent")

        if s.count('.') > 1:
            raise ValueError("Invalid decimal format")

        if '.' in s:
            int_part, frac_part = s.split('.')
            if not int_part and not frac_part:
                raise ValueError("Invalid decimal format")
            if not int_part:
                int_part = "0"
            if not frac_part:
                frac_part = "0"
            digits = int_part + frac_part
            dec_exp = -len(frac_part)
        else:
            digits = s
            dec_exp = 0

        if not digits or not digits.isdigit():
            raise ValueError("Invalid digits")

        digits = digits.lstrip('0')
        if not digits:
            digits = "0"

        mantissa = int(digits)
        exponent = sci_exp + dec_exp
        return sign, mantissa, exponent

    def format_result(k, m_s, e_s):
        d = max(0, -e_s)
        V = k * m_s

        if V == 0:
            return "0." + "0"*d if d > 0 else "0"

        abs_V = -V if V < 0 else V
        s_abs = str(abs_V)

        # Size limit check: integer part length + d <= 3000
        int_len = max(1, len(s_abs) - d) if d > 0 else len(s_abs)
        if int_len + d > 3000:
            raise ValueError("Result too large")

        sign = "-" if V < 0 else ""

        if d == 0:
            res = s_abs
        elif len(s_abs) <= d:
            res = "0." + "0" * (d - len(s_abs)) + s_abs
        else:
            res = s_abs[:-d] + "." + s_abs[-d:]

        return sign + res

    try:
        sgn_x, m_x, e_x = parse_decimal(x)
        sgn_s, m_s, e_s = parse_decimal(step)
    except ValueError:
        raise

    if m_s == 0:
        raise ValueError("Step must be > 0")

    delta_e = e_x - e_s

    if delta_e >= 0:
        num = sgn_x * m_x * (10 ** delta_e)
        den = m_s
    else:
        num = sgn_x * m_x
        den = m_s * (10 ** (-delta_e))

    q = num // den
    r = num % den

    k = q
    if r == 0:
        pass
    else:
        cmp = 2 * r - den
        if mode == "floor":
            k = q
        elif mode == "ceil":
            k = q + 1
        elif mode == "outward":
            k = q + 1 if sgn_x == 1 else q
        elif mode == "inward":
            k = q if sgn_x == 1 else q + 1
        elif mode == "tie_even":
            if cmp < 0: k = q
            elif cmp > 0: k = q + 1
            else: k = q if q % 2 == 0 else q + 1
        elif mode == "tie_odd":
            if cmp < 0: k = q
            elif cmp > 0: k = q + 1
            else: k = q if q % 2 != 0 else q + 1
        elif mode == "tie_away":
            if cmp < 0: k = q
            elif cmp > 0: k = q + 1
            else: k = q + 1 if sgn_x == 1 else q
        elif mode == "tie_zero":
            if cmp < 0: k = q
            elif cmp > 0: k = q + 1
            else: k = q if sgn_x == 1 else q + 1

    return format_result(k, m_s, e_s)

import re

def snap_to_step(x: str, step: str, mode: str) -> str:
    # Validate types
    if not isinstance(x, str) or not isinstance(step, str) or not isinstance(mode, str):
        raise ValueError("Inputs must be strings")

    # Validate length
    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input string exceeds 4000 characters")

    # Validate mode
    valid_modes = {"floor", "ceil", "outward", "inward", "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    # Parse decimal string helper
    def parse_decimal(s):
        # Returns (sign, mantissa_int, exponent_int) where value = sign * mantissa_int * 10^exponent_int
        # Mantissa contains all digits. Exponent accounts for decimal point and explicit exponent.
        m = re.match(r'^([+-]?)(\d+)(?:\.(\d*))?([eE]([+-]?\d+))?$', s)
        if not m:
            raise ValueError("Invalid decimal format")

        sign = -1 if m.group(1) == '-' else 1
        mantissa = int(m.group(2))
        dec_places = len(m.group(3)) if m.group(3) is not None else 0
        exp_val = int(m.group(5)) if m.group(5) is not None else 0

        exponent = exp_val - dec_places
        return sign, mantissa, exponent

    # Parse x and step
    sign_x, M_x, E_x = parse_decimal(x)
    sign_s, M_s, E_s = parse_decimal(step)

    # Step must be strictly positive
    if sign_s == -1 or M_s == 0:
        raise ValueError("Step must be greater than zero")

    # Compute m and e for step formatting
    m_step = M_s
    e_step = E_s
    while m_step % 10 == 0:
        m_step //= 10
        e_step += 1
    d = max(0, -e_step)

    # Compute ratio x / step = N / D
    diff = E_x - E_s
    if diff >= 0:
        N = sign_x * M_x * (10 ** diff)
        D = M_s
    else:
        N = sign_x * M_x
        D = M_s * (10 ** (-diff))

    # Integer division and remainder (Python's // and % follow floor division)
    q = N // D
    r = N % D

    # Determine k
    if mode in ("floor", "ceil", "outward", "inward"):
        if mode == "floor":
            k = q
        elif mode == "ceil":
            k = q + 1
        elif mode == "outward":
            k = q + 1 if q >= 0 else q
        elif mode == "inward":
            k = q if q >= 0 else q + 1
    else:
        # Tie_* modes: pick closer, then resolve tie
        if 2 * r < D:
            k = q
        elif 2 * r > D:
            k = q + 1
        else:
            # Exact tie
            if mode == "tie_even":
                k = q if q % 2 == 0 else q + 1
            elif mode == "tie_odd":
                k = q + 1 if q % 2 == 0 else q
            elif mode == "tie_away":
                k = q + 1 if q >= 0 else q
            elif mode == "tie_zero":
                k = q if q >= 0 else q + 1

    # Compute result value
    val = k * M_s

    # Format result
    if val == 0:
        if d == 0:
            return "0"
        return "0." + "0" * d

    sign_str = "-" if val < 0 else ""
    abs_val = abs(val)
    s = str(abs_val)

    if d == 0:
        result_str = sign_str + s
    else:
        if len(s) <= d:
            s = "0" * (d - len(s) + 1) + s
        int_part = s[:-d]
        frac_part = s[-d:]
        result_str = sign_str + int_part + "." + frac_part

    # Size limit check
    # Integer part length + d must be <= 3000
    if len(int_part) + d > 3000:
        raise ValueError("Output exceeds 3000 digits")

    return result_str

