    if len(x) > 4000 or len(step) > 4000:
        raise ValueError("Input string too long")

    valid_modes = {"floor", "ceil", "outward", "inward", 
                   "tie_even", "tie_odd", "tie_away", "tie_zero"}
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    def _parse(s):
        if not s:
            raise ValueError("Empty string")
        sign = 1
        if s[0] == '+':
            s = s[1:]
        elif s[0] == '-':
            sign = -1
            s = s[1:]
        if not s:
            raise ValueError("No digits")

        exp_offset = 0
        e_idx = -1
        for i, ch in enumerate(s):
            if ch in 'eE':
                e_idx = i
                break

        if e_idx != -1:
            exp_str = s[e_idx+1:]
            s = s[:e_idx]
            if not exp_str:
                raise ValueError("Missing exponent")
            digits_only = exp_str.lstrip('+-')
            if not digits_only or not digits_only.isdigit() or len(digits_only) > 10:
                raise ValueError("Invalid exponent")
            exp_offset = int(exp_str)
        else:
            if not s.replace('.', '').isdigit():
                raise ValueError("Invalid digits")

        if '.' in s:
            dot_idx = s.find('.')
            int_part = s[:dot_idx]
            frac_part = s[dot_idx+1:]
            if not int_part and not frac_part:
                raise ValueError("Only decimal point")
            digits = (int_part if int_part else '0') + frac_part
            frac_len = len(frac_part)
        else:
            digits = s
            if not digits.isdigit():
                raise ValueError("Invalid digits")
            frac_len = 0

        if not digits or not digits.isdigit():
            raise ValueError("Invalid digits")

        mantissa = int(digits)
        exponent = exp_offset - frac_len
        return sign, mantissa, exponent

    try:
        sx, mx, ex = _parse(x)
        _, ms, es = _parse(step)
    except ValueError:
        raise ValueError("Invalid input format")

    if ms == 0:
        raise ValueError("Step must be greater than zero")

    delta = ex - es

    if delta > 3005:
        raise ValueError("Result exceeds 3000 digits")
    elif delta < -3005:
        q, r = 0, mx
    else:
        if delta >= 0:
            numerator = mx * (10 ** delta)
            q, r = divmod(numerator, ms)
        else:
            denominator = ms * (10 ** (-delta))
            q, r = divmod(mx, denominator)

    D = ms * (10 ** max(0, -delta))

    if r == 0:
        k = sx * q
    else:
        if sx == 1:
            k_floor = q
            k_ceil = q + 1
        else:
            k_floor = -q - 1
            k_ceil = -q

        if mode in ("floor", "ceil", "outward", "inward"):
            if mode == "floor":
                k = k_floor
            elif mode == "ceil":
                k = k_ceil
            elif mode == "outward":
                k = k_ceil if sx == 1 else k_floor
            elif mode == "inward":
                k = k_floor if sx == 1 else k_ceil
        else:
            if 2 * r > D:
                k = k_ceil
            elif 2 * r < D:
                k = k_floor
            else:
                if mode == "tie_even":
                    k = k_floor if k_floor % 2 == 0 else k_ceil
                elif mode == "tie_odd":
                    k = k_floor if k_floor % 2 != 0 else k_ceil
                elif mode == "tie_away":
                    k = k_ceil if sx == 1 else k_floor
                elif mode == "tie_zero":
                    k = k_floor if sx == 1 else k_ceil

    val = k * ms
    d = max(0, -es)

    if val == 0:
        res_str = "0" + ("." + "0"*d if d > 0 else "")
    else:
        abs_val_str = str(abs(val))
        if d == 0:
            res_str = abs_val_str
        else:
            if len(abs_val_str) <= d:
                res_str = '0.' + '0' * (d - len(abs_val_str)) + abs_val_str
            else:
                split_idx = len(abs_val_str) - d
                res_str = abs_val_str[:split_idx] + '.' + abs_val_str[split_idx:]
        if val < 0:
            res_str = "-" + res_str

    clean_res = res_str.lstrip('-').replace('.', '')
    if len(clean_res) > 3000:
        raise ValueError("Result exceeds 3000 digits")

    return res_str
